// V31.5.8.60.3.9.38 - Bot typing indicator internal-test fix:
// Show WhatsApp "typing..." briefly before bot replies to customer messages.
// This is intentionally used only for inbound customer webhook messages, not staff sends,
// staff notifications, templates, reminders, or follow-up cron jobs.
// Internal/staff test numbers are now allowed to see typing too, because they are often used for bot testing.
const BOT_TYPING_INDICATOR_ENABLED = (process.env.BOT_TYPING_INDICATOR_ENABLED || "true").toString().toLowerCase() !== "false";
const BOT_TYPING_DELAY_MS = Math.max(0, Math.min(2500, Number(process.env.BOT_TYPING_DELAY_MS || 1400)));

function sleep(ms = 0) {
  const delay = Number(ms || 0);
  if (!delay || delay <= 0) return Promise.resolve();
  return new Promise((resolve) => setTimeout(resolve, delay));
}

async function sendWhatsAppTypingIndicator(to, incomingMessageId = "", phoneNumberId = DUBAI_PHONE_NUMBER_ID) {
  const finalPhoneNumberId = normalizePhoneNumberId(phoneNumberId || DUBAI_PHONE_NUMBER_ID);
  const cleanMessageId = (incomingMessageId || "").toString().trim();

  if (!BOT_TYPING_INDICATOR_ENABLED || !ACCESS_TOKEN || !finalPhoneNumberId || !cleanMessageId) {
    return { ok: false, skipped: true };
  }

  const url = `https://graph.facebook.com/v18.0/${finalPhoneNumberId}/messages`;
  const payload = {
    messaging_product: "whatsapp",
    status: "read",
    message_id: cleanMessageId,
    typing_indicator: { type: "text" }
  };

  try {
    const response = await fetch(url, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${ACCESS_TOKEN}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify(payload)
    });

    const result = await response.json().catch(() => ({}));

    if (!response.ok) {
      console.log("WhatsApp typing indicator failed:");
      console.log(JSON.stringify(result, null, 2));
      return { ok: false, status: response.status, result };
    }

    return { ok: true, status: response.status, result };
  } catch (error) {
    console.log("WhatsApp typing indicator threw error:");
    console.log(error);
    return { ok: false, error: error?.message || String(error) };
  }
}

async function showBotTypingBeforeReply({ to, incomingMessageId, phoneNumberId, fromInternalNumber = false } = {}) {
  if (!BOT_TYPING_INDICATOR_ENABLED) {
    return;
  }

  // Do not skip internal/staff test numbers here.
  // They are suppressed only from inbox live notifications, but should still see typing during tests.
  if (fromInternalNumber) {
    console.log("[Bot Typing] internal/test number allowed for typing indicator test", { to });
  }

  await sendWhatsAppTypingIndicator(to, incomingMessageId, phoneNumberId);
  await sleep(BOT_TYPING_DELAY_MS);
}

async function sendWhatsAppMessage(to, body, phoneNumberId = DUBAI_PHONE_NUMBER_ID, options = {}) {
  const finalPhoneNumberId = normalizePhoneNumberId(phoneNumberId || DUBAI_PHONE_NUMBER_ID);
  const lineConfig = getLineConfig(finalPhoneNumberId);
  const url = `https://graph.facebook.com/v18.0/${finalPhoneNumberId}/messages`;
  const replyLanguage = options.replyLanguage || getConversationLanguage(to);
  const shouldLocalize = options.skipAutoLanguage
    ? false
    : (options.autoLocalize || Boolean(options.replyLanguage) || /\n\s*-{10,}\s*\n/.test((body || "").toString()));
  const finalBody = shouldLocalize
    ? cleanLocalizedReplyBody(body, replyLanguage)
    : body;

  const payload = {
    messaging_product: "whatsapp",
    to,
    type: "text",
    text: { body: finalBody }
  };

  console.log(`Sending WhatsApp message from ${lineConfig.branch} (${finalPhoneNumberId}) to ${to}`);

  const response = await fetch(url, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${ACCESS_TOKEN}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify(payload)
  });

  const result = await response.json();

  if (!response.ok) {
    console.log("WhatsApp API send failed:");
    console.log(JSON.stringify(result, null, 2));
  } else {
    console.log("WhatsApp message sent successfully:");
    console.log(JSON.stringify(result, null, 2));
  }

  return result;
}

function getWhatsAppApiError(sendResult = {}) {
  if (!sendResult || typeof sendResult !== "object") {
    return null;
  }

  if (sendResult.error) {
    return sendResult.error;
  }

  if (sendResult.result && sendResult.result.error) {
    return sendResult.result.error;
  }

  return null;
}

function isWhatsAppOutside24HourWindowError(error = {}) {
  const code = (error.code || error.error_code || "").toString().trim();
  const message = normalizeText(error.message || error.error_user_msg || error.details || "");

  return code === "131047" ||
    code === "470" ||
    message.includes("24 hour") ||
    message.includes("24-hour") ||
    message.includes("outside") ||
    message.includes("re-engagement") ||
    message.includes("customer care window");
}

function getWhatsAppFailureReasonArabic(sendResult = {}) {
  const error = getWhatsAppApiError(sendResult) || {};
  const rawMessage = (error.error_user_msg || error.message || error.details || "").toString().trim();

  if (isWhatsAppOutside24HourWindowError(error)) {
    return "خارج نافذة واتساب 24 ساعة. لازم العميل يرسل أولاً لفتح المحادثة، أو يتم استخدام Template معتمدة من واتساب.";
  }

  return rawMessage || "واتساب رفض الإرسال أو لم يؤكد قبول الرسالة.";
}

