function getDubaiNowPseudoDate() {
  return new Date(new Date().toLocaleString("en-US", { timeZone: "Asia/Dubai" }));
}

function isSameConversationPhone(message = {}, phone = "", phoneNumberId = "") {
  const cleanPhone = normalizePhoneDigits(phone);
  const messagePhone = normalizePhoneDigits(message.phone || "");
  const cleanPhoneNumberId = normalizePhoneNumberId(phoneNumberId || "");
  const messagePhoneNumberId = normalizePhoneNumberId(message.phoneNumberId || "");

  if (!cleanPhone || !messagePhone || cleanPhone !== messagePhone) {
    return false;
  }

  return !cleanPhoneNumberId || !messagePhoneNumberId || messagePhoneNumberId === cleanPhoneNumberId;
}

function getLatestCustomerMessageRecord(messages = [], phone = "", phoneNumberId = "") {
  const matched = (messages || [])
    .filter((message) => {
      return isSameConversationPhone(message, phone, phoneNumberId) &&
        normalizeText(message.sender || "") === "customer";
    })
    .map((message) => ({
      message,
      date: parseSheetDate(message.time || message.opt_out_date || message.opt_in_date)
    }))
    .filter((item) => item.date && !Number.isNaN(item.date.getTime()))
    .sort((a, b) => b.date.getTime() - a.date.getTime());

  return matched[0] || null;
}

function buildStaffSendBlockedResult(reason = "outside_24h", details = {}) {
  const optedOutText = details.optedOut
    ? " العميل أرسل STOP سابقاً، لذلك التذكيرات والمتابعات التلقائية موقوفة لهذا الرقم."
    : "";
  const lastCustomerText = details.lastCustomerTime
    ? ` آخر رسالة من العميل كانت: ${details.lastCustomerTime}.`
    : " لا توجد رسالة حديثة من العميل محفوظة ضمن نافذة 24 ساعة.";

  return {
    ok: false,
    error: {
      code: "STAFF_FREE_TEXT_BLOCKED",
      reason,
      message: `لا يمكن إرسال رسالة عادية الآن. المحادثة خارج نافذة واتساب 24 ساعة.${lastCustomerText}${optedOutText} يجب أن يرسل العميل رسالة أولاً، أو يتم استخدام Template معتمدة من واتساب.`,
      error_user_msg: `خارج نافذة واتساب 24 ساعة. لازم العميل يرسل أولاً لفتح المحادثة، أو يتم استخدام Template معتمدة من واتساب.${optedOutText}`
    }
  };
}

async function getStaffFreeTextSendGuard(phone = "", phoneNumberId = "") {
  try {
    const cleanPhone = normalizePhoneDigits(phone);
    if (!cleanPhone) {
      return { ok: false, sendResult: buildStaffSendBlockedResult("missing_phone") };
    }

    // V31.5.8.60.3.9.51 - Fast staff send guard:
    // Do not block every staff reply on a fresh Google Sheet read. /api/messages already keeps
    // a safe last-good Sheet cache + in-memory messages. Use that fast source for the 24h guard.
    // This keeps the protection logic, but removes the extra 3-30s wait before WhatsApp send.
    const sheetData = (typeof loadMessagesFromGoogleSheetForMessagesApi === "function")
      ? await loadMessagesFromGoogleSheetForMessagesApi()
      : await loadMessagesFromGoogleSheet();
    const sheetMessages = Array.isArray(sheetData.messages) ? sheetData.messages : [];
    const memoryMessages = Array.isArray(inboxMessages) ? inboxMessages : [];
    const messages = [...sheetMessages, ...memoryMessages];
    const optedOut = isCustomerOptedOutForFollowUps(messages, cleanPhone, phoneNumberId);
    const latestCustomer = getLatestCustomerMessageRecord(messages, cleanPhone, phoneNumberId);

    if (!latestCustomer) {
      return {
        ok: false,
        sendResult: buildStaffSendBlockedResult("no_recent_customer_message", { optedOut })
      };
    }

    const now = getDubaiNowPseudoDate();
    const ageMs = now.getTime() - latestCustomer.date.getTime();
    const windowMs = 24 * 60 * 60 * 1000;

    if (ageMs > windowMs) {
      return {
        ok: false,
        sendResult: buildStaffSendBlockedResult("outside_24h", {
          optedOut,
          lastCustomerTime: latestCustomer.message.time || ""
        })
      };
    }

    return {
      ok: true,
      optedOut,
      lastCustomerTime: latestCustomer.message.time || ""
    };
  } catch (error) {
    console.error("Staff free-text guard failed:");
    console.error(error);
    return { ok: true, warning: "guard_failed" };
  }
}

async function blockStaffSendIfNeeded({ to, phoneNumberId, originalBody = "" }) {
  const guard = await getStaffFreeTextSendGuard(to, phoneNumberId);

  if (guard.ok) {
    return { ok: true };
  }

  const sendResult = guard.sendResult || buildStaffSendBlockedResult("blocked");
  addInboxMessage(to, "staff", buildStaffSendFailureLogBody(originalBody, sendResult), "Failed / Not delivered", phoneNumberId, {
    messageType: "Failed / Not delivered",
    statusOverride: "Failed / Not delivered"
  });

  return {
    ok: false,
    statusCode: 409,
    response: {
      ok: false,
      status: "Failed / Not delivered",
      error: getStaffSendFailureResponseMessage(sendResult),
      result: sendResult
    }
  };
}


function parseImageDataUrl(imageDataUrl) {
  const value = (imageDataUrl || "").toString().trim();
  const match = value.match(/^data:(image\/(?:jpeg|jpg|png|webp));base64,([A-Za-z0-9+/=]+)$/);

  if (!match) {
    return null;
  }

  const mimeType = match[1] === "image/jpg" ? "image/jpeg" : match[1];
  const buffer = Buffer.from(match[2], "base64");

  return { mimeType, buffer };
}

// V31.5.8.60.3.4 - Voice button fix:
// Supports staff-sent WhatsApp audio from Team Inbox while keeping the raw file input hidden.
function parseAudioDataUrl(audioDataUrl) {
  const value = (audioDataUrl || "").toString().trim();
  const match = value.match(/^data:(audio\/(?:aac|mp4|mpeg|amr|ogg|x-m4a|m4a));base64,([A-Za-z0-9+/=]+)$/);

  if (!match) {
    return null;
  }

  const originalMimeType = match[1].toLowerCase();
  const mimeType = (originalMimeType === "audio/x-m4a" || originalMimeType === "audio/m4a")
    ? "audio/mp4"
    : originalMimeType;
  const buffer = Buffer.from(match[2], "base64");

  return { mimeType, buffer };
}

function sanitizeMediaFilename(filename, mimeType) {
  const safeBase = (filename || "iconic-image")
    .toString()
    .replace(/[^a-zA-Z0-9._-]/g, "_")
    .replace(/_+/g, "_")
    .slice(0, 80) || "iconic-image";

  if (safeBase.includes(".")) {
    return safeBase;
  }

  const extensionMap = {
    "image/jpeg": ".jpg",
    "image/png": ".png",
    "image/webp": ".webp",
    "audio/aac": ".aac",
    "audio/mp4": ".m4a",
    "audio/mpeg": ".mp3",
    "audio/amr": ".amr",
    "audio/ogg": ".ogg"
  };

  return safeBase + (extensionMap[mimeType] || ".jpg");
}

async function uploadWhatsAppMediaFromBuffer(buffer, mimeType, filename, phoneNumberId = DUBAI_PHONE_NUMBER_ID) {
  const finalPhoneNumberId = normalizePhoneNumberId(phoneNumberId || DUBAI_PHONE_NUMBER_ID);
  const url = `https://graph.facebook.com/v18.0/${finalPhoneNumberId}/media`;

  const form = new FormData();
  const blob = new Blob([buffer], { type: mimeType });
  form.append("messaging_product", "whatsapp");
  form.append("type", mimeType);
  form.append("file", blob, sanitizeMediaFilename(filename, mimeType));

  const response = await fetch(url, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${ACCESS_TOKEN}`
    },
    body: form
  });

  const result = await response.json();

  if (!response.ok) {
    console.log("WhatsApp media upload failed:");
    console.log(JSON.stringify(result, null, 2));
    return { ok: false, status: response.status, result };
  }

  return { ok: true, status: response.status, mediaId: result.id, result };
}

async function sendWhatsAppImageMessage(to, imageDataUrl, caption = "", filename = "iconic-image.jpg", phoneNumberId = DUBAI_PHONE_NUMBER_ID) {
  const finalPhoneNumberId = normalizePhoneNumberId(phoneNumberId || DUBAI_PHONE_NUMBER_ID);
  const parsedImage = parseImageDataUrl(imageDataUrl);

  if (!parsedImage) {
    return {
      ok: false,
      status: 400,
      result: { error: "Invalid image format. Please upload JPG, PNG, or WEBP." }
    };
  }

  if (parsedImage.buffer.length > 5 * 1024 * 1024) {
    return {
      ok: false,
      status: 400,
      result: { error: "Image is too large. Please upload an image under 5MB." }
    };
  }

  const uploadResult = await uploadWhatsAppMediaFromBuffer(
    parsedImage.buffer,
    parsedImage.mimeType,
    filename,
    finalPhoneNumberId
  );

  if (!uploadResult.ok) {
    return uploadResult;
  }

  const lineConfig = getLineConfig(finalPhoneNumberId);
  const url = `https://graph.facebook.com/v18.0/${finalPhoneNumberId}/messages`;
  const cleanCaption = (caption || "").toString().trim().slice(0, 900);

  const payload = {
    messaging_product: "whatsapp",
    to,
    type: "image",
    image: {
      id: uploadResult.mediaId,
      ...(cleanCaption ? { caption: cleanCaption } : {})
    }
  };

  console.log(`Sending WhatsApp image from ${lineConfig.branch} (${finalPhoneNumberId}) to ${to}`);

  const response = await fetch(url, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${ACCESS_TOKEN}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify(payload)
  });

  const result = await response.json();

  if (!response.ok) {
    console.log("WhatsApp image send failed:");
    console.log(JSON.stringify(result, null, 2));
  } else {
    console.log("WhatsApp image sent successfully:");
    console.log(JSON.stringify(result, null, 2));
  }

  return {
    ok: response.ok,
    status: response.status,
    mediaId: uploadResult.mediaId,
    result
  };
}


