async function uploadWhatsAppVideoFromUrl(videoUrl, phoneNumberId = DUBAI_PHONE_NUMBER_ID, filename = "iconic-video.mp4") {
  const finalPhoneNumberId = normalizePhoneNumberId(phoneNumberId || DUBAI_PHONE_NUMBER_ID);
  const cleanVideoUrl = (videoUrl || "").toString().trim();
  const safeFilename = (filename || "iconic-video.mp4")
    .toString()
    .replace(/[^a-zA-Z0-9._-]/g, "_")
    .replace(/_+/g, "_")
    .slice(0, 90) || "iconic-video.mp4";

  if (!cleanVideoUrl) {
    return {
      ok: false,
      status: 400,
      result: { error: "Missing video URL" }
    };
  }

  let videoResponse;
  try {
    videoResponse = await fetch(cleanVideoUrl, {
      headers: {
        "User-Agent": "Mozilla/5.0 IconicHairCareBot/1.0",
        "Accept": "video/mp4,video/*,*/*"
      }
    });
  } catch (error) {
    return {
      ok: false,
      status: 500,
      result: { error: "Video URL fetch threw error", url: cleanVideoUrl, message: error?.message || String(error) }
    };
  }

  if (!videoResponse.ok) {
    return {
      ok: false,
      status: videoResponse.status,
      result: { error: "Video URL fetch failed", url: cleanVideoUrl }
    };
  }

  const originalContentType = (videoResponse.headers.get("content-type") || "").split(";")[0].trim().toLowerCase();
  const isMp4Url = cleanVideoUrl.toLowerCase().includes(".mp4") || safeFilename.toLowerCase().endsWith(".mp4");
  const contentType = originalContentType.startsWith("video/")
    ? originalContentType
    : (isMp4Url ? "video/mp4" : "video/mp4");

  const arrayBuffer = await videoResponse.arrayBuffer();
  const buffer = Buffer.from(arrayBuffer);

  if (!buffer.length) {
    return {
      ok: false,
      status: 400,
      result: { error: "Video URL returned empty file", url: cleanVideoUrl, originalContentType, contentType }
    };
  }

  if (buffer.length > 16 * 1024 * 1024) {
    return {
      ok: false,
      status: 400,
      result: { error: "Video is larger than WhatsApp 16MB limit", sizeBytes: buffer.length }
    };
  }

  const uploadUrl = `https://graph.facebook.com/v18.0/${finalPhoneNumberId}/media`;
  const form = new FormData();
  const blob = new Blob([buffer], { type: contentType });
  form.append("messaging_product", "whatsapp");
  form.append("type", contentType);
  form.append("file", blob, safeFilename);

  const response = await fetch(uploadUrl, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${ACCESS_TOKEN}`
    },
    body: form
  });

  const result = await response.json().catch(() => ({}));

  if (!response.ok) {
    console.log("WhatsApp video media upload failed:");
    console.log(JSON.stringify({
      url: cleanVideoUrl,
      filename: safeFilename,
      originalContentType,
      contentType,
      sizeBytes: buffer.length,
      result
    }, null, 2));
    return {
      ok: false,
      status: response.status,
      result: {
        ...result,
        uploadDebug: {
          url: cleanVideoUrl,
          filename: safeFilename,
          originalContentType,
          contentType,
          sizeBytes: buffer.length
        }
      }
    };
  }

  return { ok: true, status: response.status, mediaId: result.id, result };
}
const videoHeaderMediaCache = new Map();

function getVideoHeaderMediaCacheKey(videoUrl, phoneNumberId, filename) {
  return [
    normalizePhoneNumberId(phoneNumberId || DUBAI_PHONE_NUMBER_ID),
    (videoUrl || "").toString().trim(),
    (filename || "iconic-video.mp4").toString().trim()
  ].join("|");
}

async function sendWhatsAppVideoHeaderButtonMessage(to, body, buttons, videoUrl, phoneNumberId = DUBAI_PHONE_NUMBER_ID, options = {}) {
  const cleanVideoUrl = (videoUrl || "").toString().trim();
  const fallbackImageUrl = (options.headerImageUrl || BOT_HEADER_IMAGE_URL || "").toString().trim();
  const filename = (options.filename || "iconic-video.mp4").toString().trim() || "iconic-video.mp4";

  if (!cleanVideoUrl) {
    console.log("Video header skipped: missing video URL");
    return sendWhatsAppButtonMessage(to, body, buttons, phoneNumberId, { ...options, headerImageUrl: fallbackImageUrl });
  }

  const cacheKey = getVideoHeaderMediaCacheKey(cleanVideoUrl, phoneNumberId, filename);
  const cachedMediaId = videoHeaderMediaCache.get(cacheKey);

  if (cachedMediaId) {
    const cachedSendResult = await sendWhatsAppButtonMessage(to, body, buttons, phoneNumberId, { ...options, headerVideoId: cachedMediaId });

    if (!cachedSendResult?.error) {
      console.log("Video header sent using cached WhatsApp media id.");
      return cachedSendResult;
    }

    console.log("Cached video header media id failed; refreshing upload.");
    console.log(JSON.stringify(cachedSendResult, null, 2));
    videoHeaderMediaCache.delete(cacheKey);
  }

  const uploadResult = await uploadWhatsAppVideoFromUrl(cleanVideoUrl, phoneNumberId, filename);

  if (!uploadResult.ok || !uploadResult.mediaId) {
    console.log("Video header upload failed; sending buttons with image header instead:");
    console.log(JSON.stringify(uploadResult.result || {}, null, 2));
    return sendWhatsAppButtonMessage(to, body, buttons, phoneNumberId, { ...options, headerImageUrl: fallbackImageUrl });
  }

  videoHeaderMediaCache.set(cacheKey, uploadResult.mediaId);

  return sendWhatsAppButtonMessage(to, body, buttons, phoneNumberId, { ...options, headerVideoId: uploadResult.mediaId });
}


