async function sendWhatsAppFlowMessage(to, phoneNumberId = DUBAI_PHONE_NUMBER_ID, options = {}) {
  const finalPhoneNumberId = normalizePhoneNumberId(phoneNumberId || DUBAI_PHONE_NUMBER_ID);
  const lineConfig = getLineConfig(finalPhoneNumberId);
  const requestedFlowType = (options.flowType || options.requestType || "").toString().toLowerCase();
  const isServiceBookingFlow = requestedFlowType.includes("service");
  const bookingFlowConfig = isServiceBookingFlow
    ? getServiceBookingFlowConfigForLine(finalPhoneNumberId)
    : getBookingFlowConfigForLine(finalPhoneNumberId);
  const selectedFlowCta = isServiceBookingFlow ? ICONIC_SERVICE_BOOKING_FLOW_CTA : ICONIC_CONSULTATION_FLOW_CTA;
  const selectedFlowHeader = isServiceBookingFlow ? "Service Booking" : "Consultation Booking";

  if (!ICONIC_BOOKING_FLOW_ENABLED) {
    return {
      ok: false,
      status: 400,
      result: { error: "ICONIC_BOOKING_FLOW_ENABLED is false" }
    };
  }

  if (!bookingFlowConfig.flowId) {
    return {
      ok: false,
      status: 400,
      result: { error: `${bookingFlowConfig.envName} is missing` }
    };
  }

  const url = `https://graph.facebook.com/v18.0/${finalPhoneNumberId}/messages`;
  const flowToken = [
    bookingFlowConfig.tokenPrefix,
    normalizePhoneDigits(to),
    Date.now().toString()
  ].filter(Boolean).join("_");

  const customerNameForFlow = cleanCustomerName(options.customerName || "");
  const flowGreeting = customerNameForFlow ? `Hello ${customerNameForFlow} 👋` : "Hello 👋";

  const replyLanguage = options.replyLanguage || getConversationLanguage(to);
  const localizedFlowCta = replyLanguage === "ar"
    ? (isServiceBookingFlow ? "احجز سيرفس" : "احجز استشارة")
    : selectedFlowCta;
  const localizedFlowHeader = replyLanguage === "ar"
    ? (isServiceBookingFlow ? "حجز سيرفس" : "حجز استشارة")
    : selectedFlowHeader;
  const localizedFlowGreeting = replyLanguage === "ar"
    ? (customerNameForFlow ? `مرحبا ${customerNameForFlow} 👋` : "مرحبا 👋")
    : flowGreeting;

  const flowBody = (isServiceBookingFlow
    ? (replyLanguage === "ar"
        ? [
            localizedFlowGreeting,
            "",
            "احجز موعد السيرفس خلال ثواني من داخل واتساب.",
            "اختر الفرع، اليوم، الوقت، واسم الموظف المفضل إن وجد.",
            "الفريق سيؤكد الموعد النهائي بعد مراجعة التوفر."
          ]
        : [
            localizedFlowGreeting,
            "",
            "Book your service appointment in seconds inside WhatsApp.",
            "Choose the branch, preferred day, preferred time, and preferred team member if any.",
            "Our team will confirm the final appointment after checking availability."
          ])
    : (replyLanguage === "ar"
        ? [
            localizedFlowGreeting,
            "",
            "احجز استشارتك خلال ثواني من داخل واتساب.",
            "اختر اليوم والوقت المناسب، وفريقنا سيؤكد الموعد النهائي بعد مراجعة التوفر."
          ]
        : [
            localizedFlowGreeting,
            "",
            "Book your consultation in seconds inside WhatsApp.",
            "Choose your preferred day and time. Our team will confirm the final appointment after checking availability."
          ])
  ).join(String.fromCharCode(10));

  const payload = {
    messaging_product: "whatsapp",
    recipient_type: "individual",
    to,
    type: "interactive",
    interactive: {
      type: "flow",
      header: BOT_HEADER_IMAGE_URL
        ? {
            type: "image",
            image: { link: BOT_HEADER_IMAGE_URL }
          }
        : {
            type: "text",
            text: localizedFlowHeader
          },
      body: {
        text: flowBody
      },
      footer: {
        text: "Iconic Hair Care"
      },
      action: {
        name: "flow",
        parameters: {
          flow_message_version: "3",
          flow_id: bookingFlowConfig.flowId,
          flow_token: flowToken,
          flow_cta: localizedFlowCta,
          flow_action: "navigate",
          flow_action_payload: isServiceBookingFlow
            ? {
                screen: "SERVICE_BOOKING",
                data: {
                  ...getServiceBookingFlowData(options.branch || lineConfig.branch, "Today"),
                  default_branch: options.branch || lineConfig.branch,
                  customer_name: options.customerName || "",
                  request_type: "Service Appointment",
                  flow_type: "service_booking"
                }
              }
            : (isAbuDhabiLine(finalPhoneNumberId)
                ? {
                    screen: "CONSULTATION_BOOKING",
                    data: {
                      default_branch: "Abu Dhabi",
                      selected_branch: "Abu Dhabi",
                      customer_name: options.customerName || "",
                      request_type: bookingFlowConfig.requestType,
                      flow_type: "consultation_booking",
                      today_available: false,
                      today_unavailable_message: "Today is not available for Abu Dhabi consultation booking. Please choose Tomorrow or Day After Tomorrow."
                    }
                  }
                : {
                    screen: "CONSULTATION_BOOKING",
                    data: {
                      ...getConsultationBookingFlowData(options.branch || lineConfig.branch, "Today"),
                      default_branch: options.branch || lineConfig.branch,
                      customer_name: options.customerName || "",
                      request_type: bookingFlowConfig.requestType,
                      flow_type: "consultation_booking"
                    }
                  })
        }
      }
    }
  };

  console.log(`Sending WhatsApp Flow from ${lineConfig.branch} (${finalPhoneNumberId}) to ${to} using ${bookingFlowConfig.envName}=${bookingFlowConfig.flowId}`);

  const response = await fetch(url, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${ACCESS_TOKEN}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify(payload)
  });

  const responseText = await response.text();
  let result;

  try {
    result = JSON.parse(responseText);
  } catch (error) {
    result = { raw: responseText || "" };
  }

  if (!response.ok) {
    console.log("WhatsApp Flow send failed:");
    console.log(JSON.stringify(result, null, 2));
  } else {
    console.log("WhatsApp Flow sent successfully:");
    console.log(JSON.stringify(result, null, 2));
  }

  return {
    ok: response.ok,
    status: response.status,
    result
  };
}

