async function handleRealCustomerIntentUpgrade({ from, message, originalText, text, incomingPhoneNumberId, lineConfig, profileName, replyLanguage = "en" }) {
  const input = originalText || text || "";
  if (!input) return false;

  const logRealCustomerIntent = (status = "Customer Message", messageType = "Customer Message", fallbackAction = "") => {
    logCustomerActionForInbox({
      from,
      message,
      profileName,
      rawText: input,
      fallbackAction: fallbackAction || input,
      status,
      phoneNumberId: incomingPhoneNumberId,
      messageType
    });
  };

  if (isSharjahBranchIntentText(input)) {
    logRealCustomerIntent("Location Requested", "Customer Sharjah Branch Request");
    setConversationStatus(from, "Location Requested");
    const body = buildSharjahBranchIntentBody(profileName, replyLanguage);
    const buttons = getBranchChoiceButtons(replyLanguage);
    await sendWhatsAppButtonMessage(from, body, buttons, incomingPhoneNumberId, { replyLanguage, skipAutoLanguage: true });
    addInboxMessage(from, "bot", formatButtonLog(body, buttons), "Location Requested", incomingPhoneNumberId, { customerName: profileName, messageType: "Real Customer Intent - Sharjah Branch" });
    return true;
  }

  if (isSmartBookingEarlierTimeText(input)) {
    logRealCustomerIntent("Need Follow-up", "Customer Earlier Time Request");
    setConversationStatus(from, "Need Follow-up");
    const body = buildEarlierTimeBody(profileName, replyLanguage);
    await sendWhatsAppMessage(from, body, incomingPhoneNumberId, { replyLanguage, skipAutoLanguage: true });
    addInboxMessage(from, "bot", body, "Need Follow-up", incomingPhoneNumberId, { customerName: profileName, messageType: "Real Customer Intent - Earlier Time" });
    return true;
  }

  if (isSpecialistExclusionText(input)) {
    logRealCustomerIntent("Smart Booking - Specialist Preference", "Customer Specialist Exclusion Request");
    setConversationStatus(from, "Smart Booking - Specialist Preference");
    const body = buildSpecialistExclusionBody(input, profileName, replyLanguage);
    const buttons = getSmartBookingStaffPreferenceButtons(replyLanguage);
    await sendWhatsAppButtonMessage(from, body, buttons, incomingPhoneNumberId, { replyLanguage, skipAutoLanguage: true });
    addInboxMessage(from, "bot", formatButtonLog(body, buttons), "Smart Booking - Specialist Preference", incomingPhoneNumberId, { customerName: profileName, messageType: "Real Customer Intent - Specialist Exclusion" });
    return true;
  }

  if (isSmartBookingUrgentText(input) && !isSmartBookingNaturalRequest(input)) {
    logRealCustomerIntent("Need Follow-up", "Customer Urgent Request");
    setConversationStatus(from, "Need Follow-up");
    const body = buildUrgentIntentBody(profileName, replyLanguage);
    const buttons = getSmartBookingStaffPreferenceButtons(replyLanguage);
    await sendWhatsAppButtonMessage(from, body, buttons, incomingPhoneNumberId, { replyLanguage, skipAutoLanguage: true });
    addInboxMessage(from, "bot", formatButtonLog(body, buttons), "Need Follow-up", incomingPhoneNumberId, { customerName: profileName, messageType: "Real Customer Intent - Urgent" });
    return true;
  }

  if (isSmartBookingAvailabilityQuestionText(input)) {
    logRealCustomerIntent("Availability Question", "Customer Availability Question");
    const staff = detectSmartBookingStaff(input);
    const explicitWeekday = detectSmartBookingExplicitWeekday(input);
    const naturalDay = detectSmartBookingDay(input);
    const inputTime = getSmartBookingTimeFromText(input);
    const draft = {
      branch: staff?.branch || lineConfig.branch || "Dubai",
      preferredDay: explicitWeekday || naturalDay || "",
      preferredTime: inputTime.ok ? inputTime.time : "",
      teamMember: staff?.name || "",
      serviceType: detectSmartBookingServiceType(input),
      rawRequest: input,
      startedAt: getDubaiTimestamp(),
      phoneNumberId: incomingPhoneNumberId,
      waitingForBookingConfirm: true,
      waitingForTime: false,
      waitingForWeekday: false,
      waitingForStaff: false
    };
    smartBookingDrafts[from] = draft;
    setConversationStatus(from, "Availability Question");
    const body = buildSmartAvailabilityConfirmBody(draft, profileName, replyLanguage);
    const buttons = getAvailabilityConfirmButtons(replyLanguage);
    await sendWhatsAppButtonMessage(from, body, buttons, incomingPhoneNumberId, { replyLanguage, skipAutoLanguage: true });
    addInboxMessage(from, "bot", formatButtonLog(body, buttons), "Availability Question", incomingPhoneNumberId, { customerName: profileName, messageType: "Real Customer Intent - Availability" });
    return true;
  }

  return false;
}


function getStaffActionNumbersForBranch(branch = "Dubai") {
  const isAbuDhabi = compactText(branch).includes("abu");
  const envName = isAbuDhabi ? "ABU_DHABI_STAFF_NUMBER" : "DUBAI_STAFF_NUMBER";
  const fallback = isAbuDhabi ? DEFAULT_ABU_DHABI_STAFF_NUMBER : DEFAULT_DUBAI_STAFF_NUMBER;
  const raw = (process.env[envName] || fallback || "").toString();
  return raw
    .split(",")
    .map((item) => normalizeWhatsAppRecipientDigits(item))
    .filter(Boolean);
}

function getStaffActionRouteFromNumber(staffPhone = "", incomingPhoneNumberId = DUBAI_PHONE_NUMBER_ID) {
  const cleanStaffPhone = normalizeWhatsAppRecipientDigits(staffPhone);
  const dubaiNumbers = getStaffActionNumbersForBranch("Dubai");
  const abuDhabiNumbers = getStaffActionNumbersForBranch("Abu Dhabi");

  if (abuDhabiNumbers.includes(cleanStaffPhone)) {
    return {
      isStaff: true,
      staffNumber: cleanStaffPhone,
      branch: "Abu Dhabi",
      phoneNumberId: ABU_DHABI_PHONE_NUMBER_ID,
      envName: "ABU_DHABI_STAFF_NUMBER"
    };
  }

  if (dubaiNumbers.includes(cleanStaffPhone)) {
    return {
      isStaff: true,
      staffNumber: cleanStaffPhone,
      branch: "Dubai",
      phoneNumberId: DUBAI_PHONE_NUMBER_ID,
      envName: "DUBAI_STAFF_NUMBER"
    };
  }

  return {
    isStaff: false,
    staffNumber: cleanStaffPhone,
    branch: getLineConfig(incomingPhoneNumberId).branch,
    phoneNumberId: incomingPhoneNumberId,
    envName: "NONE"
  };
}

function getStaffBookingActionFromText(text = "") {
  const value = compactText(text);
  if (!value) return "";

  // V31.5.8.60.3.9.35 - Staff Flow confirm priority:
  // Staff WhatsApp alert buttons may arrive as "Confirm Booking",
  // "confirm_booking", or even the common typo "conform".
  // Treat all of them as a direct booking confirmation action so the
  // customer is notified immediately without needing Team Inbox.
  if (
    value === "confirm" ||
    value === "confirmed" ||
    value === "confirm booking" ||
    value === "confirm appointment" ||
    value === "confirm request" ||
    value === "confirm_booking" ||
    value === "confirm_appointment" ||
    value === "approve" ||
    value === "approved" ||
    value === "approve booking" ||
    value === "approve appointment" ||
    value === "conform" ||
    value === "conform booking" ||
    value === "conform appointment" ||
    value === "تأكيد" ||
    value === "تأكيد الحجز" ||
    value === "اكد" ||
    value === "أكد" ||
    value === "اكد الحجز" ||
    value === "أكد الحجز"
  ) return "confirm";

  if (
    value === "suggest time" ||
    value === "suggest_time" ||
    value === "suggest" ||
    value === "suggest another time" ||
    value === "suggest_another_time" ||
    value.includes("suggest time")
  ) return "suggest_time";

  if (value === "team will call" || value === "team_will_call" || value === "team will contact" || value.includes("team will call")) return "team_will_call";

  return "";
}

function getBookingMessageField(message = "", labels = []) {
  const lines = (message || "").toString().split(/\r?\n/);
  const normalizedLabels = labels.map((label) => compactText(label));

  for (const line of lines) {
    const index = line.indexOf(":");
    if (index === -1) continue;

    const key = compactText(line.slice(0, index));
    if (normalizedLabels.includes(key)) {
      return line.slice(index + 1).trim();
    }
  }

  return "";
}

function getBookingRequestDetails(booking = {}) {
  const message = [booking.message || "", booking.notes || ""].filter(Boolean).join("\n");
  return {
    branch: booking.branch || getBookingMessageField(message, ["Preferred branch", "Branch", "الفرع"]),
    preferredDay: getBookingMessageField(message, ["Preferred day", "Day", "اليوم"]),
    preferredTime: getBookingMessageField(message, ["Preferred time", "Time", "الوقت", "Suggested time", "الوقت المقترح"]),
    teamMember: getBookingMessageField(message, ["Team member", "Employee", "Staff", "الموظف"]),
    serviceType: getBookingMessageField(message, ["Service type", "Service", "الخدمة"]),
    requestType: booking.requestType || getBookingMessageField(message, ["Request type", "Type", "نوع الطلب"])
  };
}

function getMessageContextId(message = {}) {
  return (message?.context?.id || "").toString().trim();
}

function cleanupStaffBookingActionContexts() {
  const cutoff = Date.now() - (24 * 60 * 60 * 1000);
  for (const [id, context] of pendingStaffBookingActionsByTemplateMessageId.entries()) {
    if ((context?.createdAt || 0) < cutoff) {
      pendingStaffBookingActionsByTemplateMessageId.delete(id);
    }
  }
}

function rememberStaffBookingActionContextFromTemplateResult(templateResult = {}, context = {}) {
  const messageId = getWhatsAppTemplateMessageId(templateResult?.result || {});
  if (!messageId) return "";

  const customerPhone = normalizePhoneDigits(context.customerPhone || context.flowData?.phone || "");
  const staffNumber = normalizeWhatsAppRecipientDigits(context.staffNumber || "");

  pendingStaffBookingActionsByTemplateMessageId.set(messageId, {
    ...context,
    staffNumber,
    customerPhone,
    branch: context.flowData?.branch || context.routing?.branch || "",
    phoneNumberId: normalizePhoneNumberId(context.phoneNumberId || context.routing?.phoneNumberId || DUBAI_PHONE_NUMBER_ID),
    createdAt: Date.now()
  });
  cleanupStaffBookingActionContexts();

  console.log("[Staff Booking Action Context] linked template", JSON.stringify({
    messageId,
    staffNumber,
    customerPhone,
    branch: context.flowData?.branch || context.routing?.branch || "",
    testOnly: Boolean(context.testOnly || context.routing?.testOnly)
  }, null, 2));

  return messageId;
}

async function findPendingBookingForStaffActionContext(context = {}, route = {}) {
  const customerPhone = normalizePhoneDigits(context.customerPhone || context.flowData?.phone || "");
  if (!customerPhone) return null;

  const result = await loadBookingRequestsFromGoogleSheetFromServer();
  const bookings = Array.isArray(result.bookingRequests) ? result.bookingRequests : [];
  const branchValue = compactText(context.branch || context.flowData?.branch || route.branch || "Dubai");

  const matches = bookings.filter((booking) => {
    const bookingPhone = normalizePhoneDigits(booking.phone || "");
    const bookingBranch = compactText(booking.branch || getBookingRequestDetails(booking).branch || "");
    const sameBranch = branchValue.includes("abu")
      ? bookingBranch.includes("abu")
      : (!bookingBranch.includes("abu"));

    return bookingPhone === customerPhone &&
      sameBranch &&
      isPendingBookingStatusValue(booking.status || "Pending");
  });

  matches.sort((a, b) => {
    const rowA = Number(a.rowNumber || 0);
    const rowB = Number(b.rowNumber || 0);
    if (rowA !== rowB) return rowB - rowA;

    const dateA = parseSheetDate(a.lastUpdated || a.date || "")?.getTime() || 0;
    const dateB = parseSheetDate(b.lastUpdated || b.date || "")?.getTime() || 0;
    return dateB - dateA;
  });

  return matches[0] || null;
}

function buildBookingDetailsNoteForCustomer(booking = {}, language = "en") {
  const details = getBookingRequestDetails(booking);
  const lines = [];
  const isArabic = language === "ar";

  if (details.preferredDay) lines.push(`${isArabic ? "اليوم" : "Day"}: ${getSmartBookingDayLabel(details.preferredDay, language)}`);
  if (details.preferredTime) lines.push(`${isArabic ? "الوقت" : "Time"}: ${details.preferredTime}`);
  if (details.teamMember) lines.push(`${isArabic ? "الموظف" : "Team member"}: ${details.teamMember}`);
  if (details.serviceType) lines.push(`${isArabic ? "الخدمة" : "Service"}: ${details.serviceType}`);

  return lines.join("\n");
}

function isPendingBookingStatusValue(status = "") {
  const value = compactText(status || "pending");
  if (!value) return true;

  return !value.includes("confirm") &&
    !value.includes("approved") &&
    !value.includes("cancel") &&
    !value.includes("done") &&
    !value.includes("closed") &&
    !value.includes("suggested") &&
    !value.includes("team will call");
}

async function findLatestPendingBookingForStaffAction(branch = "Dubai") {
  const result = await loadBookingRequestsFromGoogleSheetFromServer();
  const bookings = Array.isArray(result.bookingRequests) ? result.bookingRequests : [];
  const branchValue = compactText(branch);
  const branchBookings = bookings.filter((booking) => {
    const bookingBranch = compactText(booking.branch || getBookingRequestDetails(booking).branch || "");
    const customerPhone = normalizePhoneDigits(booking.phone || "");
    const isSameBranch = branchValue.includes("abu")
      ? bookingBranch.includes("abu")
      : (!bookingBranch.includes("abu"));

    return isSameBranch &&
      customerPhone &&
      !isSuppressedCustomerNotificationNumber(customerPhone) &&
      isPendingBookingStatusValue(booking.status || "Pending");
  });

  branchBookings.sort((a, b) => {
    const rowA = Number(a.rowNumber || 0);
    const rowB = Number(b.rowNumber || 0);
    if (rowA !== rowB) return rowB - rowA;

    const dateA = parseSheetDate(a.lastUpdated || a.date || "")?.getTime() || 0;
    const dateB = parseSheetDate(b.lastUpdated || b.date || "")?.getTime() || 0;
    return dateB - dateA;
  });

  return branchBookings[0] || null;
}

async function getCustomerLanguageFromHistory(customerPhone = "", fallback = "en") {
  const cleanPhone = normalizePhoneDigits(customerPhone);
  const savedLanguage = conversationLanguage[cleanPhone] || conversationLanguage[customerPhone] || "";

  try {
    const loaded = await loadMessagesFromGoogleSheet();
    const messages = Array.isArray(loaded.messages) ? loaded.messages : [];
    const latestCustomerMessage = messages
      .filter((message) => normalizePhoneDigits(message.phone || "") === cleanPhone && (message.sender || "") === "customer")
      .sort((a, b) => (parseSheetDate(b.time || "")?.getTime() || 0) - (parseSheetDate(a.time || "")?.getTime() || 0))[0];

    if (latestCustomerMessage?.body) {
      return detectIncomingLanguage(latestCustomerMessage.body, savedLanguage || fallback || "en");
    }
  } catch (error) {
    console.log("Staff action customer language lookup failed:");
    console.log(error);
  }

  return savedLanguage || fallback || "en";
}

function buildTeamWillCallCustomerBody(customerName = "", language = "en") {
  const cleanName = cleanCustomerName(customerName);

  if (language === "ar") {
    return [
      `${BUSINESS_NAME_SPACED} ✨`,
      "",
      cleanName ? `تمام ${cleanName} ✅` : "تمام ✅",
      "فريقنا سيتواصل معك قريبًا لتأكيد أفضل موعد متاح."
    ].join("\n");
  }

  return [
    `${BUSINESS_NAME_SPACED} ✨`,
    "",
    cleanName ? `Done ${cleanName} ✅` : "Done ✅",
    "Our team will contact you shortly to confirm the best available appointment time."
  ].join("\n");
}

function buildStaffActionAckBody(action = "", booking = {}, extra = "") {
  const phone = normalizePhoneDigits(booking.phone || "");
  const details = getBookingRequestDetails(booking);
  const customerName = booking.customerName || "Customer";

  if (action === "confirm") {
    return [
      "Confirmed ✅ / تم تأكيد الموعد ✅",
      "",
      `Customer: ${customerName}`,
      phone ? `Phone: ${phone}` : "",
      details.preferredDay ? `Day: ${details.preferredDay}` : "",
      details.preferredTime ? `Time: ${details.preferredTime}` : "",
      "",
      "The customer has been notified directly.",
      "تم إرسال التأكيد للعميل مباشرة."
    ].filter(Boolean).join("\n");
  }

  if (action === "suggest_time_waiting") {
    return [
      "Please type the suggested time.",
      "Example: Tomorrow 5:00 PM",
      "",
      `Customer: ${customerName}`,
      phone ? `Phone: ${phone}` : ""
    ].filter(Boolean).join("\n");
  }

  if (action === "suggest_time_sent") {
    return [
      "Suggested time sent ✅",
      "",
      `Customer: ${customerName}`,
      phone ? `Phone: ${phone}` : "",
      extra ? `Suggested time: ${extra}` : ""
    ].filter(Boolean).join("\n");
  }

  if (action === "team_will_call") {
    return [
      "Team Will Call message sent ✅",
      "",
      `Customer: ${customerName}`,
      phone ? `Phone: ${phone}` : "",
      "The customer has been notified that the team will contact them shortly."
    ].filter(Boolean).join("\n");
  }

  return "Action received ✅";
}

async function sendStaffActionAck(staffNumber = "", body = "", route = {}) {
  const to = normalizeWhatsAppRecipientDigits(staffNumber);
  if (!to || !body) return null;

  return sendWhatsAppMessage(to, body, route.phoneNumberId || DUBAI_PHONE_NUMBER_ID, {
    replyLanguage: "en",
    skipAutoLanguage: true
  });
}

function cleanupSuggestedTimeCustomerContexts() {
  const cutoff = Date.now() - (7 * 24 * 60 * 60 * 1000);
  for (const [phone, context] of pendingCustomerSuggestedTimeActionsByPhone.entries()) {
    if ((context?.createdAt || 0) < cutoff) {
      pendingCustomerSuggestedTimeActionsByPhone.delete(phone);
    }
  }
}

function rememberCustomerSuggestedTimeAction({ customerPhone = "", staffNumber = "", booking = {}, suggestedTime = "", phoneNumberId = DUBAI_PHONE_NUMBER_ID, branch = "" } = {}) {
  const cleanPhone = normalizePhoneDigits(customerPhone || booking.phone || "");
  const cleanStaffNumber = normalizeWhatsAppRecipientDigits(staffNumber || "");

  if (!cleanPhone) return false;

  pendingCustomerSuggestedTimeActionsByPhone.set(cleanPhone, {
    customerPhone: cleanPhone,
    staffNumber: cleanStaffNumber,
    bookingRowNumber: booking.rowNumber || "",
    suggestedTime: (suggestedTime || "").toString().trim(),
    phoneNumberId: normalizePhoneNumberId(phoneNumberId || booking.phoneNumberId || DUBAI_PHONE_NUMBER_ID),
    branch: branch || booking.branch || getLineConfig(phoneNumberId || booking.phoneNumberId || DUBAI_PHONE_NUMBER_ID).branch,
    customerName: booking.customerName || "",
    createdAt: Date.now()
  });

  cleanupSuggestedTimeCustomerContexts();
  return true;
}

function getRememberedCustomerSuggestedTimeAction(customerPhone = "") {
  cleanupSuggestedTimeCustomerContexts();
  const cleanPhone = normalizePhoneDigits(customerPhone || "");
  return cleanPhone ? (pendingCustomerSuggestedTimeActionsByPhone.get(cleanPhone) || null) : null;
}

function isSuggestedTimeBookingStatusValue(status = "") {
  const value = compactText(status || "");
  return value.includes("suggest") ||
    value.includes("new time") ||
    value.includes("وقت مقترح") ||
    value.includes("تعديل الوقت");
}

function isCustomerAcceptSuggestedTimeText(text = "") {
  const value = compactText(text || "");
  if (!value) return false;

  return isSimpleAffirmationText(value) ||
    hasAnyIntentPhrase(value, [
      "confirm", "confirmed", "i confirm", "works for me", "this works", "that works", "good for me", "ok confirmed", "yes confirm",
      "مناسب", "يناسب", "يناسبني", "موافق", "اكد", "أكد", "تم", "تمام مناسب", "تمام اكد", "تمام أكد", "اكيد", "أكيد"
    ]);
}

function isCustomerRejectSuggestedTimeText(text = "") {
  const value = compactText(text || "");
  if (!value) return false;

  return value === "no" ||
    value === "n" ||
    value === "لا" ||
    value === "لأ" ||
    value === "لاء" ||
    hasAnyIntentPhrase(value, [
      "not suitable", "does not work", "doesn't work", "another time", "change time", "different time", "later", "earlier",
      "مو مناسب", "غير مناسب", "ما بيناسب", "ما يناسب", "وقت ثاني", "غير الوقت", "بدي وقت تاني", "وقت آخر", "وقت اخر"
    ]);
}

async function findLatestSuggestedTimeBookingForCustomer(customerPhone = "", phoneNumberId = "") {
  const cleanPhone = normalizePhoneDigits(customerPhone || "");
  if (!cleanPhone) return null;

  const result = await loadBookingRequestsFromGoogleSheetFromServer();
  const bookings = Array.isArray(result.bookingRequests) ? result.bookingRequests : [];
  const cleanPhoneNumberId = normalizePhoneNumberId(phoneNumberId || "");
  const recentCutoff = Date.now() - (7 * 24 * 60 * 60 * 1000);

  const matches = bookings.filter((booking) => {
    const bookingPhone = normalizePhoneDigits(booking.phone || "");
    const bookingPhoneNumberId = normalizePhoneNumberId(booking.phoneNumberId || "");
    const status = booking.status || "";
    const bookingDate = parseSheetDate(booking.lastUpdated || booking.date || "");
    const bookingTime = bookingDate?.getTime?.() || 0;
    const isRecent = !bookingTime || bookingTime >= recentCutoff;

    return bookingPhone === cleanPhone &&
      (!cleanPhoneNumberId || !bookingPhoneNumberId || bookingPhoneNumberId === cleanPhoneNumberId) &&
      isRecent &&
      isSuggestedTimeBookingStatusValue(status);
  });

  matches.sort((a, b) => {
    const rowA = Number(a.rowNumber || 0);
    const rowB = Number(b.rowNumber || 0);
    if (rowA !== rowB) return rowB - rowA;

    const dateA = parseSheetDate(a.lastUpdated || a.date || "")?.getTime() || 0;
    const dateB = parseSheetDate(b.lastUpdated || b.date || "")?.getTime() || 0;
    return dateB - dateA;
  });

  return matches[0] || null;
}

function getSuggestedTimeFromBooking(booking = {}, rememberedContext = null) {
  const rememberedTime = (rememberedContext?.suggestedTime || "").toString().trim();
  if (rememberedTime) return rememberedTime;

  const notes = (booking.notes || "").toString().trim();
  if (!notes) return "";

  const suggestedMatch = notes.match(/(?:Suggested time|الوقت المقترح)\s*:\s*([^\n]+)/i);
  if (suggestedMatch?.[1]) return suggestedMatch[1].trim();

  return notes;
}

function buildSuggestedTimeConfirmedNotesForCustomer(booking = {}, suggestedTime = "", language = "en") {
  const details = getBookingRequestDetails(booking);
  const isArabic = language === "ar";
  const lines = [];

  if (details.preferredDay) {
    lines.push(`${isArabic ? "اليوم" : "Day"}: ${getSmartBookingDayLabel(details.preferredDay, language)}`);
  }

  if (suggestedTime) {
    lines.push(`${isArabic ? "الوقت" : "Time"}: ${suggestedTime}`);
  } else if (details.preferredTime) {
    lines.push(`${isArabic ? "الوقت" : "Time"}: ${details.preferredTime}`);
  }

  if (details.teamMember) lines.push(`${isArabic ? "الموظف" : "Team member"}: ${details.teamMember}`);
  if (details.serviceType) lines.push(`${isArabic ? "الخدمة" : "Service"}: ${details.serviceType}`);

  return lines.join("\n");
}

function buildSuggestedTimeCustomerAckBody(suggestedTime = "", customerName = "", language = "en") {
  const cleanName = cleanCustomerName(customerName || "");
  const isArabic = language === "ar";

  if (isArabic) {
    return [
      `${BUSINESS_NAME_SPACED} ✨`,
      "",
      cleanName ? `تمام ${cleanName} ✅` : "تمام ✅",
      "تم تسجيل موافقتك على الوقت المقترح.",
      suggestedTime ? `الوقت المقترح: ${suggestedTime}` : "",
      "",
      "تم إبلاغ الفريق، وسيتم متابعة تأكيد الموعد لك."
    ].filter(Boolean).join("\n");
  }

  return [
    `${BUSINESS_NAME_SPACED} ✨`,
    "",
    cleanName ? `Done ${cleanName} ✅` : "Done ✅",
    "Your approval for the suggested time has been recorded.",
    suggestedTime ? `Suggested time: ${suggestedTime}` : "",
    "",
    "The team has been notified and will follow up to confirm the appointment."
  ].filter(Boolean).join("\n");
}

function buildSuggestedTimeCustomerDeclineBody(suggestedTime = "", customerName = "", language = "en") {
  const cleanName = cleanCustomerName(customerName || "");
  const isArabic = language === "ar";

  if (isArabic) {
    return [
      `${BUSINESS_NAME_SPACED} ✨`,
      "",
      cleanName ? `تمام ${cleanName}، وصلت ملاحظتك ✅` : "تمام، وصلت ملاحظتك ✅",
      suggestedTime ? `الوقت المقترح كان: ${suggestedTime}` : "",
      "الفريق سيقترح لك وقتاً آخر أو يتابع معك مباشرة."
    ].filter(Boolean).join("\n");
  }

  return [
    `${BUSINESS_NAME_SPACED} ✨`,
    "",
    cleanName ? `Got it ${cleanName} ✅` : "Got it ✅",
    suggestedTime ? `Suggested time was: ${suggestedTime}` : "",
    "The team will suggest another time or follow up with you directly."
  ].filter(Boolean).join("\n");
}

function buildSuggestedTimeStaffNotifyBody({ booking = {}, customerPhone = "", customerName = "", suggestedTime = "", customerReply = "", action = "accepted" } = {}) {
  const isDeclined = action === "declined";
  const isAutoConfirmed = action === "accepted_confirmed" || action === "confirmed";
  const actionTitle = isDeclined
    ? "Customer rejected suggested time ⚠️"
    : (isAutoConfirmed ? "Customer accepted suggested time and booking was confirmed ✅" : "Customer accepted suggested time ✅");
  const details = getBookingRequestDetails(booking);

  return [
    actionTitle,
    "",
    `Branch: ${booking.branch || details.branch || ""}`,
    `Customer: ${customerName || booking.customerName || ""}`,
    `Phone: ${customerPhone || booking.phone || ""}`,
    suggestedTime ? `Suggested time: ${suggestedTime}` : "",
    customerReply ? `Customer reply: ${customerReply}` : "",
    details.requestType ? `Type: ${details.requestType}` : (booking.requestType ? `Type: ${booking.requestType}` : ""),
    "",
    isDeclined
      ? "Please suggest another time or follow up in Team Inbox."
      : (isAutoConfirmed ? "The customer has been notified directly. No Team Inbox confirmation is needed." : "Please confirm the booking in Team Inbox.")
  ].filter(Boolean).join("\n");
}

async function notifyStaffAboutSuggestedTimeCustomerReply({ booking = {}, customerPhone = "", profileName = "", suggestedTime = "", customerReply = "", phoneNumberId = DUBAI_PHONE_NUMBER_ID, rememberedContext = null, action = "accepted" } = {}) {
  const cleanPhoneNumberId = normalizePhoneNumberId(phoneNumberId || booking.phoneNumberId || DUBAI_PHONE_NUMBER_ID);
  const lineConfig = getLineConfig(cleanPhoneNumberId);
  const body = buildSuggestedTimeStaffNotifyBody({
    booking,
    customerPhone,
    customerName: profileName || booking.customerName || "",
    suggestedTime,
    customerReply,
    action
  });

  let numbers = [];
  let routing = getStaffNotificationRouting(cleanPhoneNumberId);

  const rememberedStaff = normalizeWhatsAppRecipientDigits(rememberedContext?.staffNumber || "");
  if (rememberedStaff) {
    numbers = [rememberedStaff];
    routing = {
      ...routing,
      number: rememberedStaff,
      envName: "remembered_staff_suggested_time_context",
      branch: booking.branch || rememberedContext?.branch || lineConfig.branch,
      phoneNumberId: cleanPhoneNumberId
    };
  } else {
    const staffInfo = getStaffNotificationNumbers(cleanPhoneNumberId);
    numbers = staffInfo.numbers || [];
    routing = staffInfo.routing || routing;
  }

  if (!numbers.length) {
    console.log("[Suggested Time Customer Reply] skipped staff notify: no staff number", { customerPhone, phoneNumberId: cleanPhoneNumberId });
    return { ok: false, skipped: true, reason: "no_staff_number" };
  }

  const flowData = {
    branch: booking.branch || rememberedContext?.branch || lineConfig.branch,
    customerName: profileName || booking.customerName || "",
    phone: customerPhone,
    requestType: action === "declined" ? "Suggested Time Rejected" : (action === "accepted_confirmed" ? "Suggested Time Accepted - Confirmed" : "Suggested Time Accepted"),
    serviceInterest: action === "declined" ? "Suggested Time Rejected" : (action === "accepted_confirmed" ? "Suggested Time Accepted - Confirmed" : "Suggested Time Accepted"),
    preferredDay: getBookingRequestDetails(booking).preferredDay || "",
    preferredTime: suggestedTime || getBookingRequestDetails(booking).preferredTime || "",
    notes: customerReply || ""
  };

  const results = [];
  for (const staffNumber of numbers) {
    const textResult = await sendStaffNotificationTextMessage(staffNumber, body, cleanPhoneNumberId, routing);
    const finalResult = await handleStaffTemplateFallbackIfTextBlocked(textResult, {
      staffNumber,
      flowData,
      customerPhone,
      phoneNumberId: cleanPhoneNumberId,
      routing
    });
    results.push({ staffNumber, ...finalResult });
  }

  return { ok: results.every((item) => item.ok), results };
}

async function handleCustomerSuggestedTimeReply({ from, message, originalText, text, incomingPhoneNumberId, lineConfig, profileName, replyLanguage = "en" }) {
  const input = (originalText || text || "").toString().trim();
  if (!input) return false;

  const isAccept = isCustomerAcceptSuggestedTimeText(input);
  const isDecline = isCustomerRejectSuggestedTimeText(input);
  if (!isAccept && !isDecline) return false;

  const booking = await findLatestSuggestedTimeBookingForCustomer(from, incomingPhoneNumberId);
  if (!booking) return false;

  const rememberedContext = getRememberedCustomerSuggestedTimeAction(from);
  const suggestedTime = getSuggestedTimeFromBooking(booking, rememberedContext);
  const action = isDecline ? "declined" : "accepted_confirmed";
  const status = isDecline ? "Customer Rejected Suggested Time" : "Confirmed Appointment";
  const notePrefix = isDecline ? "Customer rejected suggested time" : "Customer accepted suggested time and booking auto-confirmed";
  const updateNotes = [
    suggestedTime ? `Suggested time: ${suggestedTime}` : "",
    `${notePrefix}: ${input}`
  ].filter(Boolean).join("\n");

  logCustomerActionForInbox({
    from,
    message,
    profileName,
    rawText: input,
    fallbackAction: input,
    status: isDecline ? "Customer Rejected Suggested Time" : "Customer Accepted Suggested Time",
    phoneNumberId: incomingPhoneNumberId,
    messageType: isDecline ? "Customer Suggested Time Rejected" : "Customer Suggested Time Accepted"
  });

  if (isDecline) {
    if (booking.rowNumber) {
      await updateBookingRequestStatusInGoogleSheetFromServer({
        rowNumber: booking.rowNumber,
        phone: from,
        phoneNumberId: incomingPhoneNumberId,
        status: "Customer Rejected Suggested Time",
        notes: updateNotes
      });
    }

    setConversationStatus(from, "Customer Rejected Suggested Time");
    await saveConversationStateToGoogleSheetFromServer({
      phone: from,
      phoneNumberId: incomingPhoneNumberId,
      branch: booking.branch || lineConfig.branch,
      status: "Customer Rejected Suggested Time",
      assignee: getBranchTeamAssignee(booking.branch || lineConfig.branch),
      tags: ["Booking", "Suggested Time Rejected"],
      updatedBy: "Customer Suggested Time Reply"
    });
  } else {
    const confirmationNotes = buildSuggestedTimeConfirmedNotesForCustomer(booking, suggestedTime, replyLanguage) || updateNotes;
    const confirmResult = await sendBookingActionUpdateToCustomer({
      booking,
      status: "Confirmed",
      notes: confirmationNotes,
      phoneNumberId: incomingPhoneNumberId,
      updatedBy: "Customer Accepted Suggested Time - Auto Confirm"
    });

    if (!confirmResult.ok) {
      const failedLogBody = [
        "Customer accepted suggested time, but confirmation send failed ⚠️",
        `Branch: ${booking.branch || lineConfig.branch}`,
        `Suggested time: ${suggestedTime || ""}`,
        `Reason: ${confirmResult.error || "Unknown error"}`
      ].filter(Boolean).join("\n");
      addInboxMessage(from, "bot", failedLogBody, "Customer Confirmation Failed", incomingPhoneNumberId, {
        customerName: profileName,
        messageType: "Suggested Time Accepted - Confirmation Failed"
      });

      await notifyStaffAboutSuggestedTimeCustomerReply({
        booking,
        customerPhone: from,
        profileName,
        suggestedTime,
        customerReply: `${input} / confirmation failed: ${confirmResult.error || "Unknown error"}`,
        phoneNumberId: incomingPhoneNumberId,
        rememberedContext,
        action: "accepted"
      });

      const cleanPhone = normalizePhoneDigits(from);
      if (cleanPhone) pendingCustomerSuggestedTimeActionsByPhone.delete(cleanPhone);
      return true;
    }

    setConversationStatus(from, "Confirmed Appointment");
    await saveConversationStateToGoogleSheetFromServer({
      phone: from,
      phoneNumberId: incomingPhoneNumberId,
      branch: booking.branch || lineConfig.branch,
      status: "Confirmed Appointment",
      assignee: getBranchTeamAssignee(booking.branch || lineConfig.branch),
      tags: ["Booking", "Confirmed", "Suggested Time Accepted"],
      updatedBy: "Customer Accepted Suggested Time - Auto Confirm"
    });
  }

  const staffNotifyResult = await notifyStaffAboutSuggestedTimeCustomerReply({
    booking,
    customerPhone: from,
    profileName,
    suggestedTime,
    customerReply: input,
    phoneNumberId: incomingPhoneNumberId,
    rememberedContext,
    action
  });

  const staffLogBody = [
    isDecline ? "Suggested time rejection staff notify sent" : "Suggested time accepted and booking auto-confirm staff notify sent",
    staffNotifyResult?.ok ? "✅" : "⚠️",
    `Branch: ${booking.branch || lineConfig.branch}`,
    `Suggested time: ${suggestedTime || ""}`,
    staffNotifyResult?.reason ? `Reason: ${staffNotifyResult.reason}` : ""
  ].filter(Boolean).join("\n");
  addInboxMessage(from, "bot", staffLogBody, staffNotifyResult?.ok ? "Staff Notify Sent" : "Staff Notify Failed", incomingPhoneNumberId, {
    customerName: profileName,
    messageType: isDecline ? "Suggested Time Rejection Staff Notify" : "Suggested Time Accepted Auto Confirm Staff Notify"
  });

  if (isDecline) {
    const customerAckBody = buildSuggestedTimeCustomerDeclineBody(suggestedTime, profileName, replyLanguage);
    await sendWhatsAppMessage(from, customerAckBody, incomingPhoneNumberId, { replyLanguage, skipAutoLanguage: true });
    addInboxMessage(from, "bot", customerAckBody, "Customer Rejected Suggested Time", incomingPhoneNumberId, {
      customerName: profileName,
      messageType: "Suggested Time Rejection Customer Ack"
    });
  }

  const cleanPhone = normalizePhoneDigits(from);
  if (cleanPhone) pendingCustomerSuggestedTimeActionsByPhone.delete(cleanPhone);

  return true;
}

async function sendBookingActionUpdateToCustomer({ booking = {}, status = "", notes = "", phoneNumberId = DUBAI_PHONE_NUMBER_ID, updatedBy = "Staff Booking Action" }) {
  const customerPhone = normalizePhoneDigits(booking.phone || "");
  if (!customerPhone) {
    return { ok: false, error: "missing_customer_phone" };
  }

  const customerLanguage = await getCustomerLanguageFromHistory(customerPhone, "en");
  const messageBuild = buildBookingCustomerUpdateBody(status, notes, customerLanguage);

  if (!messageBuild.ok) {
    return { ok: false, error: messageBuild.error || "message_build_failed" };
  }

  const buttons = Array.isArray(messageBuild.buttons) ? messageBuild.buttons : [];
  const sendResult = buttons.length
    ? await sendWhatsAppButtonMessage(customerPhone, messageBuild.body, buttons, phoneNumberId, {
        headerImageUrl: BOT_HEADER_IMAGE_URL,
        replyLanguage: customerLanguage,
        skipAutoLanguage: true
      })
    : await sendWhatsAppMessage(customerPhone, messageBuild.body, phoneNumberId, {
        replyLanguage: customerLanguage,
        skipAutoLanguage: true
      });

  if (sendResult?.error) {
    return {
      ok: false,
      error: sendResult.error?.message || "customer_update_send_failed",
      result: sendResult
    };
  }

  if (booking.rowNumber) {
    await updateBookingRequestStatusInGoogleSheetFromServer({
      rowNumber: booking.rowNumber,
      phone: customerPhone,
      phoneNumberId,
      status,
      notes
    });
  }

  const loggedBody = buttons.length ? formatButtonLog(messageBuild.body, buttons) : messageBuild.body;
  addInboxMessage(
    customerPhone,
    "staff",
    loggedBody,
    isApprovedBookingStatus(status) ? "Confirmed Appointment" : "Human Reply",
    phoneNumberId,
    {
      customerName: booking.customerName || "",
      messageType: "Staff Button Action - Customer Update"
    }
  );

  if (isApprovedBookingStatus(status)) {
    setConversationStatus(customerPhone, "Confirmed Appointment");
    await activateAppointmentReminderAfterConfirmation({
      booking: { ...booking, phone: customerPhone, phoneNumberId },
      phoneNumberId,
      notes,
      updatedBy
    });
  }

  return { ok: true, customerPhone, result: sendResult };
}

async function handleStaffBookingAction({ from, message = null, originalText = "", incomingPhoneNumberId = DUBAI_PHONE_NUMBER_ID }) {
  const route = getStaffActionRouteFromNumber(from, incomingPhoneNumberId);
  if (!route.isStaff) return false;

  const text = (originalText || "").toString().trim();
  const action = getStaffBookingActionFromText(text);
  const pendingAction = pendingStaffBookingActionsByStaffNumber.get(route.staffNumber);

  if (pendingAction?.action === "suggest_time" && !action) {
    const booking = pendingAction.booking || {};
    const customerPhone = normalizePhoneDigits(booking.phone || "");
    const phoneNumberId = normalizePhoneNumberId(booking.phoneNumberId || pendingAction.phoneNumberId || route.phoneNumberId);
    const suggestedTime = text;

    if (!suggestedTime) {
      await sendStaffActionAck(route.staffNumber, "Please type the suggested time. Example: Tomorrow 5:00 PM", route);
      return true;
    }

    const sendResult = await sendBookingActionUpdateToCustomer({
      booking,
      status: "Suggested Time",
      notes: suggestedTime,
      phoneNumberId,
      updatedBy: "Staff Suggested Time Button"
    });

    pendingStaffBookingActionsByStaffNumber.delete(route.staffNumber);

    if (!sendResult.ok) {
      await sendStaffActionAck(route.staffNumber, `Suggested time failed ⚠️\n${sendResult.error || "Unknown error"}`, route);
      return true;
    }

    rememberCustomerSuggestedTimeAction({
      customerPhone,
      staffNumber: route.staffNumber,
      booking,
      suggestedTime,
      phoneNumberId,
      branch: route.branch
    });

    await sendStaffActionAck(route.staffNumber, buildStaffActionAckBody("suggest_time_sent", booking, suggestedTime), route);
    console.log("[Staff Booking Action] suggested time sent", JSON.stringify({ staff: route.staffNumber, customerPhone, phoneNumberId, suggestedTime }, null, 2));
    return true;
  }

  if (!action) return false;

  const contextMessageId = getMessageContextId(message);
  const linkedContext = contextMessageId
    ? pendingStaffBookingActionsByTemplateMessageId.get(contextMessageId)
    : null;

  if (!linkedContext) {
    await sendStaffActionAck(
      route.staffNumber,
      `This staff action is not linked to a booking request.
Please use the latest booking alert, or check Team Inbox.`,
      route
    );
    console.log("[Staff Booking Action] missing linked context", JSON.stringify({
      staff: route.staffNumber,
      branch: route.branch,
      action,
      contextMessageId
    }, null, 2));
    return true;
  }

  if (linkedContext.testOnly || linkedContext.routing?.testOnly) {
    await sendStaffActionAck(
      route.staffNumber,
      `Test button received ✅

Action: ${text}
No customer was notified because this was a template test.`,
      route
    );
    console.log("[Staff Booking Action] test-only action ignored", JSON.stringify({
      staff: route.staffNumber,
      branch: route.branch,
      action,
      contextMessageId
    }, null, 2));
    return true;
  }

  const booking = await findPendingBookingForStaffActionContext(linkedContext, route);
  if (!booking) {
    const linkedPhone = normalizePhoneDigits(linkedContext.customerPhone || linkedContext.flowData?.phone || "");
    await sendStaffActionAck(
      route.staffNumber,
      `No pending booking request found for the linked customer${linkedPhone ? ` ${linkedPhone}` : ""}.
Please check Team Inbox.`,
      route
    );
    console.log("[Staff Booking Action] no linked pending booking found", JSON.stringify({
      staff: route.staffNumber,
      branch: route.branch,
      action,
      contextMessageId,
      linkedPhone
    }, null, 2));
    return true;
  }

  const customerPhone = normalizePhoneDigits(booking.phone || linkedContext.customerPhone || linkedContext.flowData?.phone || "");
  const phoneNumberId = normalizePhoneNumberId(booking.phoneNumberId || linkedContext.phoneNumberId || route.phoneNumberId);

  console.log("[Staff Booking Action] received", JSON.stringify({
    staff: route.staffNumber,
    branch: route.branch,
    action,
    customerPhone,
    rowNumber: booking.rowNumber || "",
    phoneNumberId,
    contextMessageId
  }, null, 2));

  if (action === "suggest_time") {
    pendingStaffBookingActionsByStaffNumber.set(route.staffNumber, {
      action: "suggest_time",
      booking,
      branch: route.branch,
      phoneNumberId,
      createdAt: Date.now()
    });
    await sendStaffActionAck(route.staffNumber, buildStaffActionAckBody("suggest_time_waiting", booking), route);
    return true;
  }

  if (action === "confirm") {
    const notes = buildBookingDetailsNoteForCustomer(booking, await getCustomerLanguageFromHistory(customerPhone, "en"));
    const sendResult = await sendBookingActionUpdateToCustomer({
      booking,
      status: "Confirmed",
      notes,
      phoneNumberId,
      updatedBy: "Staff Flow Confirm Button - Direct Customer Confirmation"
    });

    if (!sendResult.ok) {
      await sendStaffActionAck(route.staffNumber, `Confirm failed ⚠️\n${sendResult.error || "Unknown error"}`, route);
      return true;
    }

    await sendStaffActionAck(route.staffNumber, buildStaffActionAckBody("confirm", booking), route);
    return true;
  }

  if (action === "team_will_call") {
    const customerLanguage = await getCustomerLanguageFromHistory(customerPhone, "en");
    const body = buildTeamWillCallCustomerBody(booking.customerName || "", customerLanguage);
    const sendResult = await sendWhatsAppMessage(customerPhone, body, phoneNumberId, {
      replyLanguage: customerLanguage,
      skipAutoLanguage: true
    });

    if (sendResult?.error) {
      await sendStaffActionAck(route.staffNumber, `Team Will Call failed ⚠️\n${sendResult.error?.message || "Unknown error"}`, route);
      return true;
    }

    if (booking.rowNumber) {
      await updateBookingRequestStatusInGoogleSheetFromServer({
        rowNumber: booking.rowNumber,
        phone: customerPhone,
        phoneNumberId,
        status: "Team Will Call",
        notes: "Team will contact customer shortly"
      });
    }

    addInboxMessage(customerPhone, "staff", body, "Team Will Call", phoneNumberId, {
      customerName: booking.customerName || "",
      messageType: "Staff Button Action - Team Will Call"
    });

    setConversationStatus(customerPhone, "Need Follow-up");
    await saveConversationStateToGoogleSheetFromServer({
      phone: customerPhone,
      phoneNumberId,
      branch: booking.branch || route.branch,
      status: "Need Follow-up",
      assignee: getBranchTeamAssignee(booking.branch || route.branch),
      tags: ["Booking", "Team Will Call"],
      updatedBy: "Staff Team Will Call Button"
    });

    await sendStaffActionAck(route.staffNumber, buildStaffActionAckBody("team_will_call", booking), route);
    return true;
  }

  return false;
}

async function notifyStaffAboutSmartBooking(draft = {}, customerPhone = "", profileName = "", preferredTime = "") {
  const finalDraft = mergeSmartBookingStaffIntoDraft(draft, draft.rawRequest || "");
  const isAbuDhabi = finalDraft.branch === "Abu Dhabi";
  const routingPhoneNumberId = isAbuDhabi ? ABU_DHABI_PHONE_NUMBER_ID : DUBAI_PHONE_NUMBER_ID;
  const envName = isAbuDhabi ? "ABU_DHABI_STAFF_NUMBER" : "DUBAI_STAFF_NUMBER";
  const rawStaffNumber = isAbuDhabi
    ? (process.env.ABU_DHABI_STAFF_NUMBER || ABU_DHABI_STAFF_NUMBER || DEFAULT_ABU_DHABI_STAFF_NUMBER || "")
    : (process.env.DUBAI_STAFF_NUMBER || DUBAI_STAFF_NUMBER || DEFAULT_DUBAI_STAFF_NUMBER || "");
  const staffNumber = normalizeWhatsAppRecipientDigits(rawStaffNumber);

  const smartRequestType = finalDraft.requestType || (finalDraft.serviceType ? "Service Appointment" : "WhatsApp Smart Natural Booking V3.9.14");
  const smartSource = finalDraft.directConsultationChatBooking
    ? "Source: WhatsApp Direct Consultation Chat Booking V3.9.34"
    : "Source: WhatsApp Smart Natural Booking V3.9.14";

  const flowData = {
    branch: finalDraft.branch || getLineConfig(routingPhoneNumberId).branch,
    customerName: profileName || "",
    phone: customerPhone || "",
    requestType: smartRequestType,
    serviceInterest: smartRequestType,
    preferredDay: finalDraft.preferredDay || "",
    preferredTime: preferredTime || "",
    teamMember: (finalDraft.skipStaffQuestion ? "" : (finalDraft.teamMember || "")),
    serviceType: finalDraft.serviceType || "",
    notes: finalDraft.urgent ? `${smartSource} - Urgent request` : smartSource
  };

  console.log(`[Smart Booking Direct Staff Notify] preparing branch=${flowData.branch} fromPhoneNumberId=${routingPhoneNumberId} to=${staffNumber || "MISSING"} env=${envName} raw=${rawStaffNumber || "MISSING"} teamMember=${flowData.teamMember || ""}`);

  if (!staffNumber) {
    console.log(`[Smart Booking Direct Staff Notify] skipped branch=${flowData.branch} reason=missing_staff_number env=${envName}`);
    return {
      ok: false,
      skipped: true,
      reason: "missing_staff_number",
      routingPhoneNumberId,
      flowData,
      results: []
    };
  }

  const routing = {
    number: staffNumber,
    branch: flowData.branch,
    phoneNumberId: routingPhoneNumberId,
    envName,
    branchEnvName: envName,
    fallbackUsed: !process.env[envName],
    hasNumber: true
  };

  const body = buildStaffBookingNotificationBody(flowData, customerPhone);
  const textResult = await sendStaffNotificationTextMessage(staffNumber, body, routingPhoneNumberId, routing);
  const directResult = await handleStaffTemplateFallbackIfTextBlocked(textResult, {
    staffNumber,
    flowData,
    customerPhone,
    phoneNumberId: routingPhoneNumberId,
    routing
  });

  console.log("[Smart Booking Direct Staff Notify] result", JSON.stringify({
    ok: directResult?.ok,
    status: directResult?.status,
    branch: flowData.branch,
    phoneNumberId: routingPhoneNumberId,
    envName,
    staffNumber,
    teamMember: flowData.teamMember || "",
    templateFallbackAttempted: Boolean(directResult?.templateFallbackAttempted),
    watchedForTemplateFallback: Boolean(directResult?.watchedForTemplateFallback),
    result: directResult?.result || null,
    templateFallback: directResult?.templateFallback || null
  }, null, 2));

  return {
    ok: Boolean(directResult?.ok),
    direct: true,
    routingPhoneNumberId,
    flowData,
    results: [{ staffNumber, ...directResult }]
  };
}

async function handleSmartWhatsAppBooking({ from, message, originalText, text, incomingPhoneNumberId, lineConfig, profileName, replyLanguage = "en", forceConsultationChatBooking = false }) {
  const input = originalText || text || "";
  let existingDraft = smartBookingDrafts[from] || null;

  const chosenDayButton = getSmartBookingDayFromButton(input);
  const explicitWeekday = detectSmartBookingExplicitWeekday(input);
  const naturalDay = detectSmartBookingDay(input);
  const detectedDay = explicitWeekday || chosenDayButton || naturalDay;
  const inputTime = getSmartBookingTimeFromText(input);

  console.log(`[Smart Booking Router] input=${JSON.stringify(input)} from=${from} existingDraft=${Boolean(existingDraft)} language=${replyLanguage} detectedDay=${detectedDay || ""} time=${inputTime.ok ? inputTime.time : ""} forceConsultationChatBooking=${Boolean(forceConsultationChatBooking)}`);

  const logSmartCustomerReply = (status = "Smart Booking", messageType = "Customer Smart Booking Reply") => {
    logCustomerActionForInbox({
      from,
      message,
      profileName,
      rawText: input,
      fallbackAction: input,
      status,
      phoneNumberId: incomingPhoneNumberId,
      messageType
    });
  };

  if (existingDraft) {
    existingDraft = mergeSmartBookingStaffIntoDraft(existingDraft, input || existingDraft.rawRequest || "");

    // V31.5.8.60.3.9.32:
    // Keep direct consultation chat booking branch locked to the WhatsApp line.
    // This makes Abu Dhabi run the same chat-booking cycle as Dubai, but routed to Abu Dhabi.
    if (existingDraft.directConsultationChatBooking || existingDraft.skipStaffQuestion) {
      existingDraft.branch = lineConfig.branch || existingDraft.branch || "Dubai";
      existingDraft.phoneNumberId = incomingPhoneNumberId;
      existingDraft.teamMember = "";
      existingDraft.requestType = "Consultation Booking";
      existingDraft.directConsultationChatBooking = true;
      existingDraft.skipStaffQuestion = true;
    }

    smartBookingDrafts[from] = existingDraft;
  }

  // A plain staff name such as "Ahmed" / "احمد" should only answer an active
  // specialist question. It must not start a brand-new booking after the previous
  // booking was already submitted, because that creates the extra "choose day" loop.
  if (!existingDraft && isSmartBookingStandaloneStaffOnly(input)) {
    console.log(`[Smart Booking Router] ignored standalone staff name without active draft: ${JSON.stringify(input)}`);
    return false;
  }

  if (!existingDraft && !forceConsultationChatBooking && !isSmartBookingNaturalRequest(input)) return false;

  const askForDay = async (draft) => {
    draft.waitingForWeekday = false;
    draft.waitingForTime = false;
    draft.waitingForStaff = false;
    smartBookingDrafts[from] = draft;
    setConversationStatus(from, "Smart Booking - Choose Day");
    const askDayBody = buildSmartBookingAskDayBody(draft, profileName, replyLanguage);
    const dayButtons = getSmartBookingWeekdayButtons(replyLanguage);
    await sendWhatsAppButtonMessage(from, askDayBody, dayButtons, incomingPhoneNumberId, { replyLanguage });
    addInboxMessage(from, "bot", formatButtonLog(askDayBody, dayButtons), "Smart Booking - Choose Day", incomingPhoneNumberId, { customerName: profileName, messageType: "Smart Booking Ask Day" });
    return true;
  };

  const askForWeekday = async (draft) => {
    draft.waitingForWeekday = true;
    draft.waitingForTime = false;
    draft.waitingForStaff = false;
    smartBookingDrafts[from] = draft;
    setConversationStatus(from, "Smart Booking - Choose Weekday");
    const weekdayBody = buildSmartBookingAskWeekdayBody(draft, profileName, replyLanguage);
    await sendWhatsAppMessage(from, weekdayBody, incomingPhoneNumberId, { replyLanguage, skipAutoLanguage: true });
    addInboxMessage(from, "bot", weekdayBody, "Smart Booking - Choose Weekday", incomingPhoneNumberId, { customerName: profileName, messageType: "Smart Booking Ask Weekday" });
    return true;
  };

  const askForTime = async (draft) => {
    draft.waitingForWeekday = false;
    draft.waitingForStaff = false;
    draft.waitingForTime = true;
    smartBookingDrafts[from] = draft;
    setConversationStatus(from, "Smart Booking - Choose Time");
    const askTimeBody = buildSmartBookingAskTimeBody(draft, profileName, replyLanguage);
    await sendWhatsAppMessage(from, askTimeBody, incomingPhoneNumberId, { replyLanguage, skipAutoLanguage: true });
    addInboxMessage(from, "bot", askTimeBody, "Smart Booking - Choose Time", incomingPhoneNumberId, { customerName: profileName, messageType: "Smart Booking Ask Time" });
    return true;
  };

  const askForStaff = async (draft) => {
    draft.waitingForWeekday = false;
    draft.waitingForTime = false;
    draft.waitingForStaff = true;
    smartBookingDrafts[from] = draft;
    setConversationStatus(from, "Smart Booking - Choose Specialist");
    const staffBody = buildSmartBookingAskStaffBody(draft, profileName, draft.preferredTime || "", replyLanguage);
    const staffButtons = getSmartBookingStaffPreferenceButtons(replyLanguage);
    await sendWhatsAppButtonMessage(from, staffBody, staffButtons, incomingPhoneNumberId, { replyLanguage });
    addInboxMessage(from, "bot", formatButtonLog(staffBody, staffButtons), "Smart Booking - Choose Specialist", incomingPhoneNumberId, { customerName: profileName, messageType: "Smart Booking Ask Specialist" });
    return true;
  };

  const submitSmartBooking = async (draft, selectedTime, originalSelection = "") => {
    const finalDraft = mergeSmartBookingStaffIntoDraft(draft, `${draft.rawRequest || ""} ${originalSelection || ""}`.trim());
    const selectedBranch = finalDraft.branch || lineConfig.branch || "Dubai";
    finalDraft.branch = selectedBranch;
    finalDraft.preferredTime = selectedTime;

    const requestMessage = buildSmartBookingRequestMessage(finalDraft, selectedTime, finalDraft.rawRequest || originalSelection || input);
    setConversationStatus(from, "Booking Request");
    await saveConversationStateToGoogleSheetFromServer({
      phone: from,
      phoneNumberId: incomingPhoneNumberId,
      branch: selectedBranch,
      status: "Booking Request",
      assignee: getBranchTeamAssignee(selectedBranch),
      tags: ["Booking", finalDraft.requestType || "Smart Natural Booking V3.14", "Need Confirmation"],
      updatedBy: finalDraft.directConsultationChatBooking ? "WhatsApp Direct Consultation Chat Booking V3.9.34" : "WhatsApp Smart Natural Booking V3.14"
    });
    await saveBookingRequestToGoogleSheetFromServer({
      phone: from,
      phoneNumberId: incomingPhoneNumberId,
      customerName: profileName,
      branch: selectedBranch,
      message: requestMessage,
      requestType: finalDraft.requestType || "WhatsApp Smart Natural Booking V3.14",
      bookingStatus: "Pending"
    });
    addInboxMessage(from, "customer", requestMessage, "Booking Request", incomingPhoneNumberId, { customerName: profileName, messageType: "WhatsApp Smart Natural Booking Submit" });

    let staffNotifyResult = null;
    try {
      staffNotifyResult = await notifyStaffAboutSmartBooking(finalDraft, from, profileName, selectedTime);
    } catch (error) {
      staffNotifyResult = { ok: false, error: error?.message || String(error), routingPhoneNumberId: finalDraft.branch === "Abu Dhabi" ? ABU_DHABI_PHONE_NUMBER_ID : DUBAI_PHONE_NUMBER_ID };
      console.log("Smart booking staff notification failed:");
      console.log(error);
    }

    const staffNotifyLogBody = buildSmartBookingStaffNotifyLogBody(staffNotifyResult, finalDraft, staffNotifyResult?.routingPhoneNumberId || "");
    addInboxMessage(
      from,
      "bot",
      staffNotifyLogBody,
      staffNotifyResult?.ok ? "Staff Notify Sent" : "Staff Notify Failed",
      incomingPhoneNumberId,
      {
        customerName: profileName,
        messageType: staffNotifyResult?.ok ? "Smart Booking Staff Notify Sent" : "Smart Booking Staff Notify Failed"
      }
    );

    delete smartBookingDrafts[from];
    const confirmationBody = buildSmartBookingConfirmationBody(finalDraft, selectedTime, replyLanguage);
    await sendWhatsAppMessage(from, confirmationBody, incomingPhoneNumberId, { replyLanguage, skipAutoLanguage: true });
    addInboxMessage(from, "bot", confirmationBody, "Booking Request", incomingPhoneNumberId, { customerName: profileName, messageType: "Smart Booking Confirmation" });
    return true;
  };


  if (existingDraft && existingDraft.waitingForBookingConfirm) {
    logSmartCustomerReply("Availability Reply", "Customer Availability Reply");
    existingDraft = mergeSmartBookingStaffIntoDraft(existingDraft, input || existingDraft.rawRequest || "");

    if (isSmartBookingNegativeConfirmationText(input)) {
      delete smartBookingDrafts[from];
      setConversationStatus(from, "Availability - Booking Declined");
      const noBookingBody = buildSmartBookingNoBookingBody(profileName, replyLanguage);
      await sendWhatsAppMessage(from, noBookingBody, incomingPhoneNumberId, { replyLanguage, skipAutoLanguage: true });
      addInboxMessage(from, "bot", noBookingBody, "Availability - Booking Declined", incomingPhoneNumberId, { customerName: profileName, messageType: "Availability Booking Declined Reply" });
      return true;
    }

    if (isSmartBookingAskTeamText(input)) {
      delete smartBookingDrafts[from];
      setConversationStatus(from, "Talk to Team");
      const teamBody = buildTeamHandoffBody(profileName);
      const localizedTeamBody = cleanLocalizedReplyBody(teamBody, replyLanguage);
      await sendWhatsAppMessage(from, localizedTeamBody, incomingPhoneNumberId, { replyLanguage, skipAutoLanguage: true });
      addInboxMessage(from, "bot", localizedTeamBody, "Talk to Team", incomingPhoneNumberId, { customerName: profileName, messageType: "Availability Ask Team Handoff" });
      return true;
    }

    if (isSmartBookingChangeTimeText(input)) {
      return askForTime(existingDraft);
    }

    if (!isSmartBookingBookNowText(input)) {
      const body = buildSmartAvailabilityConfirmBody(existingDraft, profileName, replyLanguage);
      const buttons = getAvailabilityConfirmButtons(replyLanguage);
      await sendWhatsAppButtonMessage(from, body, buttons, incomingPhoneNumberId, { replyLanguage, skipAutoLanguage: true });
      addInboxMessage(from, "bot", formatButtonLog(body, buttons), "Availability Question", incomingPhoneNumberId, { customerName: profileName, messageType: "Availability Confirm Retry" });
      return true;
    }

    existingDraft.waitingForBookingConfirm = false;
    smartBookingDrafts[from] = existingDraft;

    if (!existingDraft.preferredDay) {
      return askForDay(existingDraft);
    }

    if (existingDraft.preferredDay === "This Week") {
      return askForWeekday(existingDraft);
    }

    if (!existingDraft.teamMember && !existingDraft.skipStaffQuestion) {
      return askForStaff(existingDraft);
    }

    if (existingDraft.preferredTime) {
      return submitSmartBooking(existingDraft, existingDraft.preferredTime, input);
    }

    return askForTime(existingDraft);
  }

  if (existingDraft && detectedDay) {
    logSmartCustomerReply("Smart Booking - Day Reply", "Customer Smart Booking Day Reply");
    existingDraft = mergeSmartBookingStaffIntoDraft(existingDraft, input || existingDraft.rawRequest || "");
    existingDraft.preferredDay = detectedDay;
    existingDraft.rawRequest = existingDraft.rawRequest || input;
    if (inputTime.ok) existingDraft.preferredTime = inputTime.time;

    if (existingDraft.preferredDay === "This Week") {
      return askForWeekday(existingDraft);
    }

    if (!existingDraft.teamMember && !existingDraft.skipStaffQuestion) {
      return askForStaff(existingDraft);
    }

    if (existingDraft.preferredTime) {
      return submitSmartBooking(existingDraft, existingDraft.preferredTime, input);
    }

    return askForTime(existingDraft);
  }

  if (existingDraft && existingDraft.waitingForWeekday) {
    logSmartCustomerReply("Smart Booking - Weekday Reply", "Customer Smart Booking Weekday Reply");
    existingDraft = mergeSmartBookingStaffIntoDraft(existingDraft, input || existingDraft.rawRequest || "");
    const weekday = detectedDay;
    if (!weekday) {
      const retryDay = replyLanguage === "ar"
        ? "اكتب اليوم المناسب مثل: الاثنين أو الثلاثاء."
        : "Please type the suitable day, like Monday or Tuesday.";
      await sendWhatsAppMessage(from, retryDay, incomingPhoneNumberId, { replyLanguage, skipAutoLanguage: true });
      addInboxMessage(from, "bot", retryDay, "Smart Booking - Choose Weekday", incomingPhoneNumberId, { customerName: profileName, messageType: "Smart Booking Retry Weekday" });
      return true;
    }

    existingDraft.preferredDay = weekday;
    if (inputTime.ok) existingDraft.preferredTime = inputTime.time;

    if (!existingDraft.teamMember && !existingDraft.skipStaffQuestion) {
      return askForStaff(existingDraft);
    }

    if (existingDraft.preferredTime) {
      return submitSmartBooking(existingDraft, existingDraft.preferredTime, input);
    }

    return askForTime(existingDraft);
  }

  if (existingDraft && existingDraft.waitingForStaff) {
    logSmartCustomerReply("Smart Booking - Specialist Reply", "Customer Smart Booking Specialist Reply");
    const detectedStaff = detectSmartBookingStaff(input || "");
    const noPreference = isSmartBookingAnySpecialistText(input || "");

    if (!detectedStaff && !noPreference) {
      const retryStaff = buildSmartBookingAskStaffBody(existingDraft, profileName, existingDraft.preferredTime || "", replyLanguage);
      const retryButtons = getSmartBookingStaffPreferenceButtons(replyLanguage);
      await sendWhatsAppButtonMessage(from, retryStaff, retryButtons, incomingPhoneNumberId, { replyLanguage });
      addInboxMessage(from, "bot", formatButtonLog(retryStaff, retryButtons), "Smart Booking - Choose Specialist", incomingPhoneNumberId, { customerName: profileName, messageType: "Smart Booking Retry Specialist" });
      return true;
    }

    if (detectedStaff) {
      existingDraft.branch = detectedStaff.branch || existingDraft.branch || lineConfig.branch || "Dubai";
      existingDraft.teamMember = detectedStaff.name || "";
    } else {
      existingDraft.teamMember = "Any Available";
      existingDraft.branch = existingDraft.branch || lineConfig.branch || "Dubai";
    }

    existingDraft.waitingForStaff = false;
    if (inputTime.ok) existingDraft.preferredTime = inputTime.time;
    smartBookingDrafts[from] = existingDraft;

    if (existingDraft.preferredTime) {
      return submitSmartBooking(existingDraft, existingDraft.preferredTime, input);
    }

    return askForTime(existingDraft);
  }

  if (existingDraft && existingDraft.waitingForTime) {
    logSmartCustomerReply("Smart Booking - Time Reply", "Customer Smart Booking Time Reply");
    existingDraft = mergeSmartBookingStaffIntoDraft(existingDraft, input || existingDraft.rawRequest || "");
    smartBookingDrafts[from] = existingDraft;
    const parsedTime = getSmartBookingTimeFromText(input);
    if (!parsedTime.ok) {
      const invalidBody = buildSmartBookingInvalidTimeBody(parsedTime.reason, replyLanguage);
      await sendWhatsAppMessage(from, invalidBody, incomingPhoneNumberId, { replyLanguage, skipAutoLanguage: true });
      addInboxMessage(from, "bot", invalidBody, "Smart Booking - Choose Time", incomingPhoneNumberId, { customerName: profileName, messageType: "Smart Booking Invalid Time" });
      return true;
    }

    return submitSmartBooking(existingDraft, parsedTime.time, input);
  }

  const staff = detectSmartBookingStaff(input);
  const detectedDayForNewDraft = detectedDay;
  const directConsultationChatBooking = Boolean(forceConsultationChatBooking || isDirectConsultationChatBookingText(input));
  const branch = directConsultationChatBooking ? (lineConfig.branch || "Dubai") : (staff?.branch || lineConfig.branch || "Dubai");
  const draft = {
    branch,
    preferredDay: detectedDayForNewDraft || "",
    preferredTime: inputTime.ok ? inputTime.time : "",
    teamMember: directConsultationChatBooking ? "" : (staff?.name || ""),
    serviceType: directConsultationChatBooking ? "" : detectSmartBookingServiceType(input),
    requestType: directConsultationChatBooking ? "Consultation Booking" : "",
    directConsultationChatBooking,
    skipStaffQuestion: directConsultationChatBooking,
    urgent: isSmartBookingUrgentText(input),
    rawRequest: input,
    startedAt: getDubaiTimestamp(),
    phoneNumberId: incomingPhoneNumberId,
    waitingForTime: false,
    waitingForWeekday: false,
    waitingForStaff: false
  };
  smartBookingDrafts[from] = draft;

  addInboxMessage(from, "customer", buildCustomerActionBody(profileName, input), "Smart Booking", incomingPhoneNumberId, { customerName: profileName, messageType: "Customer Smart Natural Booking Request" });

  if (!draft.preferredDay) {
    setConversationStatus(from, "Smart Booking - Choose Day");
    const askDayBody = buildSmartBookingAskDayBody(draft, profileName, replyLanguage);
    const dayButtons = getSmartBookingWeekdayButtons(replyLanguage);
    await sendWhatsAppButtonMessage(from, askDayBody, dayButtons, incomingPhoneNumberId, { replyLanguage });
    addInboxMessage(from, "bot", formatButtonLog(askDayBody, dayButtons), "Smart Booking - Choose Day", incomingPhoneNumberId, { customerName: profileName, messageType: "Smart Booking Ask Day" });
    return true;
  }

  if (draft.preferredDay === "This Week") {
    return askForWeekday(draft);
  }

  if (!draft.teamMember && !draft.skipStaffQuestion) {
    return askForStaff(draft);
  }

  if (draft.preferredTime) {
    return submitSmartBooking(draft, draft.preferredTime, input);
  }

  return askForTime(draft);
}

