function buildStaffBookingAlertTemplateValues(flowData = {}, customerPhone = "") {
  return [
    flowData.branch || "Dubai",
    flowData.customerName || "Customer",
    customerPhone || flowData.phone || "",
    flowData.preferredDay || "",
    flowData.preferredTime || "",
    flowData.teamMember || "Any Available"
  ].map((value) => (value || "-").toString());
}

async function sendStaffBookingAlertTemplateMessage(to, flowData = {}, customerPhone = "", phoneNumberId = DUBAI_PHONE_NUMBER_ID, routing = {}) {
  const finalPhoneNumberId = normalizePhoneNumberId(phoneNumberId || DUBAI_PHONE_NUMBER_ID);
  const templateName = getStaffBookingAlertTemplateName(flowData.branch || routing.branch || "");
  const templateValues = buildStaffBookingAlertTemplateValues(flowData, customerPhone);

  console.log(`[Staff Template Fallback] sending template=${templateName} branch=${flowData.branch || routing.branch || ""} fromPhoneNumberId=${finalPhoneNumberId} to=${to} env=${routing.envName || "UNKNOWN"}`);

  const templateResult = await sendWhatsAppTemplate(
    to,
    templateName,
    finalPhoneNumberId,
    STAFF_BOOKING_ALERT_TEMPLATE_LANGUAGE,
    {
      includeHeaderImage: Boolean(STAFF_BOOKING_ALERT_TEMPLATE_HEADER_IMAGE_URL),
      headerImageUrl: STAFF_BOOKING_ALERT_TEMPLATE_HEADER_IMAGE_URL,
      bodyParameters: templateValues
    }
  );

  console.log("[Staff Template Fallback] result", JSON.stringify({
    ok: templateResult?.ok,
    status: templateResult?.status,
    templateName,
    branch: flowData.branch || routing.branch || "",
    to,
    result: templateResult?.result || null
  }, null, 2));

  let actionContextMessageId = "";
  if (templateResult?.ok) {
    actionContextMessageId = rememberStaffBookingActionContextFromTemplateResult(templateResult, {
      staffNumber: to,
      flowData,
      customerPhone,
      phoneNumberId: finalPhoneNumberId,
      routing,
      testOnly: Boolean(routing?.testOnly)
    });
  }

  return {
    ...templateResult,
    templateName,
    templateFallback: true,
    actionContextMessageId
  };
}

function rememberStaffTemplateFallbackCandidate(textResult = {}, context = {}) {
  const messageId = getWhatsAppTemplateMessageId(textResult?.result || {});

  if (!messageId) {
    return "";
  }

  pendingStaffTemplateFallbackByMessageId.set(messageId, {
    ...context,
    createdAt: Date.now()
  });

  // Keep memory small and remove old entries after roughly 24 hours.
  const cutoff = Date.now() - (24 * 60 * 60 * 1000);
  for (const [id, item] of pendingStaffTemplateFallbackByMessageId.entries()) {
    if ((item?.createdAt || 0) < cutoff) {
      pendingStaffTemplateFallbackByMessageId.delete(id);
    }
  }

  return messageId;
}

async function handleStaffTemplateFallbackIfTextBlocked(textResult = {}, context = {}) {
  const resultPayload = textResult?.result || {};

  if (textResult?.ok) {
    const messageId = rememberStaffTemplateFallbackCandidate(textResult, context);
    if (messageId) {
      console.log(`[Staff Template Fallback] text accepted; watching messageId=${messageId} for async 131047 failure`);
    }

    return {
      ...textResult,
      watchedForTemplateFallback: Boolean(messageId)
    };
  }

  if (!isReengagementErrorResult(resultPayload)) {
    return textResult;
  }

  console.log("[Staff Template Fallback] text blocked synchronously by 131047; sending approved template now.");

  const templateResult = await sendStaffBookingAlertTemplateMessage(
    context.staffNumber,
    context.flowData,
    context.customerPhone,
    context.phoneNumberId,
    context.routing
  );

  return {
    ...textResult,
    templateFallbackAttempted: true,
    templateFallback: templateResult,
    ok: Boolean(templateResult?.ok)
  };
}

async function handleStaffTemplateFallbackFromStatus(status = {}, statusValue = {}) {
  if (!status || status.status !== "failed" || !isReengagementStatus(status)) {
    return false;
  }

  const messageId = (status.id || "").toString().trim();
  const context = pendingStaffTemplateFallbackByMessageId.get(messageId);

  if (!context) {
    console.log("[Staff Template Fallback] 131047 status received but no pending staff context found", {
      messageId,
      recipientId: status.recipient_id || "",
      phoneNumberId: statusValue?.metadata?.phone_number_id || ""
    });
    return false;
  }

  pendingStaffTemplateFallbackByMessageId.delete(messageId);

  console.log("[Staff Template Fallback] async 131047 detected; sending approved staff template", {
    messageId,
    staffNumber: context.staffNumber,
    branch: context.flowData?.branch || "",
    phoneNumberId: context.phoneNumberId || ""
  });

  await sendStaffBookingAlertTemplateMessage(
    context.staffNumber,
    context.flowData,
    context.customerPhone,
    context.phoneNumberId,
    context.routing
  );

  return true;
}

async function handleWhatsAppStatusUpdates(value = {}) {
  const statuses = Array.isArray(value?.statuses) ? value.statuses : [];

  for (const status of statuses) {
    await handleStaffTemplateFallbackFromStatus(status, value);
  }
}

function parseSheetDate(value) {
  if (!value) return null;

  const date = new Date(value);

  if (!Number.isNaN(date.getTime())) {
    return date;
  }

  return null;
}

function getReminderKey(message) {
  const phone = normalizePhoneDigits(message.phone);
  const phoneNumberId = normalizePhoneNumberId(message.phoneNumberId || DUBAI_PHONE_NUMBER_ID);
  return `${phone}|${phoneNumberId}`;
}

function isFollowUpReminderRow(message) {
  const messageType = normalizeText(message.messageType);
  const status = normalizeText(message.status);
  const body = normalizeText(message.body);

  return (
    messageType === "service follow-up reminder" ||
    messageType === "service follow-up template test" ||
    status === "follow-up sent" ||
    status === "follow-up test" ||
    body.includes(FOLLOW_UP_TEMPLATE_NAME.toLowerCase()) ||
    body.includes(FOLLOW_UP_TEMPLATE_NAME_DUBAI.toLowerCase()) ||
    body.includes(FOLLOW_UP_TEMPLATE_NAME_ABU_DHABI.toLowerCase())
  );
}

function buildLatestOptInRecords(messages) {
  const records = new Map();
  const sorted = [...messages].sort((a, b) => {
    const dateA = parseSheetDate(a.time || a.opt_in_date || a.opt_out_date)?.getTime() || 0;
    const dateB = parseSheetDate(b.time || b.opt_in_date || b.opt_out_date)?.getTime() || 0;
    return dateA - dateB;
  });

  for (const message of sorted) {
    const phone = normalizePhoneDigits(message.phone);
    if (!phone) continue;

    const phoneNumberId = normalizePhoneNumberId(message.phoneNumberId || DUBAI_PHONE_NUMBER_ID);
    const key = getReminderKey({ phone, phoneNumberId });
    const current = records.get(key) || {
      phone,
      customerName: message.customerName || "",
      branch: getLineConfig(phoneNumberId).branch,
      phoneNumberId,
      optedIn: false,
      optedOut: false,
      optInDate: null,
      optOutDate: null,
      reminderSentDate: null
    };

    if (message.customerName) {
      current.customerName = message.customerName;
    }

    if (message.opt_in === "yes" || normalizeText(message.messageType) === "opt-in") {
      current.optedIn = true;
      current.optedOut = false;
      current.optInDate = parseSheetDate(message.opt_in_date || message.time) || current.optInDate || new Date();
      current.optOutDate = null;
      current.phoneNumberId = phoneNumberId;
      current.branch = getLineConfig(phoneNumberId).branch;
    }

    if (message.opt_out === "yes" || normalizeText(message.messageType) === "opt-out") {
      current.optedOut = true;
      current.optedIn = false;
      current.optOutDate = parseSheetDate(message.opt_out_date || message.time) || current.optOutDate || new Date();
      current.phoneNumberId = phoneNumberId;
      current.branch = getLineConfig(phoneNumberId).branch;
    }

    if (isFollowUpReminderRow(message)) {
      const reminderDate = parseSheetDate(message.time) || new Date();
      if (!current.reminderSentDate || reminderDate > current.reminderSentDate) {
        current.reminderSentDate = reminderDate;
      }
    }

    records.set(key, current);
  }

  return Array.from(records.values());
}

function getDueFollowUpReminders(messages, delayDays = FOLLOW_UP_DELAY_DAYS) {
  const now = new Date();
  const delayMs = Number(delayDays) * 24 * 60 * 60 * 1000;

  return buildLatestOptInRecords(messages).filter((record) => {
    if (!record.optedIn) return false;
    if (record.optedOut) return false;
    if (!record.optInDate) return false;
    if (record.reminderSentDate && record.reminderSentDate >= record.optInDate) return false;

    return now.getTime() - record.optInDate.getTime() >= delayMs;
  });
}

function findFollowUpOptRecord(messages = [], phone = "", phoneNumberId = "") {
  const cleanPhone = normalizePhoneDigits(phone);
  const cleanPhoneNumberId = normalizePhoneNumberId(phoneNumberId || "");

  if (!cleanPhone) {
    return null;
  }

  return buildLatestOptInRecords(messages).find((record) => {
    const recordPhone = normalizePhoneDigits(record.phone);
    const recordPhoneNumberId = normalizePhoneNumberId(record.phoneNumberId || "");

    return recordPhone === cleanPhone &&
      (!cleanPhoneNumberId || recordPhoneNumberId === cleanPhoneNumberId);
  }) || null;
}

function isCustomerOptedOutForFollowUps(messages = [], phone = "", phoneNumberId = "") {
  const record = findFollowUpOptRecord(messages, phone, phoneNumberId);
  return Boolean(record && record.optedOut);
}

function getReminderBodyForLog(phoneNumberId = DUBAI_PHONE_NUMBER_ID) {
  return `Template sent: ${getFollowUpTemplateName(phoneNumberId)}`;
}

function getAppointmentReminderBodyForLog(phoneNumberId = DUBAI_PHONE_NUMBER_ID, appointmentAt = null) {
  const templateName = getAppointmentReminderTemplateName(phoneNumberId);
  const at = appointmentAt instanceof Date && !Number.isNaN(appointmentAt.getTime())
    ? appointmentAt.toISOString()
    : "";
  return [`Appointment 1-hour reminder sent: ${templateName}`, at ? `Appointment at: ${at}` : ""].filter(Boolean).join("\n");
}

function isAppointmentReminderRow(message) {
  const messageType = normalizeText(message.messageType);
  const status = normalizeText(message.status);
  const body = normalizeText(message.body);

  return messageType === "appointment 1-hour reminder" ||
    status === "appointment reminder sent" ||
    body.includes("appointment 1-hour reminder sent") ||
    body.includes(APPOINTMENT_REMINDER_TEMPLATE_NAME_DUBAI.toLowerCase()) ||
    body.includes(APPOINTMENT_REMINDER_TEMPLATE_NAME_ABU_DHABI.toLowerCase());
}

function getDubaiDatePartsFromDate(date = new Date()) {
  const formatter = new Intl.DateTimeFormat("en-CA", {
    timeZone: "Asia/Dubai",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false
  });

  const parts = Object.fromEntries(formatter.formatToParts(date).map((part) => [part.type, part.value]));
  return {
    year: Number(parts.year),
    month: Number(parts.month),
    day: Number(parts.day),
    hour: Number(parts.hour),
    minute: Number(parts.minute),
    second: Number(parts.second)
  };
}

function getDubaiDatePartsFromSheetValue(value = "") {
  const text = (value || "").toString().trim();
  const match = text.match(/(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})/);

  if (match) {
    return {
      month: Number(match[1]),
      day: Number(match[2]),
      year: Number(match[3])
    };
  }

  const parsed = parseSheetDate(text);
  if (parsed) {
    return getDubaiDatePartsFromDate(parsed);
  }

  return getDubaiDatePartsFromDate(new Date());
}

function addDaysToDubaiParts(parts = {}, days = 0) {
  const date = new Date(Date.UTC(Number(parts.year || 1970), Number(parts.month || 1) - 1, Number(parts.day || 1) + Number(days || 0), 12, 0, 0));
  return { year: date.getUTCFullYear(), month: date.getUTCMonth() + 1, day: date.getUTCDate() };
}

function getDubaiWeekdayIndex(parts = {}) {
  const date = new Date(Date.UTC(Number(parts.year || 1970), Number(parts.month || 1) - 1, Number(parts.day || 1), 12, 0, 0));
  return date.getUTCDay();
}

function getWeekdayIndexFromText(value = "") {
  const text = compactText(value);
  const days = [
    { index: 0, keys: ["sunday", "sun", "الأحد", "الاحد", "حد"] },
    { index: 1, keys: ["monday", "mon", "الاثنين", "الإثنين", "اثنين"] },
    { index: 2, keys: ["tuesday", "tue", "الثلاثاء", "ثلاثاء"] },
    { index: 3, keys: ["wednesday", "wed", "الأربعاء", "الاربعاء", "اربعاء"] },
    { index: 4, keys: ["thursday", "thu", "الخميس", "خميس"] },
    { index: 5, keys: ["friday", "fri", "الجمعة", "جمعه"] },
    { index: 6, keys: ["saturday", "sat", "السبت", "سبت"] }
  ];

  for (const day of days) {
    if (day.keys.some((key) => text.includes(compactText(key)))) {
      return day.index;
    }
  }

  return null;
}

function extractRelativeDayText(value = "") {
  const text = compactText(value);
  if (!text) return "";

  if (text.includes("day after") || text.includes("after tomorrow") || text.includes("بعد بكرا") || text.includes("بعد غد")) return "day_after_tomorrow";
  if (text.includes("tomorrow") || text.includes("بكرا") || text.includes("غدا") || text.includes("غداً")) return "tomorrow";
  if (text.includes("today") || text.includes("اليوم")) return "today";

  const weekdayIndex = getWeekdayIndexFromText(text);
  return weekdayIndex === null ? "" : `weekday:${weekdayIndex}`;
}

function parseAppointmentTimeParts(value = "") {
  const text = (value || "").toString().trim();
  if (!text) return null;

  const match = text.match(/(\d{1,2})(?::(\d{2}))?\s*(am|pm|a\.m\.|p\.m\.|ص|م|صباح|صباحاً|مساء|مساءً)?/i);
  if (!match) return null;

  let hour = Number(match[1]);
  const minute = Number(match[2] || 0);
  const marker = (match[3] || "").toString().toLowerCase();

  if (minute < 0 || minute > 59 || hour < 0 || hour > 23) return null;

  const isPm = marker.includes("p") || marker.includes("م") || marker.includes("مساء");
  const isAm = marker.includes("a") || marker.includes("ص") || marker.includes("صباح");

  if (isPm && hour < 12) hour += 12;
  if (isAm && hour === 12) hour = 0;

  // Business hours are afternoon-heavy; if the customer/team wrote just "3" keep it as 3 PM, not 3 AM.
  if (!isPm && !isAm && hour >= 1 && hour <= 7) {
    hour += 12;
  }

  return { hour, minute };
}

function resolveAppointmentDubaiDateParts(dayText = "", baseParts = getDubaiDatePartsFromDate(new Date())) {
  const relative = extractRelativeDayText(dayText);

  if (relative === "today") return addDaysToDubaiParts(baseParts, 0);
  if (relative === "tomorrow") return addDaysToDubaiParts(baseParts, 1);
  if (relative === "day_after_tomorrow") return addDaysToDubaiParts(baseParts, 2);

  if (relative.startsWith("weekday:")) {
    const target = Number(relative.split(":")[1]);
    const current = getDubaiWeekdayIndex(baseParts);
    let diff = target - current;
    if (diff < 0) diff += 7;
    return addDaysToDubaiParts(baseParts, diff);
  }

  return null;
}

function buildDubaiAppointmentDate(parts = {}, time = {}) {
  if (!parts || !time) return null;

  const utcMs = Date.UTC(
    Number(parts.year),
    Number(parts.month) - 1,
    Number(parts.day),
    Number(time.hour) - 4,
    Number(time.minute || 0),
    0
  );

  const date = new Date(utcMs);
  return Number.isNaN(date.getTime()) ? null : date;
}

function parseAppointmentDateTimeFromBooking(booking = {}) {
  const details = getBookingRequestDetails(booking);
  const baseParts = getDubaiDatePartsFromSheetValue(booking.date || booking.lastUpdated || "");
  const combinedText = [booking.notes || "", booking.message || "", details.preferredDay || "", details.preferredTime || ""].filter(Boolean).join("\n");

  const explicitDate = combinedText.match(/(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})/);
  const timeParts = parseAppointmentTimeParts(details.preferredTime || combinedText);
  if (!timeParts) return null;

  let dateParts = null;
  if (explicitDate) {
    dateParts = { month: Number(explicitDate[1]), day: Number(explicitDate[2]), year: Number(explicitDate[3]) };
  } else {
    const timeRelative = extractRelativeDayText(details.preferredTime || "");
    dateParts = resolveAppointmentDubaiDateParts(timeRelative || details.preferredDay || combinedText, baseParts);
  }

  if (!dateParts) return null;

  return buildDubaiAppointmentDate(dateParts, timeParts);
}

function getAppointmentReminderKey(phone = "", phoneNumberId = "", appointmentAt = null) {
  const cleanPhone = normalizePhoneDigits(phone);
  const cleanPhoneNumberId = normalizePhoneNumberId(phoneNumberId || DUBAI_PHONE_NUMBER_ID);
  const appointmentKey = appointmentAt instanceof Date && !Number.isNaN(appointmentAt.getTime())
    ? appointmentAt.toISOString()
    : "";
  return `${cleanPhone}|${cleanPhoneNumberId}|${appointmentKey}`;
}

function hasAppointmentReminderBeenSent(messages = [], phone = "", phoneNumberId = "", appointmentAt = null) {
  const key = getAppointmentReminderKey(phone, phoneNumberId, appointmentAt);
  if (!key.includes("|")) return false;

  return (messages || []).some((message) => {
    if (!isAppointmentReminderRow(message)) return false;
    const messagePhone = normalizePhoneDigits(message.phone || "");
    const messagePhoneNumberId = normalizePhoneNumberId(message.phoneNumberId || "");
    const body = (message.body || "").toString();

    return key.startsWith(`${messagePhone}|${messagePhoneNumberId}|`) &&
      body.includes(appointmentAt?.toISOString?.() || "");
  });
}

function getDueAppointmentReminders(bookings = [], messages = []) {
  if (!APPOINTMENT_REMINDER_ENABLED) return [];

  const now = new Date();
  const leadMs = APPOINTMENT_REMINDER_LEAD_MINUTES * 60 * 1000;
  const dueWindowMs = APPOINTMENT_REMINDER_DUE_WINDOW_MINUTES * 60 * 1000;

  return (bookings || []).map((booking) => {
    const phone = normalizePhoneDigits(booking.phone || "");
    const phoneNumberId = normalizePhoneNumberId(booking.phoneNumberId || DUBAI_PHONE_NUMBER_ID);
    const appointmentAt = parseAppointmentDateTimeFromBooking(booking);
    const reminderAt = appointmentAt ? new Date(appointmentAt.getTime() - leadMs) : null;

    return {
      booking,
      phone,
      customerName: booking.customerName || "",
      branch: booking.branch || getLineConfig(phoneNumberId).branch,
      phoneNumberId,
      appointmentAt,
      reminderAt,
      template: getAppointmentReminderTemplateName(phoneNumberId)
    };
  }).filter((record) => {
    const status = compactText(record.booking.status || "");
    if (!record.phone || !record.appointmentAt || !record.reminderAt) return false;
    if (!isConfirmedAppointmentStatus(status) && !status.includes("confirmed")) return false;
    if (isCustomerOptedOutForFollowUps(messages, record.phone, record.phoneNumberId)) return false;
    if (hasAppointmentReminderBeenSent(messages, record.phone, record.phoneNumberId, record.appointmentAt)) return false;

    const nowMs = now.getTime();
    const reminderMs = record.reminderAt.getTime();
    const appointmentMs = record.appointmentAt.getTime();

    return nowMs >= reminderMs && nowMs <= Math.min(appointmentMs, reminderMs + dueWindowMs);
  });
}

async function activateAppointmentReminderAfterConfirmation({ booking = {}, phoneNumberId = DUBAI_PHONE_NUMBER_ID, notes = "", updatedBy = "Booking Confirmation" } = {}) {
  const customerPhone = normalizePhoneDigits(booking.phone || "");
  const finalPhoneNumberId = normalizePhoneNumberId(phoneNumberId || booking.phoneNumberId || DUBAI_PHONE_NUMBER_ID);
  if (!customerPhone) return { ok: false, skipped: true, reason: "missing_customer_phone" };

  const bookingWithNotes = { ...booking, notes: notes || booking.notes || "" };
  const appointmentAt = parseAppointmentDateTimeFromBooking(bookingWithNotes);
  const lineConfig = getLineConfig(finalPhoneNumberId);

  await saveConversationStateToGoogleSheetFromServer({
    phone: customerPhone,
    phoneNumberId: finalPhoneNumberId,
    branch: booking.branch || lineConfig.branch,
    status: "Confirmed Appointment",
    assignee: getBranchTeamAssignee(booking.branch || lineConfig.branch),
    tags: ["Booking", "Confirmed", "Appointment Reminder Auto Scheduled", `${APPOINTMENT_REMINDER_LEAD_MINUTES} Minutes Before`],
    updatedBy
  });

  const logBody = [
    "Appointment reminder auto scheduled ✅",
    `Branch: ${booking.branch || lineConfig.branch}`,
    `Template: ${getAppointmentReminderTemplateName(finalPhoneNumberId)}`,
    appointmentAt ? `Appointment at: ${appointmentAt.toISOString()}` : "Appointment time could not be parsed yet",
    `Reminder lead: ${APPOINTMENT_REMINDER_LEAD_MINUTES} minutes before`
  ].filter(Boolean).join("\n");

  addInboxMessage(customerPhone, "bot", logBody, "Appointment Reminder Scheduled", finalPhoneNumberId, {
    customerName: booking.customerName || "",
    messageType: "Appointment Reminder Auto Scheduled"
  });

  return { ok: Boolean(appointmentAt), appointmentAt, template: getAppointmentReminderTemplateName(finalPhoneNumberId) };
}

function normalizeIntentTags(tags) {
  const seen = new Set();
  return (Array.isArray(tags) ? tags : []).map((tag) => (tag || "").toString().trim()).filter((tag) => {
    if (!tag || seen.has(tag)) return false;
    seen.add(tag);
    return true;
  });
}

function getAutoIntentWorkflow(text) {
  const value = compactText(text);

  if (!value) return null;

  const hasAny = (items) => items.some((item) => value.includes(item));

  if (isBookingIntentText(value)) {
    return {
      status: "Booking Request",
      tags: ["Booking", "Need Details"],
      assignee: "Consultation Team",
      notifyStaff: false
    };
  }

  if (isConsultationIntentText(value)) {
    return {
      status: "Consultation Request",
      tags: ["Consultation", "Need Details"],
      assignee: "Consultation Team",
      notifyStaff: true
    };
  }

  if (isTalkToTeamText(value)) {
    return {
      status: "Talk to Team",
      tags: ["Human Support", "Need Details"],
      assignee: "Consultation Team",
      notifyStaff: false
    };
  }

  if (isCallIntentText(value)) {
    return {
      status: "Call Requested",
      tags: ["Call Requested", "Need Details"],
      assignee: "Consultation Team",
      notifyStaff: false
    };
  }

  if (isPriceIntentText(value)) {
    return {
      status: "Price Question",
      tags: ["Price", "Need Details"],
      assignee: "Consultation Team",
      notifyStaff: false
    };
  }

  if (isLocationIntentText(value)) {
    return {
      status: "Location Requested",
      tags: ["Location"],
      assignee: "Unassigned",
      notifyStaff: false
    };
  }

  if (isNaturalLookIntentText(value)) {
    return {
      status: "Service Interest",
      tags: ["Service Interest", "Natural Look"],
      assignee: "Unassigned",
      notifyStaff: false
    };
  }

  if (isServicesIntentText(value)) {
    return {
      status: "Service Interest",
      tags: ["Service Interest"],
      assignee: "Unassigned",
      notifyStaff: false
    };
  }

  if (isAutoVideoRequestText(value)) {
    return {
      status: "Media Requested",
      tags: ["Media Requested", "Service Interest"],
      assignee: "Unassigned",
      notifyStaff: false
    };
  }

  return null;
}

async function saveConversationStateToGoogleSheetFromServer({ phone, phoneNumberId, branch, status, assignee, tags, updatedBy = "Auto Intent Tags" }) {
  const sheetUrl = process.env.SHEET_WEBHOOK_URL;

  if (!sheetUrl) {
    console.log("SHEET_WEBHOOK_URL is missing. Auto intent state save skipped.");
    return;
  }

  const cleanPhone = (phone || "").toString().trim();
  const cleanPhoneNumberId = normalizePhoneNumberId(phoneNumberId || "");

  if (!cleanPhone || !cleanPhoneNumberId) {
    console.log("Auto intent state save skipped: missing phone or phoneNumberId.");
    return;
  }

  const payload = {
    action: "saveConversationState",
    phone: cleanPhone,
    phoneNumberId: cleanPhoneNumberId,
    branch: (branch || getLineConfig(cleanPhoneNumberId).branch || "").toString().trim(),
    conversation_status: (status || "Open").toString().trim(),
    assigned_to: getBranchTeamAssignee(branch || getLineConfig(cleanPhoneNumberId).branch),
    tags: normalizeIntentTags(tags || []),
    last_updated_by: updatedBy
  };

  try {
    const response = await fetch(sheetUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });

    const responseText = await response.text();

    if (!response.ok) {
      console.log("Auto intent state save HTTP failed:");
      console.log(response.status, responseText);
      return;
    }

    console.log("Auto intent state saved:");
    console.log(responseText);
    clearMessagesApiSheetCache("conversation state saved");
  } catch (error) {
    console.log("Auto intent state save failed:");
    console.log(error);
  }
}

async function saveBookingRequestToGoogleSheetFromServer({ phone, phoneNumberId, customerName = "", branch = "", message = "", requestType = "Booking Request", bookingStatus = "Pending" }) {
  const sheetUrl = process.env.SHEET_WEBHOOK_URL;

  if (!sheetUrl) {
    console.log("SHEET_WEBHOOK_URL is missing. Booking request save skipped.");
    return;
  }

  const cleanPhone = (phone || "").toString().trim();
  const cleanPhoneNumberId = normalizePhoneNumberId(phoneNumberId || "");

  if (!cleanPhone || !cleanPhoneNumberId) {
    console.log("Booking request save skipped: missing phone or phoneNumberId.");
    return;
  }

  const now = getDubaiTimestamp();
  const payload = {
    action: "saveBookingRequest",
    date: now,
    phone: cleanPhone,
    phoneNumberId: cleanPhoneNumberId,
    customerName: (customerName || "").toString().trim(),
    branch: (branch || getLineConfig(cleanPhoneNumberId).branch || "").toString().trim(),
    requestType: requestType || "Booking Request",
    message: (message || "").toString().trim() || "Customer selected Book / Booking Request",
    bookingStatus: bookingStatus || "Pending",
    notes: "",
    lastUpdated: now
  };

  try {
    const response = await fetch(sheetUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });

    const responseText = await response.text();

    if (!response.ok) {
      console.log("Booking request save HTTP failed:");
      console.log(response.status, responseText);
      return;
    }

    let result;
    try {
      result = JSON.parse(responseText);
    } catch (error) {
      result = { ok: false, raw: responseText };
    }

    if (!result.ok) {
      console.log("Booking request save returned failure:");
      console.log(responseText);
      return;
    }

    console.log("Booking request saved:");
    console.log(responseText);
    clearMessagesApiSheetCache("booking request saved");
  } catch (error) {
    console.log("Booking request save failed:");
    console.log(error);
  }
}


async function loadBookingRequestsFromGoogleSheetFromServer() {
  const sheetUrl = process.env.SHEET_WEBHOOK_URL;

  if (!sheetUrl) {
    console.log("SHEET_WEBHOOK_URL is missing. Booking requests load skipped.");
    return { ok: false, bookingRequests: [], error: "SHEET_WEBHOOK_URL is missing" };
  }

  try {
    const response = await fetch(sheetUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action: "loadBookingRequests" })
    });

    const responseText = await response.text();
    let result;

    try {
      result = JSON.parse(responseText);
    } catch (error) {
      result = { ok: false, error: responseText || "Invalid Apps Script response" };
    }

    if (!response.ok || !result.ok) {
      console.log("Booking requests load failed:");
      console.log(response.status, responseText);
      return {
        ok: false,
        bookingRequests: [],
        error: result.error || "Booking requests load failed"
      };
    }

    return {
      ok: true,
      bookingRequests: Array.isArray(result.bookingRequests) ? result.bookingRequests : []
    };
  } catch (error) {
    console.log("Booking requests load error:");
    console.log(error);
    return { ok: false, bookingRequests: [], error: "Booking requests load error" };
  }
}

async function updateBookingRequestStatusInGoogleSheetFromServer({ rowNumber, phone, phoneNumberId, status, notes = "" }) {
  const sheetUrl = process.env.SHEET_WEBHOOK_URL;

  if (!sheetUrl) {
    return { ok: false, error: "SHEET_WEBHOOK_URL is missing" };
  }

  const payload = {
    action: "updateBookingRequestStatus",
    rowNumber,
    phone: (phone || "").toString().trim(),
    phoneNumberId: normalizePhoneNumberId(phoneNumberId || ""),
    status: (status || "").toString().trim(),
    notes: (notes || "").toString().trim()
  };

  if (!payload.status) {
    return { ok: false, error: "Missing status" };
  }

  try {
    const response = await fetch(sheetUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });

    const responseText = await response.text();
    let result;

    try {
      result = JSON.parse(responseText);
    } catch (error) {
      result = { ok: false, error: responseText || "Invalid Apps Script response" };
    }

    if (!response.ok || !result.ok) {
      console.log("Booking status update failed:");
      console.log(response.status, responseText);
      return result;
    }

    console.log("Booking status updated:");
    console.log(responseText);
    clearMessagesApiSheetCache("booking request updated");
    return result;
  } catch (error) {
    console.log("Booking status update error:");
    console.log(error);
    return { ok: false, error: "Booking status update error" };
  }
}

function buildBookingCustomerUpdateBody(status, notes = "", language = "en") {
  const cleanStatus = (status || "").toString().trim();
  const statusValue = cleanStatus.toLowerCase();
  const cleanNotes = (notes || "").toString().trim();
  const isArabic = language === "ar";

  if (!cleanStatus) {
    return { ok: false, error: isArabic ? "اختر إجراء تحديث الموعد قبل إرساله للعميل." : "Please choose an update action before sending it to the customer." };
  }

  if (statusValue.includes("suggest")) {
    if (!cleanNotes) {
      return {
        ok: false,
        error: isArabic ? "أضف الوقت المقترح في ملاحظة الفريق أولاً." : "Please add the suggested appointment time in the team note first."
      };
    }

    return {
      ok: true,
      body: isArabic
        ? [
            BUSINESS_NAME_SPACED + " ✨",
            "",
            "شكراً لك.",
            "راجع فريقنا طلب الموعد، وهذا الوقت المقترح لك:",
            "",
            cleanNotes,
            "",
            "إذا كان الوقت مناسباً، يرجى الرد على هذه الرسالة للتأكيد."
          ].join("\n")
        : [
            BUSINESS_NAME_SPACED + " ✨",
            "",
            "Thank you.",
            "Our team reviewed your appointment request, and this is the suggested time:",
            "",
            cleanNotes,
            "",
            "If this time works for you, please reply to confirm."
          ].join("\n")
    };
  }

  if (statusValue.includes("approved") || statusValue.includes("confirmed")) {
    return {
      ok: true,
      body: isArabic
        ? [
            BUSINESS_NAME_SPACED + " ✨",
            "",
            "تم تأكيد موعدك من طرف فريقنا ✅",
            cleanNotes ? "تفاصيل الموعد:" : "",
            cleanNotes ? cleanNotes : "",
            "",
            "إذا احتجت أي تعديل أو مساعدة، يمكنك الرد على هذه الرسالة في أي وقت."
          ].filter((line) => line !== "").join("\n")
        : [
            BUSINESS_NAME_SPACED + " ✨",
            "",
            "Your appointment has been confirmed by our team ✅",
            cleanNotes ? "Appointment details:" : "",
            cleanNotes ? cleanNotes : "",
            "",
            "If you need any change or support, you can reply to this message anytime."
          ].filter((line) => line !== "").join("\n")
    };
  }

  if (statusValue.includes("follow")) {
    return {
      ok: true,
      body: isArabic
        ? [
            BUSINESS_NAME_SPACED + " ✨",
            "",
            "طلبك قيد المتابعة من فريقنا.",
            "سنراجع التفاصيل ونعود إليك قريباً بالتحديث المناسب."
          ].join("\n")
        : [
            BUSINESS_NAME_SPACED + " ✨",
            "",
            "Your request is being followed up by our team.",
            "We will review the details and get back to you shortly."
          ].join("\n")
    };
  }

  if (statusValue.includes("cancel")) {
    return {
      ok: true,
      body: isArabic
        ? [
            BUSINESS_NAME_SPACED + " ✨",
            "",
            "تم تحديث طلب الموعد الحالي.",
            "إذا رغبت بالمساعدة أو اختيار وقت آخر، يمكنك الرد هنا في أي وقت."
          ].join("\n")
        : [
            BUSINESS_NAME_SPACED + " ✨",
            "",
            "Your current appointment request has been updated.",
            "If you would like help or another time option, you can reply here anytime."
          ].join("\n")
    };
  }

  return {
    ok: false,
    error: isArabic
      ? "اختر Confirm booking أو Suggest another time أو Mark for follow-up أو Cancel request قبل إرسال التحديث."
      : "Choose Confirm booking, Suggest another time, Mark for follow-up, or Cancel request before sending an update."
  };
}

