app.get("/api/reminders/send-due", protectInbox, async (req, res) => {
  try {
    const confirm = (req.query.confirm || "").toString().trim();

    if (confirm !== "SEND") {
      return res.status(400).json({
        ok: false,
        error: "Safety check: add ?confirm=SEND to send due reminders.",
        preview_url: "/api/reminders/preview"
      });
    }

    const sheetData = await loadMessagesFromGoogleSheet();
    const messages = sheetData.messages || [];
    const due = getDueFollowUpReminders(messages);
    const sent = [];
    const failed = [];
    const skippedOptOut = [];

    for (const record of due) {
      if (isCustomerOptedOutForFollowUps(messages, record.phone, record.phoneNumberId)) {
        skippedOptOut.push({
          phone: record.phone,
          branch: record.branch,
          phoneNumberId: record.phoneNumberId,
          reason: "Customer sent STOP"
        });
        continue;
      }

      const templateName = getFollowUpTemplateName(record.phoneNumberId);
      const sendResult = await sendWhatsAppTemplate(record.phone, templateName, record.phoneNumberId, FOLLOW_UP_TEMPLATE_LANGUAGE);

      if (sendResult.ok) {
        addInboxMessage(
          record.phone,
          "bot",
          getReminderBodyForLog(record.phoneNumberId),
          "Follow-up Sent",
          record.phoneNumberId,
          {
            customerName: record.customerName || "",
            messageType: "Service Follow-up Reminder"
          }
        );

        sent.push({
          phone: record.phone,
          branch: record.branch,
          phoneNumberId: record.phoneNumberId,
          template: templateName
        });
      } else {
        failed.push({
          phone: record.phone,
          branch: record.branch,
          phoneNumberId: record.phoneNumberId,
          template: templateName,
          result: sendResult.result
        });
      }
    }

    return res.json({
      ok: failed.length === 0,
      mode: "follow_up_send_due_only",
      templateMode: "branch_specific",
      templates: getFollowUpTemplateMap(),
      appointmentReminder: {
        separated: true,
        previewUrl: "/api/appointment-reminders/preview",
        sendDueUrl: "/api/appointment-reminders/send-due?confirm=SEND"
      },
      headerImageConfigured: Boolean(FOLLOW_UP_HEADER_IMAGE_URL),
      delayDays: FOLLOW_UP_DELAY_DAYS,
      dueCount: due.length,
      sentCount: sent.length,
      failedCount: failed.length,
      skippedOptOutCount: skippedOptOut.length,
      sent,
      failed,
      skippedOptOut
    });
  } catch (error) {
    console.error("Sending due reminders failed:");
    console.error(error);

    return res.status(500).json({
      ok: false,
      error: "Sending due reminders failed"
    });
  }
});

function getMessageMergeKey(message = {}) {
  return [
    message.phone || "",
    message.phoneNumberId || "",
    message.time || "",
    message.sender || "",
    (message.body || "").toString().slice(0, 300),
    message.messageType || ""
  ].join("|");
}

function sortMessagesNewestFirst(messages = []) {
  return messages.slice().sort((a, b) => {
    const aTime = new Date(a?.time || 0).getTime() || 0;
    const bTime = new Date(b?.time || 0).getTime() || 0;
    return bTime - aTime;
  });
}

function mergeInboxHistory(sheetMessages = [], memoryMessages = []) {
  const mergedMap = new Map();

  // Keep Google Sheet as the primary persisted source.
  for (const message of sheetMessages || []) {
    const key = getMessageMergeKey(message);
    if (key.trim() && !mergedMap.has(key)) {
      mergedMap.set(key, message);
    }
  }

  // Add current in-memory messages so a partial Sheet response cannot hide live conversations.
  for (const message of memoryMessages || []) {
    const key = getMessageMergeKey(message);
    if (key.trim() && !mergedMap.has(key)) {
      mergedMap.set(key, message);
    }
  }

  return sortMessagesNewestFirst(Array.from(mergedMap.values()));
}

// V31.5.8.60.3.9.50 - History Locked / Messages API Fast Path:
// The Network test showed /api/messages requests taking 20–36s and overlapping.
// This patch keeps history logic intact, but prevents the Team Inbox UI from waiting
// on slow Google Sheet reads on every poll. Google Sheet remains the persisted source;
// stale cache + in-memory messages are returned quickly while a background refresh runs.
const MESSAGES_API_SHEET_CACHE_TTL_MS = Number(process.env.MESSAGES_API_SHEET_CACHE_TTL_MS || 15000);
const MESSAGES_API_SHEET_TIMEOUT_MS = Number(process.env.MESSAGES_API_SHEET_TIMEOUT_MS || 3500);
let messagesApiSheetCache = null;
let messagesApiSheetCacheAt = 0;
let messagesApiSheetCachePromise = null;

function getEmptyMessagesApiSheetData() {
  return { messages: [], conversationStates: [], bookingRequests: [] };
}

function clearMessagesApiSheetCache(reason = "") {
  // Do not wipe the last good cache. Mark it stale so /api/messages can still respond fast.
  messagesApiSheetCacheAt = 0;
  if (reason) {
    console.log(`[Messages API Cache] marked stale: ${reason}`);
  }
}

function timeoutAfter(ms, label = "timeout") {
  return new Promise((_, reject) => {
    setTimeout(() => reject(new Error(label)), Math.max(1000, Number(ms) || 3500));
  });
}

function startMessagesApiSheetRefresh(reason = "") {
  if (messagesApiSheetCachePromise) {
    return messagesApiSheetCachePromise;
  }

  if (reason) {
    console.log(`[Messages API Cache] refresh started: ${reason}`);
  }

  messagesApiSheetCachePromise = loadMessagesFromGoogleSheet()
    .then((sheetData) => {
      messagesApiSheetCache = sheetData || getEmptyMessagesApiSheetData();
      messagesApiSheetCacheAt = Date.now();
      return messagesApiSheetCache;
    })
    .catch((error) => {
      console.log("Messages API background Sheet refresh failed:");
      console.log(error);
      return messagesApiSheetCache || getEmptyMessagesApiSheetData();
    })
    .finally(() => {
      messagesApiSheetCachePromise = null;
    });

  return messagesApiSheetCachePromise;
}

async function loadMessagesFromGoogleSheetForMessagesApi() {
  const now = Date.now();
  const hasCache = Boolean(messagesApiSheetCache);
  const cacheAge = hasCache ? (now - messagesApiSheetCacheAt) : Infinity;

  if (hasCache && cacheAge < MESSAGES_API_SHEET_CACHE_TTL_MS) {
    return messagesApiSheetCache;
  }

  if (hasCache) {
    // Return stale cache immediately and refresh in the background.
    startMessagesApiSheetRefresh("stale-cache").catch(() => {});
    return messagesApiSheetCache;
  }

  const refreshPromise = startMessagesApiSheetRefresh("cold-cache");

  try {
    return await Promise.race([
      refreshPromise,
      timeoutAfter(MESSAGES_API_SHEET_TIMEOUT_MS, "Messages API Sheet load timeout")
    ]);
  } catch (error) {
    console.log("Messages API returned fast fallback while Sheet is still loading:");
    console.log(error.message || error);
    return messagesApiSheetCache || getEmptyMessagesApiSheetData();
  }
}


function normalizeInboxArchiveStatusValue(value = "") {
  return (value || "").toString().trim().toLowerCase();
}

function isArchivedInboxConversationStatus(status = "") {
  const value = normalizeInboxArchiveStatusValue(status);
  return value === "archived" || value === "hidden" || value === "hide" || value === "deleted";
}

function buildInboxArchiveConversationKey(phone = "", phoneNumberId = "", branch = "") {
  return `${(phone || "unknown").toString().trim()}::${(phoneNumberId || branch || "line").toString().trim()}`;
}

function getArchivedConversationKeySet(conversationStates = []) {
  const archivedKeys = new Set();

  (conversationStates || []).forEach((state) => {
    if (!isArchivedInboxConversationStatus(state?.conversation_status || state?.status || "")) {
      return;
    }

    const phone = (state?.phone || "").toString().trim();
    const phoneNumberId = normalizePhoneNumberId(state?.phoneNumberId || "");
    const branch = (state?.branch || "").toString().trim();

    if (!phone) return;
    archivedKeys.add(buildInboxArchiveConversationKey(phone, phoneNumberId, branch));
  });

  return archivedKeys;
}

function filterArchivedInboxPayload(messages = [], conversationStates = [], bookingRequests = [], includeArchived = false, archiveOnly = false) {
  const archivedKeys = getArchivedConversationKeySet(conversationStates);

  if (!archivedKeys.size) {
    return {
      messages: archiveOnly ? [] : messages,
      conversationStates: archiveOnly ? [] : conversationStates,
      bookingRequests: archiveOnly ? [] : bookingRequests,
      archivedConversationCount: 0,
      hiddenMessagesCount: 0,
      hiddenBookingRequestsCount: 0
    };
  }

  if (archiveOnly) {
    const archivedMessages = (messages || []).filter((message) => {
      const key = buildInboxArchiveConversationKey(message?.phone || "", normalizePhoneNumberId(message?.phoneNumberId || ""), message?.branch || "");
      return archivedKeys.has(key);
    });

    const archivedConversationStates = (conversationStates || []).filter((state) => {
      const key = buildInboxArchiveConversationKey(state?.phone || "", normalizePhoneNumberId(state?.phoneNumberId || ""), state?.branch || "");
      return archivedKeys.has(key);
    });

    const archivedBookingRequests = (bookingRequests || []).filter((booking) => {
      const key = buildInboxArchiveConversationKey(booking?.phone || "", normalizePhoneNumberId(booking?.phoneNumberId || ""), booking?.branch || "");
      return archivedKeys.has(key);
    });

    return {
      messages: archivedMessages,
      conversationStates: archivedConversationStates,
      bookingRequests: archivedBookingRequests,
      archivedConversationCount: archivedKeys.size,
      hiddenMessagesCount: Math.max(0, (messages || []).length - archivedMessages.length),
      hiddenBookingRequestsCount: Math.max(0, (bookingRequests || []).length - archivedBookingRequests.length)
    };
  }

  if (includeArchived) {
    return {
      messages,
      conversationStates,
      bookingRequests,
      archivedConversationCount: archivedKeys.size,
      hiddenMessagesCount: 0,
      hiddenBookingRequestsCount: 0
    };
  }

  const visibleMessages = (messages || []).filter((message) => {
    const key = buildInboxArchiveConversationKey(message?.phone || "", normalizePhoneNumberId(message?.phoneNumberId || ""), message?.branch || "");
    return !archivedKeys.has(key);
  });

  const visibleConversationStates = (conversationStates || []).filter((state) => {
    const key = buildInboxArchiveConversationKey(state?.phone || "", normalizePhoneNumberId(state?.phoneNumberId || ""), state?.branch || "");
    return !archivedKeys.has(key);
  });

  const visibleBookingRequests = (bookingRequests || []).filter((booking) => {
    const key = buildInboxArchiveConversationKey(booking?.phone || "", normalizePhoneNumberId(booking?.phoneNumberId || ""), booking?.branch || "");
    return !archivedKeys.has(key);
  });

  return {
    messages: visibleMessages,
    conversationStates: visibleConversationStates,
    bookingRequests: visibleBookingRequests,
    archivedConversationCount: archivedKeys.size,
    hiddenMessagesCount: Math.max(0, (messages || []).length - visibleMessages.length),
    hiddenBookingRequestsCount: Math.max(0, (bookingRequests || []).length - visibleBookingRequests.length)
  };
}

  app.get("/api/messages", protectInbox, async (req, res) => {
  res.setHeader("Cache-Control", "no-store, no-cache, must-revalidate, proxy-revalidate");
  res.setHeader("Pragma", "no-cache");
  res.setHeader("Expires", "0");
  const sheetData = await loadMessagesFromGoogleSheetForMessagesApi();
  const sheetMessages = sheetData.messages || [];
  const memoryMessages = inboxMessages || [];
  const conversationStates = sheetData.conversationStates || [];
  const bookingRequests = sheetData.bookingRequests || [];
  const mergedMessages = mergeInboxHistory(sheetMessages, memoryMessages);
  const branchFilteredPayload = filterInboxPayloadByBranchAccess(
    mergedMessages,
    conversationStates,
    bookingRequests,
    req.inboxAccess || {}
  );
  const includeArchived = ["1", "true", "yes", "on"].includes(
    (req.query?.includeArchived || "").toString().trim().toLowerCase()
  );
  const archiveOnly = ["1", "true", "yes", "on"].includes(
    (req.query?.archiveOnly || "").toString().trim().toLowerCase()
  );
  const archiveFilteredPayload = filterArchivedInboxPayload(
    branchFilteredPayload.messages,
    branchFilteredPayload.conversationStates,
    branchFilteredPayload.bookingRequests,
    includeArchived,
    archiveOnly
  );
  const source = sheetMessages.length > 0 && memoryMessages.length > 0
    ? "google_sheet_plus_memory"
    : (sheetMessages.length > 0 ? "google_sheet" : "memory");

  return res.json({
    ok: true,
    source,
    messages: archiveFilteredPayload.messages,
    conversationStates: archiveFilteredPayload.conversationStates,
    bookingRequests: archiveFilteredPayload.bookingRequests,
    debug: {
      botVersion: BOT_VERSION,
      sheetMessagesCount: sheetMessages.length,
      memoryMessagesCount: memoryMessages.length,
      returnedMessagesCount: archiveFilteredPayload.messages.length,
      unfilteredMessagesCount: mergedMessages.length,
      conversationStatesCount: archiveFilteredPayload.conversationStates.length,
      unfilteredConversationStatesCount: conversationStates.length,
      bookingRequestsCount: archiveFilteredPayload.bookingRequests.length,
      unfilteredBookingRequestsCount: bookingRequests.length,
      includeArchived,
      archiveOnly,
      archivedConversationCount: archiveFilteredPayload.archivedConversationCount,
      hiddenMessagesCount: archiveFilteredPayload.hiddenMessagesCount,
      hiddenBookingRequestsCount: archiveFilteredPayload.hiddenBookingRequestsCount,
      inboxUser: req.inboxUser || "",
      branchScope: branchFilteredPayload.branchScope || "All",
      branchFilteredMessagesCount: branchFilteredPayload.branchFilteredMessagesCount,
      branchFilteredConversationStatesCount: branchFilteredPayload.branchFilteredConversationStatesCount,
      branchFilteredBookingRequestsCount: branchFilteredPayload.branchFilteredBookingRequestsCount
    }
  });
});

