function saveReadMap() {
  localStorage.setItem("iconic_read_map", JSON.stringify(readMap));
}

function saveStatusOverrideMap() {
  localStorage.setItem("iconic_status_override_map", JSON.stringify(statusOverrideMap));
}

function setStatusOverride(key, status) {
  if (!key || !status) return;
  statusOverrideMap[key] = status;
  saveStatusOverrideMap();
}

function getStatusOverride(key) {
  return key && statusOverrideMap[key] ? statusOverrideMap[key] : "";
}

function saveAssigneeMap() {
  localStorage.setItem("iconic_assignee_map", JSON.stringify(assigneeMap));
}

function getDefaultBranchAssignee(branch) {
  const value = (branch || "").toString().toLowerCase();
  return value.includes("abu") ? "Abu Dhabi Team" : "Dubai Team";
}

function normalizeAssigneeValue(assignee, branch) {
  const value = (assignee || "").toString().trim();
  const allowed = ["Dubai Team", "Abu Dhabi Team"];

  // V31.5.8.32 keeps assignment branch-team only.
  // Old values such as Unassigned / Consultation Team / Follow-up Team safely fall back to the branch team.
  return allowed.includes(value) ? value : getDefaultBranchAssignee(branch);
}

function setAssignee(key, assignee) {
  if (!key) return;
  const value = normalizeAssigneeValue(assignee);
  assigneeMap[key] = value;
  saveAssigneeMap();
}

function getAssignee(key, branch) {
  return key && assigneeMap[key] ? normalizeAssigneeValue(assigneeMap[key], branch) : getDefaultBranchAssignee(branch);
}

function assigneeClass(assignee) {
  const value = (assignee || "").toString().toLowerCase();
  if (value.includes("abu")) return "assignee-abu";
  if (value.includes("dubai")) return "assignee-dubai";
  if (value.includes("consult")) return "assignee-consultation";
  if (value.includes("follow")) return "assignee-followup";
  return "assignee-unassigned";
}

function assigneeBadge(assignee) {
  const label = assignee || "Unassigned";
  return '<span class="assignee-chip ' + assigneeClass(label) + '">Assigned: ' + escapeHtml(label) + '</span>';
}

function saveTagMap() {
  localStorage.setItem("iconic_tag_map", JSON.stringify(tagMap));
}

function normalizeTags(tags) {
  if (!Array.isArray(tags)) return [];
  const seen = new Set();
  return tags.map(function(tag) {
    return (tag || "").toString().trim();
  }).filter(function(tag) {
    if (!tag || seen.has(tag)) return false;
    seen.add(tag);
    return true;
  });
}

function setTags(key, tags) {
  if (!key) return;
  tagMap[key] = normalizeTags(tags);
  saveTagMap();
}

function getTags(key) {
  return key && Array.isArray(tagMap[key]) ? tagMap[key] : [];
}

function parseStateTags(value) {
  if (Array.isArray(value)) return normalizeTags(value);
  return (value || "").toString().split(",").map(function(tag) {
    return tag.trim();
  }).filter(Boolean);
}

function applyConversationStates(states) {
  // V30: Google Sheets Conversation State is loaded first and then mirrored into local maps.
  // This keeps Status / Assigned / Tags stable after refresh and across devices.
  conversationStateMap = {};
  (states || []).forEach(function(state) {
    const phone = (state.phone || "").toString().trim();
    const phoneNumberId = (state.phoneNumberId || "").toString().trim();
    if (!phone || !phoneNumberId) return;

    const key = conversationKey(phone, phoneNumberId, state.branch || "");
    const status = (state.conversation_status || "").toString().trim();
    const assignee = normalizeAssigneeValue(state.assigned_to || "", state.branch || "");
    const tags = parseStateTags(state.tags || "");

    conversationStateMap[key] = {
      phone,
      phoneNumberId,
      branch: state.branch || "",
      status,
      assignee,
      tags,
      last_updated_by: state.last_updated_by || "",
      last_updated_at: state.last_updated_at || ""
    };

    if (status) statusOverrideMap[key] = status;
    assigneeMap[key] = assignee;
    tagMap[key] = tags;
  });

  saveStatusOverrideMap();
  saveAssigneeMap();
  saveTagMap();
}

function getCurrentConversationForState() {
  if (!selectedConversationKey) return null;
  return buildConversations().find(function(item) {
    return item.key === selectedConversationKey;
  }) || null;
}

async function saveConversationStateToGoogleSheet(c) {
  if (!c || !c.phone || !c.phoneNumberId) return;

  try {
    await fetch("/api/conversation-state", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        phone: c.phone,
        phoneNumberId: c.phoneNumberId,
        branch: c.branch || "",
        conversation_status: c.status || "Open",
        assigned_to: c.assignee || "Unassigned",
        tags: normalizeTags(c.tags || []),
        last_updated_by: "Team Inbox"
      })
    });
  } catch (error) {
    console.log("Conversation state save failed", error);
  }
}

function tagClass(tag) {
  const value = (tag || "").toString().toLowerCase().replace(/\s+/g, "-");
  if (value.includes("vip")) return "tag-vip";
  if (value.includes("private")) return "tag-private";
  if (value.includes("follow")) return "tag-follow-up";
  if (value.includes("price")) return "tag-price";
  if (value.includes("booking")) return "tag-booking";
  if (value.includes("human")) return "tag-need-details";
  if (value.includes("call")) return "tag-follow-up";
  if (value.includes("service")) return "tag-general";
  if (value.includes("media")) return "tag-general";
  if (value.includes("natural")) return "tag-general";
  if (value.includes("need")) return "tag-need-details";
  return "tag-general";
}

function tagBadge(tag, className) {
  const base = className || "tag-chip";
  return '<span class="' + base + ' ' + tagClass(tag) + '">' + escapeHtml(tag) + '</span>';
}

function tagBadges(tags, className, limit) {
  const safeTags = normalizeTags(tags);
  const shown = typeof limit === "number" ? safeTags.slice(0, limit) : safeTags;
  if (!shown.length) return '<span class="tag-chip">No tags</span>';
  const extra = safeTags.length - shown.length;
  return shown.map(function(tag) { return tagBadge(tag, className); }).join("") + (extra > 0 ? '<span class="' + (className || "tag-chip") + '">+' + extra + '</span>' : "");
}

function setProfileText(el, value) {
  if (el) el.textContent = value || "—";
}

function profileSenderLabel(sender) {
  if (sender === "customer") return "Customer";
  if (sender === "staff") return "Team";
  if (sender === "bot") return "Bot";
  return "Message";
}

function saveInternalNotesMap() {
  localStorage.setItem("iconic_internal_notes_map", JSON.stringify(internalNotesMap));
}

function getInternalNoteKey(c) {
  return c && c.key ? c.key : selectedConversationKey || "";
}

function hashStringForCode(value) {
  const text = (value || "").toString();
  let hash = 2166136261;
  for (let i = 0; i < text.length; i += 1) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(36).toUpperCase().padStart(6, "0").slice(-6);
}

function buildCustomerCode(c) {
  if (!c) return "IC-000000";
  return "IC-" + hashStringForCode((c.phone || "") + "|" + (c.phoneNumberId || "") + "|" + (c.branch || ""));
}

function buildLeadSource(c) {
  if (!c) return "WhatsApp";
  return "WhatsApp - " + (c.branch || "Branch");
}

function buildPrivacyLabel(tags) {
  const safeTags = normalizeTags(tags || []);
  if (safeTags.includes("Private")) return "Private";
  if (safeTags.includes("VIP")) return "VIP / Discreet";
  return "Discreet";
}

function buildLastAction(c) {
  if (!c || !c.latest) return "—";
  const latest = c.latest || {};
  const image = parseInlineImageMessage(latest.body || "");
  const actor = profileSenderLabel(latest.sender);

  if (image) {
    return actor + " sent image" + (image.caption ? ": " + shortText(image.caption, 34) : "");
  }

  const body = (latest.body || latest.messageType || "").toString().replace(/\s+/g, " ").trim();
  return actor + (body ? ": " + shortText(body, 42) : " activity");
}

function syncInternalNoteBox(c) {
  if (!customerInternalNote || !customerInternalNoteStatus) return;

  if (!c) {
    customerInternalNote.value = "";
    customerInternalNote.disabled = true;
    customerInternalNoteStatus.textContent = "Select a customer to add a note. V31.3 saves notes in this browser only.";
    return;
  }

  const key = getInternalNoteKey(c);
  customerInternalNote.disabled = false;
  customerInternalNote.value = internalNotesMap[key] || "";
  customerInternalNoteStatus.textContent = "Internal note is private to Team Inbox. V31.3 stores it in this browser only.";
}

function buildCustomerProfileSummary(c) {
  if (!c) return "No customer selected yet.";

  const messages = c.messages || [];
  const latest = c.latest || {};
  const customerCount = messages.filter(function(m) { return m.sender === "customer"; }).length;
  const teamCount = messages.filter(function(m) { return m.sender === "staff"; }).length;
  const botCount = messages.filter(function(m) { return m.sender === "bot"; }).length;

  return messages.length + " total messages • " +
    customerCount + " customer • " +
    teamCount + " team • " +
    botCount + " bot • Last sender: " + profileSenderLabel(latest.sender) + ".";
}


function updateCustomerTimeline(c) {
  if (!c) {
    setProfileText(timelineFirstSeen, "—");
    setProfileText(timelineLastMessage, "—");
    setProfileText(timelineTotalMessages, "0");
    setProfileText(timelineCustomerMessages, "0");
    setProfileText(timelineTeamMessages, "0");
    setProfileText(timelineBotMessages, "0");
    setProfileText(timelineLastSender, "—");
    return;
  }

  const messages = Array.isArray(c.messages) ? c.messages : [];
  const chronological = messages.slice().reverse();
  const first = chronological[0] || {};
  const latest = c.latest || messages[0] || {};
  const customerCount = messages.filter(function(m) { return m.sender === "customer"; }).length;
  const teamCount = messages.filter(function(m) { return m.sender === "staff"; }).length;
  const botCount = messages.filter(function(m) { return m.sender === "bot"; }).length;

  setProfileText(timelineFirstSeen, first.time || "—");
  setProfileText(timelineLastMessage, latest.time || "—");
  setProfileText(timelineTotalMessages, String(messages.length || 0));
  setProfileText(timelineCustomerMessages, String(customerCount));
  setProfileText(timelineTeamMessages, String(teamCount));
  setProfileText(timelineBotMessages, String(botCount));
  setProfileText(timelineLastSender, profileSenderLabel(latest.sender));
}

function normalizeBookingLookupValue(value) {
  return (value || "").toString().replace(/\D/g, "");
}

function bookingStatusClass(status) {
  const value = (status || "").toString().toLowerCase();
  if (value.includes("approved")) return "booking-status-approved";
  if (value.includes("suggest")) return "booking-status-suggest";
  if (value.includes("follow")) return "booking-status-follow-up";
  if (value.includes("cancel")) return "booking-status-cancelled";
  return "booking-status-pending";
}

function bookingStatusLabel(status) {
  const value = (status || "").toString().toLowerCase();
  if (value.includes("approved")) return "Confirmed";
  if (value.includes("suggest")) return "Time suggested";
  if (value.includes("follow")) return "Follow-up needed";
  if (value.includes("cancel")) return "Cancelled";
  return "Awaiting confirmation";
}

function getLatestBookingRequestForConversation(c) {
  if (!c || !Array.isArray(allBookingRequests)) return null;

  const phone = normalizeBookingLookupValue(c.phone || "");
  const phoneNumberId = (c.phoneNumberId || "").toString().trim();

  if (!phone) return null;

  const exact = allBookingRequests.find(function(booking) {
    return normalizeBookingLookupValue(booking.phone || "") === phone &&
      (booking.phoneNumberId || "").toString().trim() === phoneNumberId;
  });

  if (exact) return exact;

  return allBookingRequests.find(function(booking) {
    return normalizeBookingLookupValue(booking.phone || "") === phone;
  }) || null;
}

function cleanBookingNoteForTeamInbox(note) {
  const value = (note || "").toString().trim();

  // V31.5.8.16:
  // Hide/clear old API test notes so staff do not see production booking cards
  // polluted by testing text. If staff writes a real note, it remains saved.
  if (value.toLowerCase() === "api status update test") {
    return "";
  }

  return value;
}

function getBookingDraftKey(booking) {
  if (!booking) return "";
  return (booking.rowNumber || "") + "|" + (booking.phone || "") + "|" + (booking.phoneNumberId || "");
}

function hasBookingNoteDraft(key) {
  return Object.prototype.hasOwnProperty.call(bookingNoteDraftMap, key);
}

function setBookingNoteDraft(key, value) {
  if (!key) return;
  bookingNoteDraftMap[key] = (value || "").toString();
}

function getCurrentBookingNoteDraft() {
  if (!bookingStatusNote) return "";
  const key = bookingStatusNote.dataset.draftKey || "";
  if (key && hasBookingNoteDraft(key)) {
    return bookingNoteDraftMap[key];
  }
  return bookingStatusNote.value || "";
}

function updateBookingRequestCard(c) {
  if (!bookingRequestCard) return;

  const booking = getLatestBookingRequestForConversation(c);

  if (!booking) {
    bookingRequestCard.classList.add("is-hidden");
    bookingRequestCard.dataset.rowNumber = "";
    if (bookingRequestResult) bookingRequestResult.textContent = "No active appointment request for this client.";
    return;
  }

  bookingRequestCard.classList.remove("is-hidden");
  bookingRequestCard.dataset.rowNumber = booking.rowNumber || "";
  bookingRequestCard.dataset.phone = booking.phone || "";
  bookingRequestCard.dataset.phoneNumberId = booking.phoneNumberId || "";

  const status = booking.status || "Pending";

  if (bookingRequestStatusPill) {
    bookingRequestStatusPill.className = "booking-status-pill " + bookingStatusClass(status);
    bookingRequestStatusPill.textContent = bookingStatusLabel(status);
  }

  setProfileText(bookingRequestCustomer, booking.customerName || (c && (c.customerName || c.phone)) || "—");
  setProfileText(bookingRequestPhone, booking.phone || "—");
  setProfileText(bookingRequestBranch, booking.branch || (c && c.branch) || "—");
  setProfileText(bookingRequestMessage, booking.message || booking.requestType || "Appointment Request");
  setProfileText(bookingRequestLastUpdated, booking.lastUpdated || booking.date || "—");

  if (bookingStatusNote) {
    const draftKey = getBookingDraftKey(booking);
    const serverNote = cleanBookingNoteForTeamInbox(booking.notes || "");
    const currentDraftKey = bookingStatusNote.dataset.draftKey || "";
    const isSameFocusedDraft = bookingNoteIsEditing && currentDraftKey === draftKey;

    bookingStatusNote.dataset.draftKey = draftKey;

    if (isSameFocusedDraft) {
      setBookingNoteDraft(draftKey, bookingStatusNote.value || "");
    } else if (hasBookingNoteDraft(draftKey)) {
      bookingStatusNote.value = bookingNoteDraftMap[draftKey];
    } else {
      bookingStatusNote.value = serverNote;
      setBookingNoteDraft(draftKey, serverNote);
    }
  }

  if (bookingRequestResult) {
    bookingRequestResult.textContent = "Choose an action to prepare an update."; 
  }
}

function setBookingButtonsDisabled(disabled) {
  Array.from(document.querySelectorAll("[data-booking-status-action]")).forEach(function(btn) {
    btn.disabled = Boolean(disabled);
  });

  if (bookingSendCustomerUpdateBtn) {
    bookingSendCustomerUpdateBtn.disabled = Boolean(disabled);
  }
}

async function updateSelectedBookingStatus(status) {
  const c = getCurrentConversationForState();
  const booking = getLatestBookingRequestForConversation(c);

  if (!booking || !booking.rowNumber) {
    if (bookingRequestResult) bookingRequestResult.textContent = "No appointment request selected."; 
    return;
  }

  const notes = cleanBookingNoteForTeamInbox(getCurrentBookingNoteDraft().trim());

  if (bookingRequestResult) bookingRequestResult.textContent = "Saving appointment update...";
  setBookingButtonsDisabled(true);

  try {
    const response = await fetch("/api/bookings/status", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        rowNumber: booking.rowNumber,
        status,
        notes
      })
    });

    const result = await response.json();

    if (!response.ok || !result.ok) {
      if (bookingRequestResult) bookingRequestResult.textContent = "Failed: " + (result.error || "Appointment update failed");
      return;
    }

    const draftKey = getBookingDraftKey(booking);
    setBookingNoteDraft(draftKey, notes);

    allBookingRequests = allBookingRequests.map(function(item) {
      if (String(item.rowNumber) !== String(booking.rowNumber)) return item;
      return Object.assign({}, item, {
        status: result.status || status,
        notes: result.notes !== undefined ? result.notes : notes,
        lastUpdated: result.lastUpdated || item.lastUpdated || ""
      });
    });

    if (bookingRequestResult) bookingRequestResult.textContent = "Saved: " + bookingStatusLabel(result.status || status);
    updateBookingRequestCard(c);
    loadMessages({ forceRender: true, reason: "action" });
  } catch (error) {
    if (bookingRequestResult) bookingRequestResult.textContent = "Failed: appointment update error."; 
  } finally {
    setBookingButtonsDisabled(false);
  }
}

function bookingStatusNeedsSuggestedTime(status) {
  return (status || "").toString().toLowerCase().includes("suggest");
}

function bookingStatusCanSendCustomerUpdate(status) {
  const value = (status || "").toString().toLowerCase();
  return value.includes("approved") || value.includes("suggest") || value.includes("follow") || value.includes("cancel");
}

async function sendSelectedBookingUpdateToCustomer() {
  const c = getCurrentConversationForState();
  const booking = getLatestBookingRequestForConversation(c);

  if (!booking || !booking.rowNumber) {
    if (bookingRequestResult) bookingRequestResult.textContent = "No appointment request selected."; 
    return;
  }

  const status = (booking.status || "Pending").toString().trim();
  const notes = cleanBookingNoteForTeamInbox(getCurrentBookingNoteDraft().trim());

  if (!bookingStatusCanSendCustomerUpdate(status)) {
    if (bookingRequestResult) bookingRequestResult.textContent = "Choose a customer update action first."; 
    return;
  }

  if (bookingStatusNeedsSuggestedTime(status) && !notes) {
    if (bookingRequestResult) bookingRequestResult.textContent = "Add the suggested time in the team note first."; 
    if (bookingStatusNote) bookingStatusNote.focus();
    return;
  }

  if (bookingRequestResult) bookingRequestResult.textContent = "Sending customer update..."; 
  setBookingButtonsDisabled(true);

  try {
    const response = await fetch("/api/bookings/send-update", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        rowNumber: booking.rowNumber,
        to: booking.phone || (c && c.phone) || "",
        phoneNumberId: booking.phoneNumberId || (c && c.phoneNumberId) || "",
        status: status,
        notes: notes
      })
    });

    const result = await response.json();

    if (!response.ok || !result.ok) {
      if (bookingRequestResult) bookingRequestResult.textContent = "Failed: " + (result.error || "Customer update failed");
      return;
    }

    if (bookingRequestResult) bookingRequestResult.textContent = "Customer update sent successfully."; 
    loadMessages({ forceRender: true, reason: "action" });
  } catch (error) {
    if (bookingRequestResult) bookingRequestResult.textContent = "Failed: customer update send error."; 
  } finally {
    setBookingButtonsDisabled(false);
  }
}

function updateCustomerProfile(c) {
  if (!c) {
    setProfileText(customerProfilePhone, "—");
    setProfileText(customerProfileBranch, "—");
    setProfileText(customerProfileLastActivity, "—");
    setProfileText(customerProfileLastAction, "—");
    setProfileText(customerProfileStatus, "—");
    setProfileText(conversationInfoStatus, "—");
    setProfileText(customerProfileAssigned, "—");
    setProfileText(customerProfileTags, "No tags");
    setProfileText(customerProfileSummary, "Choose a customer from the inbox to view profile details.");
    setProfileText(customerProfileLongSummary, "No customer selected yet.");
    setProfileText(customerProfileHeaderName, "No customer selected");
    setProfileText(customerProfileHeaderPhone, "—");
    setProfileText(customerProfileCode, "—");
    setProfileText(customerProfileName, "No customer selected");
    setProfileText(customerProfilePrivacy, "Discreet");
    setProfileText(customerProfilePrivacyBadge, "Discreet");
    setProfileText(customerProfileLeadSource, "WhatsApp");
    setProfileText(customerProfileLocation, "—");
    setProfileText(customerProfileFirstContact, "—");
    setProfileText(customerProfileLanguage, "English");
    if (customerProfileAvatar) customerProfileAvatar.textContent = "IC";
    syncInternalNoteBox(null);
    updateCustomerTimeline(null);
    updateBookingRequestCard(null);
    return;
  }

  const tags = normalizeTags(c.tags || []);
  const latest = c.latest || {};
  const orderedMessages = (c.messages || []).slice().sort(function(a, b) {
    return (new Date(a.time || 0).getTime() || 0) - (new Date(b.time || 0).getTime() || 0);
  });
  const first = orderedMessages[0] || latest || {};
  const displayName = c.customerName || c.name || c.phone || "Customer";
  const location = c.branch ? (c.branch + ", UAE") : "—";
  const privacyLabel = buildPrivacyLabel(tags);

  setProfileText(customerProfilePhone, c.phone || "—");
  setProfileText(customerProfileBranch, c.branch || "—");
  setProfileText(customerProfileLastActivity, latest.time || "—");
  setProfileText(customerProfileLastAction, buildLastAction(c));
  setProfileText(customerProfileStatus, c.status || "Open");
  setProfileText(conversationInfoStatus, c.status || "Open");
  setProfileText(customerProfileAssigned, c.assignee || "Unassigned");
  setProfileText(customerProfileTags, tags.length ? tags.join(", ") : "No tags");
  setProfileText(customerProfileSummary, "Customer workflow profile for " + (c.phone || "selected customer") + ".");
  setProfileText(customerProfileLongSummary, buildCustomerProfileSummary(c));
  setProfileText(customerProfileHeaderName, displayName);
  setProfileText(customerProfileHeaderPhone, c.phone || "—");
  setProfileText(customerProfileCode, buildCustomerCode(c));
  setProfileText(customerProfileName, displayName);
  setProfileText(customerProfilePrivacy, privacyLabel);
  setProfileText(customerProfilePrivacyBadge, privacyLabel);
  setProfileText(customerProfileLeadSource, buildLeadSource(c));
  setProfileText(customerProfileLocation, location);
  setProfileText(customerProfileFirstContact, first.time || "—");
  setProfileText(customerProfileLanguage, "English");
  if (customerProfileAvatar) customerProfileAvatar.textContent = avatarText(displayName || c.phone || "IC");
  syncInternalNoteBox(c);
  updateCustomerTimeline(c);
  updateBookingRequestCard(c);
}

function syncTagPicker(tags) {
  const safeTags = normalizeTags(tags);
  const selected = new Set(safeTags);
  if (tagPicker) {
    Array.from(tagPicker.querySelectorAll('input[type="checkbox"]')).forEach(function(input) {
      input.checked = selected.has(input.value);
      input.disabled = !selectedConversationKey;
    });
  }
  if (tagDisplay) {
    tagDisplay.innerHTML = tagBadges(safeTags, "tag-chip");
  }
}

function closeChatTagsPopover() {
  if (chatTagsPopover) {
    chatTagsPopover.classList.add("is-hidden");
  }
}

function statusClass(status) {
  const value = (status || "").toString().toLowerCase();
  if (value.includes("wait")) return "status-waiting";
  if (value.includes("closed") || value.includes("archived") || value.includes("hidden")) return "status-closed";
  if (value.includes("team")) return "status-team";
  if (value.includes("follow")) return "status-follow";
  return "status-open";
}

function escapeHtml(value) {
  return (value || "").toString()
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function shortText(value, max) {
  const t = (value || "").toString().replace(/\s+/g, " ").trim();
  return t.length <= max ? t : t.slice(0, max - 1) + "…";
}

const INLINE_IMAGE_PREFIX = "[[ICONIC_INLINE_IMAGE]] ";
const INLINE_AUDIO_PREFIX = "[[ICONIC_INLINE_AUDIO]] ";

function parseInlineImageMessage(body) {
  const value = (body || "").toString().trim();

  if (!value.startsWith(INLINE_IMAGE_PREFIX)) {
    return null;
  }

  try {
    const payload = JSON.parse(value.slice(INLINE_IMAGE_PREFIX.length));
    const mediaId = (payload.mediaId || "").toString().trim();

    if (!mediaId) {
      return null;
    }

    return {
      mediaId,
      filename: (payload.filename || "WhatsApp image").toString().trim(),
      caption: (payload.caption || "").toString().trim()
    };
  } catch (error) {
    return null;
  }
}

function parseInlineAudioMessage(body) {
  const value = (body || "").toString().trim();

  if (!value.startsWith(INLINE_AUDIO_PREFIX)) {
    return null;
  }

  try {
    const payload = JSON.parse(value.slice(INLINE_AUDIO_PREFIX.length));
    const mediaId = (payload.mediaId || "").toString().trim();

    if (!mediaId) {
      return null;
    }

    return {
      mediaId,
      filename: (payload.filename || "WhatsApp voice note").toString().trim()
    };
  } catch (error) {
    return null;
  }
}

function renderMessageBody(message) {
  const image = parseInlineImageMessage(message?.body || "");
  const audio = parseInlineAudioMessage(message?.body || "");

  if (audio) {
    const audioSrc = "/api/media/" + encodeURIComponent(audio.mediaId);
    return '<div class="inline-audio-message">' +
      '<audio controls preload="none" src="' + audioSrc + '"></audio>' +
      '<div class="inline-audio-filename">🎙️ ' + escapeHtml(audio.filename || "WhatsApp voice note") + '</div>' +
    '</div>';
  }

  if (!image) {
    return escapeHtml(message?.body || "");
  }

  const mediaSrc = "/api/media/" + encodeURIComponent(image.mediaId);
  return '<div class="inline-image-message">' +
    '<a class="inline-image-link" href="' + mediaSrc + '" target="_blank" rel="noopener">' +
      '<img src="' + mediaSrc + '" alt="' + escapeHtml(image.filename || "WhatsApp image") + '" loading="lazy" />' +
    '</a>' +
    (image.caption ? '<div class="inline-image-caption">' + escapeHtml(image.caption) + '</div>' : '') +
  '</div>';
}

function avatarText(phone) {
  const clean = (phone || "IC").replace(/\D/g, "");
  return clean ? clean.slice(-2) : "IC";
}

function conversationKey(phone, phoneNumberId, branch) {
  return (phone || "unknown") + "::" + (phoneNumberId || branch || "line");
}

function branchBadge(branch) {
  if (branch === "Abu Dhabi") return '<span class="branch branch-abu">Abu Dhabi</span>';
  return '<span class="branch branch-dubai">Dubai</span>';
}

function senderBadge(sender) {
  if (sender === "customer") return '<span class="sender-badge sender-customer">Customer</span>';
  if (sender === "staff") return '<span class="sender-badge sender-staff">Staff</span>';
  return '<span class="sender-badge sender-bot">Bot</span>';
}

function renderMessageStatusBadge(message) {
  // V31.5.8.60.3.9.54:
  // UI-only status badge for staff messages. This does not claim real WhatsApp
  // delivered/read receipts. Real delivered/read needs WhatsApp status webhook
  // message_id storage and should be a separate future phase.
  if (!message || message.sender !== "staff") {
    return "";
  }

  const statusText = [message.status || "", message.messageType || ""]
    .join(" ")
    .toLowerCase();

  if (statusText.includes("failed") || statusText.includes("not delivered")) {
    return '<span class="message-status-badge message-status-failed"><span class="tick">!</span> Failed</span>';
  }

  if (statusText.includes("sent") || statusText.includes("human reply") || statusText.includes("image reply") || statusText.includes("voice reply")) {
    return '<span class="message-status-badge"><span class="tick">✓</span> Sent</span>';
  }

  return "";
}

function statusToSenderFilter(status) {
  if (status === "Customer Reply") return "customer";
  if (status === "Human Reply") return "staff";
  if (status === "Bot Reply") return "bot";
  return "";
}

function senderToReplyStatus(sender) {
  if (sender === "customer") return "Customer Reply";
  if (sender === "staff") return "Human Reply";
  if (sender === "bot") return "Bot Reply";
  return "";
}


function messageKey(m) {
  return [m.phone || "", m.time || "", m.sender || "", (m.body || "").slice(0, 30)].join("|");
}

function getMessageTimeValue(message) {
  const value = message?.time || "";
  const direct = new Date(value).getTime();

  if (!Number.isNaN(direct)) {
    return direct;
  }

  return 0;
}

function getConversationReplyFilterStatus(messages) {
  const msgs = messages || [];
  const latestMessage = msgs[0] || {};

  // Filters are based on the latest message in the conversation.
  // customer = Customer Reply, staff = Human Reply, bot = Bot Reply.
  if (latestMessage.sender === "customer") return "Customer Reply";
  if (latestMessage.sender === "staff") return "Human Reply";
  if (latestMessage.sender === "bot") return "Bot Reply";

  return "Customer Reply";
}

function getConversationBusinessStatus(messages, fallbackStatus) {
  const msgs = messages || [];

  // Keep manual workflow statuses separate from reply-type filters.
  const manualStatusMessage = msgs.find(function(m) {
    const s = (m.status || "").toString().trim();
    return (
      s &&
      s !== "Bot" &&
      s !== "Bot Reply" &&
      s !== "Human Reply" &&
      s !== "Customer Reply"
    );
  });

  if (manualStatusMessage && manualStatusMessage.status) {
    return manualStatusMessage.status;
  }

  return fallbackStatus || getConversationReplyFilterStatus(msgs);
}

function buildConversations() {
  const map = {};

  (allMessages || []).forEach(function(m) {
    const key = conversationKey(m.phone || "unknown", m.phoneNumberId || "", m.branch || "");
    const phone = m.phone || "unknown";

    if (!map[key]) {
      map[key] = {
        key,
        phone,
        messages: [],
        latest: m,
        branch: m.branch || "Dubai",
        phoneNumberId: m.phoneNumberId || "",
        status: "Customer Reply",
        replyFilterStatus: "Customer Reply"
      };
    }

    map[key].messages.push(m);

    // allMessages is newest-first, so the first message that creates the conversation is the latest.
    if (!map[key].latest) map[key].latest = m;

    if (m.phoneNumberId) {
      map[key].phoneNumberId = m.phoneNumberId;
    }

    if (m.branch) {
      map[key].branch = m.branch;
    }
  });

  return Object.values(map).map(function(c) {
    const savedState = conversationStateMap[c.key] || {};

    // V31.5.8.29:
    // Keep every conversation internally newest-first.
    // This makes card notifications reliable even when Google Sheet order changes
    // or when an automatic bot reply arrives right after the customer message.
    c.messages = (c.messages || []).slice().sort(function(a, b) {
      return getMessageTimeValue(b) - getMessageTimeValue(a);
    });
    c.latest = c.messages[0] || c.latest || {};

    const customerNameMessage = (c.messages || []).find(function(m) {
      return (m.customerName || "").toString().trim();
    });

    c.customerName = customerNameMessage ? (customerNameMessage.customerName || "").toString().trim() : "";
    c.replyFilterStatus = getConversationReplyFilterStatus(c.messages);
    c.status = savedState.status || getStatusOverride(c.key) || getConversationBusinessStatus(c.messages, c.replyFilterStatus);
    c.assignee = normalizeAssigneeValue(savedState.assignee || getAssignee(c.key, c.branch), c.branch);
    c.tags = normalizeTags(savedState.tags || getTags(c.key));
    c.stateUpdatedAt = savedState.last_updated_at || "";
    c.stateUpdatedBy = savedState.last_updated_by || "";
    return c;
  });
}

function getUnreadCustomerMessageCount(c) {
  if (!c || !Array.isArray(c.messages)) return 0;
  if (typeof isClosedOrArchivedConversation === "function" && isClosedOrArchivedConversation(c)) return 0;

  const readMarker = readMap[c.key] || "";
  let count = 0;

  for (const message of c.messages) {
    if (readMarker && messageKey(message) === readMarker) {
      break;
    }

    if (message.sender === "customer") {
      count += 1;
    }
  }

  return count;
}

function isUnreadConversation(c) {
  return getUnreadCustomerMessageCount(c) > 0;
}

function markConversationRead(key) {
  const c = buildConversations().find(function(item) { return item.key === key; });
  if (!c || !c.latest) return;
  readMap[key] = messageKey(c.latest);
  saveReadMap();
}

function normalizePhoneDigitsClient(value) {
  return (value || "").toString().replace(/\D/g, "");
}

function normalizeLiveBody(value) {
  return (value || "").toString().toLowerCase().replace(/\s+/g, " ").trim();
}

function isInternalNotificationPhone(phone) {
  const value = normalizePhoneDigitsClient(phone);
  if (!value) return false;

  return Array.from(INTERNAL_NOTIFICATION_PHONE_DIGITS).some(function(number) {
    return value === number || value.endsWith(number) || number.endsWith(value);
  });
}

function isOperationalReminderConsentMessage(message) {
  const messageType = normalizeLiveBody(message.messageType);
  const status = normalizeLiveBody(message.status);
  const body = normalizeLiveBody(message.body);

  if ([
    "opt-in",
    "opt-out",
    "reminder opt-in declined",
    "appointment reminder opt-in",
    "appointment reminder declined"
  ].includes(messageType)) {
    return true;
  }

  if ([
    "opted in",
    "opted out",
    "reminder declined",
    "appointment reminder opt-in",
    "appointment reminder declined"
  ].includes(status)) {
    return true;
  }

  return body === "stop" ||
    body === "unsubscribe" ||
    body.includes("yes, i agree to receive appointment reminders and service follow-ups from iconic hair care") ||
    body.includes("yes, i agree to receive appointment reminder and service follow-up from iconic hair care") ||
    body.includes("service follow-up reminders") ||
    body.includes("تذكير / متابعة") ||
    body.includes("أوافق") ||
    body.includes("اوافق") ||
    body.includes("أوافق / yes") ||
    body.includes("اوافق / yes");
}

function isArchivedStatusTextClient(status) {
  const value = (status || "").toString().trim().toLowerCase();
  return value === "archived" || value === "hidden" || value === "hide" || value === "deleted";
}

function isLiveNotificationArchivedMessage(message) {
  if (!message) return false;
  const key = getMessageConversationKey(message);
  const state = conversationStateMap[key] || {};
  const overrideStatus = statusOverrideMap[key] || "";
  return isArchivedStatusTextClient(state.status || "") || isArchivedStatusTextClient(overrideStatus || "");
}

function shouldIncludeInLiveCustomerNotifications(message) {
  if (!message || message.sender !== "customer") return false;
  if (isInternalNotificationPhone(message.phone)) return false;
  if (isOperationalReminderConsentMessage(message)) return false;
  if (isLiveNotificationArchivedMessage(message)) return false;
  return true;
}

function liveToastDedupKey(message) {
  return [
    normalizePhoneDigitsClient(message.phone || ""),
    message.phoneNumberId || "",
    normalizeLiveBody(message.body || "").slice(0, 160)
  ].join("|");
}

function shouldShowLiveToastForMessage(message) {
  const key = liveToastDedupKey(message);
  const now = Date.now();

  Array.from(recentLiveToastMap.keys()).forEach(function(itemKey) {
    if (now - recentLiveToastMap.get(itemKey) > LIVE_TOAST_DEDUP_WINDOW_MS) {
      recentLiveToastMap.delete(itemKey);
    }
  });

  if (recentLiveToastMap.has(key) && now - recentLiveToastMap.get(key) <= LIVE_TOAST_DEDUP_WINDOW_MS) {
    return false;
  }

  recentLiveToastMap.set(key, now);
  return true;
}

function customerNotificationKey(message) {
  return [
    message.phone || "",
    message.phoneNumberId || "",
    message.time || "",
    message.sender || "",
    (message.body || "").toString().slice(0, 80)
  ].join("|");
}

function getCustomerNotificationKeys(messages) {
  return new Set((messages || []).filter(shouldIncludeInLiveCustomerNotifications).slice(0, 500).map(customerNotificationKey));
}

function getUnreadConversationCount() {
  return buildConversations().filter(isUnreadConversation).length;
}

function setLiveNotificationStatusText(text) {
  if (!liveNotificationStatus) return;
  liveNotificationStatus.innerHTML = '<span class="system-dot"></span>' + escapeHtml(text || "Live inbox ready");
}

function updatePageNotificationTitle() {
  if (liveAlertCount > 0) {
    document.title = "(" + liveAlertCount + ") " + originalPageTitle;
  } else {
    document.title = originalPageTitle;
  }
}

function updateLiveNotificationUi() {
  const unreadCount = getUnreadConversationCount();
  const visibleCount = Math.max(unreadCount, liveAlertCount);

  if (liveNotificationCount) {
    liveNotificationCount.textContent = visibleCount > 99 ? "99+" : String(visibleCount);
  }

  if (liveNotificationBtn) {
    liveNotificationBtn.classList.toggle("has-unread", visibleCount > 0);
    liveNotificationBtn.classList.toggle("notifications-enabled", liveNotificationsEnabled);
    liveNotificationBtn.classList.toggle("notifications-disabled", !liveNotificationsEnabled);
    liveNotificationBtn.title = liveNotificationsEnabled
      ? "Open live notifications"
      : "Enable live alerts and open notifications";
    liveNotificationBtn.setAttribute("aria-expanded", liveNotificationPanelOpen ? "true" : "false");
  }

  setLiveNotificationStatusText(liveNotificationsEnabled ? "Live alerts ON" : "Live alerts ready");
  renderLiveNotificationPanel();
  updatePageNotificationTitle();
}

function getLiveToastStack() {
  let stack = document.getElementById("liveToastStack");

  if (!stack) {
    stack = document.createElement("div");
    stack.id = "liveToastStack";
    stack.className = "live-toast-stack";
    document.body.appendChild(stack);
  }

  return stack;
}

function clearLiveNotificationToasts() {
  const stack = document.getElementById("liveToastStack");
  if (stack) stack.innerHTML = "";
}


function getOpenLiveNotificationConversations() {
  return buildConversations().filter(function(conversation) {
    if (!conversation) return false;
    if (typeof isClosedOrArchivedConversation === "function" && isClosedOrArchivedConversation(conversation)) return false;
    return getUnreadCustomerMessageCount(conversation) > 0;
  }).sort(function(a, b) {
    const unreadDiff = getUnreadCustomerMessageCount(b) - getUnreadCustomerMessageCount(a);
    if (unreadDiff) return unreadDiff;
    return getMessageTimeValue(b.latest || {}) - getMessageTimeValue(a.latest || {});
  });
}

function getOpenLiveNotificationTotals(conversations) {
  const list = conversations || getOpenLiveNotificationConversations();
  return list.reduce(function(total, conversation) {
    return total + getUnreadCustomerMessageCount(conversation);
  }, 0);
}

function closeLiveNotificationPanel() {
  liveNotificationPanelOpen = false;
  if (liveNotificationPanel) {
    liveNotificationPanel.classList.remove("is-open");
  }
  if (liveNotificationBtn) {
    liveNotificationBtn.setAttribute("aria-expanded", "false");
  }
}

function openLiveNotificationPanel() {
  liveNotificationPanelOpen = true;
  renderLiveNotificationPanel();
  if (liveNotificationPanel) {
    liveNotificationPanel.classList.add("is-open");
  }
  if (liveNotificationBtn) {
    liveNotificationBtn.setAttribute("aria-expanded", "true");
  }
}

function toggleLiveNotificationPanel() {
  if (liveNotificationPanelOpen) {
    closeLiveNotificationPanel();
  } else {
    openLiveNotificationPanel();
  }
}

function renderLiveNotificationPanel() {
  if (!liveNotificationPanel) return;

  const conversations = getOpenLiveNotificationConversations();
  const unreadTotal = getOpenLiveNotificationTotals(conversations);
  const headerSubtitle = unreadTotal > 0
    ? unreadTotal + " unread customer message" + (unreadTotal === 1 ? "" : "s")
    : "No open unread notifications";

  const header =
    '<div class="live-notification-panel-head">' +
      '<div class="live-notification-panel-title">' +
        '<div class="live-notification-panel-icon">🔔</div>' +
        '<div>' +
          '<strong>Open Notifications</strong>' +
          '<span>' + escapeHtml(headerSubtitle) + '</span>' +
        '</div>' +
      '</div>' +
      '<button type="button" class="live-notification-panel-close" id="liveNotificationPanelClose" aria-label="Close notifications">×</button>' +
    '</div>';

  if (!conversations.length) {
    liveNotificationPanel.innerHTML = header +
      '<div class="live-notification-panel-body">' +
        '<div class="live-notification-empty">' +
          '<strong>All clear</strong>' +
          '<span>No unread open customer notifications right now. Closed and archived conversations stay hidden from this panel.</span>' +
        '</div>' +
      '</div>';
    return;
  }

  liveNotificationPanel.innerHTML = header +
    '<div class="live-notification-panel-body">' +
      conversations.slice(0, 12).map(function(conversation) {
        const latest = conversation.latest || (conversation.messages || [])[0] || {};
        const unreadCount = getUnreadCustomerMessageCount(conversation);
        const displayName = formatConversationDisplayName(conversation);
        const preview = formatConversationPreview(latest) || "New customer message";
        const status = conversation.status || conversation.replyFilterStatus || "Open";
        return '<button type="button" class="live-notification-card" data-live-notification-key="' + escapeHtml(conversation.key) + '">' +
          '<div class="live-notification-avatar">' + escapeHtml(avatarText(displayName || conversation.phone || "IC")) + '</div>' +
          '<div class="live-notification-main">' +
            '<div class="live-notification-name-row">' +
              '<div class="live-notification-name">' + escapeHtml(displayName) + '</div>' +
              '<span class="live-notification-unread-pill">' + escapeHtml(String(unreadCount > 99 ? "99+" : unreadCount)) + '</span>' +
            '</div>' +
            '<div class="live-notification-preview">' + escapeHtml(shortText(preview, 96)) + '</div>' +
            '<div class="live-notification-meta">' +
              '<span>' + escapeHtml(conversation.branch || "Dubai") + '</span>' +
              '<span>' + escapeHtml(status) + '</span>' +
            '</div>' +
          '</div>' +
          '<div class="live-notification-time">' + escapeHtml(latest.time || "") + '</div>' +
        '</button>';
      }).join("") +
    '</div>';
}

function resetVisibleLiveNotifications() {
  resetLiveAlertCounter();
  clearLiveNotificationToasts();
}

function getMessageConversationKey(message) {
  return conversationKey(message.phone || "unknown", message.phoneNumberId || "", message.branch || "");
}

function resetLiveAlertCounter() {
  liveAlertCount = 0;
  updateLiveNotificationUi();
}

function openConversationFromLiveMessage(message) {
  if (!message) return;
  const key = getMessageConversationKey(message);
  selectedConversationKey = key;
  selectedPhone = message.phone || selectedPhone;
  selectedPhoneNumberId = message.phoneNumberId || selectedPhoneNumberId || "";
  markConversationRead(key);
  resetLiveAlertCounter();
  closeLiveNotificationPanel();
  renderAll();
}

function showLiveNotificationToast(message, newCount) {
  if (!message) return;

  const stack = getLiveToastStack();
  const toast = document.createElement("div");
  const branch = message.branch || "Dubai";
  const phone = message.phone || "Unknown";
  const bodyText = (message.body || "").toString().replace(/\s+/g, " ").trim() || "New customer message";
  const title = newCount > 1 ? newCount + " new customer messages" : "New customer message";

  toast.className = "live-toast";
  toast.innerHTML =
    '<div class="live-toast-icon">🔔</div>' +
    '<div>' +
      '<div class="live-toast-title">' + escapeHtml(title) + '</div>' +
      '<div class="live-toast-meta">' + escapeHtml(branch + " • " + phone) + '</div>' +
      '<div class="live-toast-body">' + escapeHtml(bodyText) + '</div>' +
    '</div>';

  toast.addEventListener("click", function() {
    openConversationFromLiveMessage(message);
    toast.remove();
  });

  stack.prepend(toast);

  Array.from(stack.children).slice(LIVE_TOAST_MAX_VISIBLE).forEach(function(item) {
    item.remove();
  });

  window.setTimeout(function() {
    if (toast && toast.parentNode) {
      toast.remove();
    }
  }, 8000);
}

function unlockLiveNotificationSound() {
  try {
    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
    if (!AudioContextClass) return;

    if (!liveNotificationAudioContext) {
      liveNotificationAudioContext = new AudioContextClass();
    }

    if (liveNotificationAudioContext.state === "suspended") {
      liveNotificationAudioContext.resume().catch(function() {});
    }
  } catch (error) {
    // Sound is optional. Keep inbox working even if browser blocks audio.
  }
}

function playLiveNotificationSound() {
  if (!liveNotificationsEnabled) return;

  try {
    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
    if (!AudioContextClass) return;

    if (!liveNotificationAudioContext) {
      liveNotificationAudioContext = new AudioContextClass();
    }

    const ctx = liveNotificationAudioContext;

    if (ctx.state === "suspended") {
      ctx.resume().catch(function() {});
    }

    const oscillator = ctx.createOscillator();
    const gain = ctx.createGain();

    oscillator.type = "sine";
    oscillator.frequency.setValueAtTime(880, ctx.currentTime);
    oscillator.frequency.setValueAtTime(660, ctx.currentTime + 0.12);

    gain.gain.setValueAtTime(0.001, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.16, ctx.currentTime + 0.03);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.22);

    oscillator.connect(gain);
    gain.connect(ctx.destination);

    oscillator.start(ctx.currentTime);
    oscillator.stop(ctx.currentTime + 0.24);
  } catch (error) {
    // Sound is optional. Keep inbox working even if browser blocks audio.
  }
}

function requestBrowserNotificationPermission() {
  if (!("Notification" in window)) return Promise.resolve("unsupported");
  if (Notification.permission !== "default") return Promise.resolve(Notification.permission);
  return Notification.requestPermission().catch(function() {
    return "denied";
  });
}

function showBrowserLiveNotification(message, newCount) {
  if (!liveNotificationsEnabled) return;
  if (!("Notification" in window)) return;
  if (Notification.permission !== "granted") return;
  if (document.visibilityState === "visible") return;

  const branch = message.branch || "Dubai";
  const phone = message.phone || "Unknown";
  const bodyText = (message.body || "").toString().replace(/\s+/g, " ").trim() || "New customer message";

  try {
    const notification = new Notification(newCount > 1 ? newCount + " new Iconic messages" : "New Iconic message", {
      body: branch + " • " + phone + "\\n" + bodyText,
      tag: getMessageConversationKey(message),
      silent: true
    });

    notification.onclick = function() {
      window.focus();
      openConversationFromLiveMessage(message);
      notification.close();
    };
  } catch (error) {
    // Browser notifications are optional.
  }
}

function processLiveInboxNotifications(nextMessages) {
  const newKnownKeys = getCustomerNotificationKeys(nextMessages);
  const newCustomerMessages = (nextMessages || []).filter(function(message) {
    return shouldIncludeInLiveCustomerNotifications(message) && !knownCustomerMessageKeys.has(customerNotificationKey(message));
  });

  if (!liveNotificationsReady) {
    knownCustomerMessageKeys = newKnownKeys;
    liveNotificationsReady = true;
    updateLiveNotificationUi();
    return;
  }

  knownCustomerMessageKeys = newKnownKeys;

  if (!newCustomerMessages.length) {
    updateLiveNotificationUi();
    return;
  }

  const dedupedNewCustomerMessages = newCustomerMessages.filter(shouldShowLiveToastForMessage);

  if (!dedupedNewCustomerMessages.length) {
    updateLiveNotificationUi();
    return;
  }

  const newestMessage = dedupedNewCustomerMessages[0];
  liveAlertCount += dedupedNewCustomerMessages.length;

  showLiveNotificationToast(newestMessage, dedupedNewCustomerMessages.length);
  playLiveNotificationSound();
  showBrowserLiveNotification(newestMessage, dedupedNewCustomerMessages.length);
  updateLiveNotificationUi();
}

const CLOSED_CONVERSATION_STATUS = "Closed";
const ARCHIVED_CONVERSATION_STATUS = "Archived";
const STATIC_COMMAND_CENTER_FILTERS = [
  "needs-action",
  "Need Follow-up",
  "Talk to Team",
  "Waiting",
  "Booking Request"
];
const MAX_DYNAMIC_COMMAND_CENTER_FILTERS = 8;
const REPLY_FILTER_STATUS_VALUES = ["Customer Reply", "Human Reply", "Bot Reply"];
const NOISY_OPERATIONAL_STATUS_VALUES = new Set([
  "",
  "Bot",
  "Follow-up Test",
  "Follow-up Sent",
  "Service Follow-up Reminder",
  "Service Follow-up Template Test",
  "Call Now Test",
  "Call Now Template Test",
  "Location Test",
  "Location CTA Test"
]);
const CLEAN_STATUS_FILTER_GROUPS = [
  {
    label: "Workflow",
    statuses: [
      "Open",
      "Waiting",
      "Need Follow-up",
      "Needs Team",
      "Talk to Team",
      "Closed",
      "Archived"
    ]
  },
  {
    label: "Requests",
    statuses: [
      "Booking Request",
      "Consultation Request",
      "Price Question",
      "Call Requested",
      "Location Requested",
      "Service Interest",
      "Media Requested"
    ]
  },
  {
    label: "Replies",
    statuses: REPLY_FILTER_STATUS_VALUES
  }
];

function isClosedConversation(conversation) {
  return (conversation?.status || "").toString().trim().toLowerCase() === "closed";
}

function isArchivedConversation(conversation) {
  const value = (conversation?.status || "").toString().trim().toLowerCase();
  return value === "archived" || value === "hidden" || value === "hide" || value === "deleted";
}

function isClosedOrArchivedConversation(conversation) {
  return isClosedConversation(conversation) || isArchivedConversation(conversation);
}

function getPrimaryStatusValues() {
  const values = [];
  CLEAN_STATUS_FILTER_GROUPS.forEach(function(group) {
    group.statuses.forEach(function(status) {
      if (!values.includes(status)) values.push(status);
    });
  });
  return values;
}

function isReplyFilterStatus(status) {
  return REPLY_FILTER_STATUS_VALUES.includes((status || "").toString().trim());
}

function isStaticCommandCenterStatus(status) {
  return STATIC_COMMAND_CENTER_FILTERS.includes((status || "").toString().trim());
}

function isCleanOperationalStatus(status) {
  const value = (status || "").toString().trim();
  if (!value) return false;
  if (NOISY_OPERATIONAL_STATUS_VALUES.has(value)) return false;
  if (isReplyFilterStatus(value)) return false;
  if (value === CLOSED_CONVERSATION_STATUS) return false;
  if (value === ARCHIVED_CONVERSATION_STATUS) return false;
  return true;
}

function getCurrentConversationStatus(conversation) {
  return (conversation?.status || "").toString().trim();
}

function getDynamicDetectedStatuses(conversations) {
  const primaryStatuses = getPrimaryStatusValues();
  const detected = [];

  (conversations || []).forEach(function(conversation) {
    const value = getCurrentConversationStatus(conversation);
    if (!value) return;
    if (isClosedOrArchivedConversation(conversation)) return;
    if (!isCleanOperationalStatus(value)) return;
    if (primaryStatuses.includes(value)) return;
    if (!detected.includes(value)) detected.push(value);
  });

  return detected.sort(function(a, b) {
    return a.localeCompare(b);
  });
}

function buildStatusOptions() {
  const current = statusFilter.value;
  const conversations = buildConversations();

  // V31.5.8.60.3.9.58 - Clean + active dynamic Status Filters:
  // Primary filters stay organized. New real current conversation statuses appear under
  // Other detected statuses automatically, while noisy/test/history-only statuses stay hidden.
  const dynamicStatuses = getDynamicDetectedStatuses(conversations);
  const optionHtml = ['<option value="">All status / replies</option>'].concat(CLEAN_STATUS_FILTER_GROUPS.map(function(group) {
    const options = group.statuses.map(function(status) {
      return '<option value="' + escapeHtml(status) + '">' + escapeHtml(status) + '</option>';
    }).join("");

    return '<optgroup label="' + escapeHtml(group.label) + '">' + options + '</optgroup>';
  }));

  if (dynamicStatuses.length) {
    optionHtml.push('<optgroup label="Other detected statuses">' + dynamicStatuses.map(function(status) {
      return '<option value="' + escapeHtml(status) + '">' + escapeHtml(status) + '</option>';
    }).join("") + '</optgroup>');
  }

  statusFilter.innerHTML = optionHtml.join("");

  const validStatuses = getPrimaryStatusValues().concat(dynamicStatuses);
  if (validStatuses.includes(current)) {
    statusFilter.value = current;
  }
}

function buildAdvancedFilterOptions() {
  const currentAssignee = assigneeFilter ? assigneeFilter.value : "";
  const currentTag = tagFilter ? tagFilter.value : "";

  if (assigneeFilter) {
    const assigneeOptions = ["Dubai Team", "Abu Dhabi Team"];
    assigneeFilter.innerHTML = '<option value="">All assigned</option>' + assigneeOptions.map(function(value) {
      return '<option value="' + escapeHtml(value) + '">' + escapeHtml(value) + '</option>';
    }).join("");
    if (assigneeOptions.includes(currentAssignee)) assigneeFilter.value = currentAssignee;
  }

  if (tagFilter) {
    const defaultTags = ["Consultation", "New Customer", "Booking", "Price", "Location", "Follow-up", "Human Support", "Call Requested", "Service Interest", "Media Requested", "Natural Look", "VIP", "Private", "Need Details"];
    const dynamicTags = [];
    buildConversations().forEach(function(c) {
      normalizeTags(c.tags || []).forEach(function(tag) {
        if (!defaultTags.includes(tag) && !dynamicTags.includes(tag)) dynamicTags.push(tag);
      });
    });
    const tagOptions = defaultTags.concat(dynamicTags);
    tagFilter.innerHTML =
      '<option value="">All tags</option>' +
      '<option value="__NO_TAGS__">No tags</option>' +
      tagOptions.map(function(value) {
        return '<option value="' + escapeHtml(value) + '">' + escapeHtml(value) + '</option>';
      }).join("");
    if (currentTag === "__NO_TAGS__" || tagOptions.includes(currentTag)) tagFilter.value = currentTag;
  }
}

function normalizedMessageBranch(message) {
  const branch = (message?.branch || "").toString().trim();
  if (branch === "Abu Dhabi") return "Abu Dhabi";
  return "Dubai";
}

const NEEDS_ACTION_STATUS_VALUES = [
  "Need Follow-up",
  "Talk to Team",
  "Waiting",
  "Booking Request",
  "Call Requested",
  "Price Question"
];

// V31.5.8.60.3.9.60 - Workflow Speed Tools:
// Status buttons already exist. This layer makes the team faster by sorting
// active conversations by operational priority and adding Next / Close & Next.
const WORKFLOW_PRIORITY_STATUS_VALUES = [
  "Talk to Team",
  "Booking Request",
  "Consultation Request",
  "Call Requested",
  "Price Question",
  "Need Follow-up",
  "Waiting",
  "Needs Team",
  "Open",
  "Customer Reply",
  "Human Reply",
  "Bot Reply",
  "Closed",
  "Archived"
];

function getWorkflowPriorityRank(conversation) {
  const status = getCurrentConversationStatus(conversation) || conversation?.replyFilterStatus || "Open";
  const index = WORKFLOW_PRIORITY_STATUS_VALUES.indexOf(status);

  if (index >= 0) return index;
  if (isClosedOrArchivedConversation(conversation)) return 999;
  if (isNeedsActionConversation(conversation)) return 20;
  return 500;
}

function compareConversationsByWorkflowPriority(a, b) {
  const priorityDelta = getWorkflowPriorityRank(a) - getWorkflowPriorityRank(b);
  if (priorityDelta !== 0) return priorityDelta;

  const unreadDelta = getUnreadCustomerMessageCount(b) - getUnreadCustomerMessageCount(a);
  if (unreadDelta !== 0) return unreadDelta;

  return getMessageTimeValue(b?.latest || {}) - getMessageTimeValue(a?.latest || {});
}

function sortConversationsForWorkflow(conversations) {
  return (conversations || []).slice().sort(compareConversationsByWorkflowPriority);
}

// V31.5.8.60.3.9.65 - All view chronological safety:
// The conversation list must feel predictable. "All" and normal status/branch filters
// should follow latest activity date from newest to oldest. Workflow priority sorting is
// kept only for the Needs Action command view and Next/Close & Next helpers.
function compareConversationsByLatestActivity(a, b) {
  const timeDelta = getMessageTimeValue(b?.latest || {}) - getMessageTimeValue(a?.latest || {});
  if (timeDelta !== 0) return timeDelta;

  const unreadDelta = getUnreadCustomerMessageCount(b) - getUnreadCustomerMessageCount(a);
  if (unreadDelta !== 0) return unreadDelta;

  return (formatConversationDisplayName(a) || "").localeCompare(formatConversationDisplayName(b) || "");
}

function sortConversationsByLatestActivity(conversations) {
  return (conversations || []).slice().sort(compareConversationsByLatestActivity);
}

function sortConversationsForCurrentView(conversations) {
  // Only the command-center "Needs Action" view gets priority sorting.
  // All / Dubai / Abu Dhabi / Customer / Bot / Human / Follow-up / Talk to Team
  // remain chronological so dates follow each other visually.
  if (commandCenterFilter === "needs-action") {
    return sortConversationsForWorkflow(conversations);
  }

  return sortConversationsByLatestActivity(conversations);
}

function shouldIncludeInNextWorkflow(conversation) {
  if (!conversation || isClosedOrArchivedConversation(conversation)) return false;
  return isNeedsActionConversation(conversation) ||
    conversation.replyFilterStatus === "Customer Reply" ||
    getCurrentConversationStatus(conversation) === "Open";
}

function conversationMatchesStatusLoose(conversation, status) {
  const wanted = (status || "").toString().toLowerCase().trim();
  if (!wanted || !conversation) return false;

  const directHay = [
    conversation.status,
    conversation.replyFilterStatus,
    conversation.assignee,
    (conversation.tags || []).join(" ")
  ].join(" ").toLowerCase();

  if (directHay.includes(wanted)) return true;

  return (conversation.messages || []).some(function(message) {
    const messageHay = [
      message.status,
      message.messageType,
      message.body,
      message.sender,
      message.customerName,
      message.branch,
      message.buttonText,
      message.buttonTitle,
      message.buttonPayload,
      message.buttonId,
      message.payload,
      message.interactiveTitle,
      message.interactiveId,
      message.interactivePayload
    ].join(" ").toLowerCase();

    return messageHay.includes(wanted);
  });
}

function conversationMatchesActiveOperationalStatus(conversation, status) {
  const wanted = (status || "").toString().trim();
  if (!wanted || !conversation) return false;

  // Closed is a final workflow bucket. Old booking/call/price history must not
  // keep the conversation inside active operational counters or command filters.
  if (isClosedConversation(conversation)) return false;

  // V31.5.8.60.3.9.58:
  // Command Center counters must reflect the current conversation status only.
  // Do not count old message history, old buttons, old template statuses, or body text.
  return getCurrentConversationStatus(conversation) === wanted;
}

function isNeedsActionConversation(conversation) {
  return NEEDS_ACTION_STATUS_VALUES.some(function(status) {
    return conversationMatchesActiveOperationalStatus(conversation, status);
  });
}

function countConversationsByOperationalStatus(conversations, status) {
  return (conversations || []).filter(function(conversation) {
    return conversationMatchesActiveOperationalStatus(conversation, status);
  }).length;
}

function setNeedsActionCounter(id, value) {
  const el = document.getElementById(id);
  if (el) el.textContent = String(value || 0);
}

function getDynamicCommandCenterStatuses(conversations) {
  return getDynamicDetectedStatuses(conversations)
    .map(function(status) {
      return {
        status,
        count: countConversationsByOperationalStatus(conversations, status)
      };
    })
    .filter(function(item) {
      if (isStaticCommandCenterStatus(item.status)) return false;
      return item.count > 0;
    })
    .sort(function(a, b) {
      return b.count - a.count || a.status.localeCompare(b.status);
    })
    .slice(0, MAX_DYNAMIC_COMMAND_CENTER_FILTERS)
    .map(function(item) { return item.status; });
}

function renderDynamicCommandCenterFilters(conversations) {
  if (!dynamicCommandCenterFilters) return;

  const statuses = getDynamicCommandCenterStatuses(conversations);

  if (!statuses.length) {
    dynamicCommandCenterFilters.innerHTML = "";
    return;
  }

  dynamicCommandCenterFilters.innerHTML = statuses.map(function(status) {
    const count = countConversationsByOperationalStatus(conversations, status);
    return '<button type="button" class="dynamic-command-filter" data-command-filter="' + escapeHtml(status) + '" title="Show ' + escapeHtml(status) + '">' +
      '<span>' + escapeHtml(status) + '</span>' +
      '<strong>' + escapeHtml(String(count)) + '</strong>' +
    '</button>';
  }).join("");
}

function updateNeedsActionCommandCenter(conversations) {
  const list = conversations || [];
  setNeedsActionCounter("needsActionCount", list.filter(isNeedsActionConversation).length);
  setNeedsActionCounter("needsFollowupCount", countConversationsByOperationalStatus(list, "Need Follow-up"));
  setNeedsActionCounter("needsTeamCount", countConversationsByOperationalStatus(list, "Talk to Team"));
  setNeedsActionCounter("needsWaitingCount", countConversationsByOperationalStatus(list, "Waiting"));
  setNeedsActionCounter("needsBookingCount", countConversationsByOperationalStatus(list, "Booking Request"));
  renderDynamicCommandCenterFilters(list);
}

function updateStats() {
  const conversations = buildConversations();
  const statTotal = document.getElementById("statTotal");
  const statCustomers = document.getElementById("statCustomers");
  const statUnread = document.getElementById("statUnread");
  if (statTotal) statTotal.textContent = allMessages.length;
  if (statCustomers) statCustomers.textContent = conversations.length;
  if (statUnread) statUnread.textContent = conversations.filter(isUnreadConversation).length;
  const dubaiSidebarCount = allMessages.filter(function(m) { return normalizedMessageBranch(m) === "Dubai"; }).length;
  const abuSidebarCount = allMessages.filter(function(m) { return normalizedMessageBranch(m) === "Abu Dhabi"; }).length;
  const statDubai = document.getElementById("statDubai");
  const statAbu = document.getElementById("statAbu");
  if (statDubai) statDubai.textContent = dubaiSidebarCount;
  if (statAbu) statAbu.textContent = abuSidebarCount;
  const sideDubaiCount = document.getElementById("sideDubaiCount");
  const sideAbuCount = document.getElementById("sideAbuCount");
  if (sideDubaiCount) sideDubaiCount.textContent = dubaiSidebarCount;
  if (sideAbuCount) sideAbuCount.textContent = abuSidebarCount;
  const tabDubaiCount = document.getElementById("tabDubaiCount");
  const tabAbuCount = document.getElementById("tabAbuCount");
  const conversationBranchCounts = buildConversations().reduce(function(acc, c) {
    if (c.branch === "Abu Dhabi") acc.abu += 1;
    else acc.dubai += 1;
    return acc;
  }, { dubai: 0, abu: 0 });
  if (tabDubaiCount) tabDubaiCount.textContent = conversationBranchCounts.dubai;
  if (tabAbuCount) tabAbuCount.textContent = conversationBranchCounts.abu;
  applyBranchScopeUiVisibility();
  updateNeedsActionCommandCenter(conversations);
  updateLiveNotificationUi();
}

function conversationHasStatus(conversation, wantedStatus) {
  const wanted = (wantedStatus || "").toLowerCase().trim();
  if (!wanted) return true;

  if (wanted === "needs team") {
    const workflowHay = [
      conversation.status,
      conversation.replyFilterStatus,
      conversation.assignee,
      (conversation.tags || []).join(" ")
    ].join(" ").toLowerCase();

    if (
      workflowHay.includes("need details") ||
      workflowHay.includes("consultation") ||
      workflowHay.includes("booking") ||
      workflowHay.includes("human support") ||
      workflowHay.includes("talk to team") ||
      workflowHay.includes("call requested") ||
      workflowHay.includes("price") ||
      workflowHay.includes("consultation team")
    ) {
      return true;
    }
  }

  return (conversation.messages || []).some(function(message) {
    const combined = [
      message.status,
      message.messageType,
      message.body,
      message.sender,
      message.phone,
      message.customerName,
      message.branch,
      message.phoneNumberId,
      message.buttonText,
      message.buttonTitle,
      message.buttonPayload,
      message.buttonId,
      message.payload,
      message.interactiveTitle,
      message.interactiveId,
      message.interactivePayload
    ].join(" ").toLowerCase();

    const status = (message.status || "").toLowerCase().trim();
    const messageType = (message.messageType || "").toLowerCase().trim();

    if (status === wanted || messageType === wanted) return true;

    // Searches the full conversation, including button/body/status/message type fields.
    if (wanted === "talk to team") {
      return combined.includes("talk to team") ||
        combined.includes("team handoff") ||
        combined.includes("chat with team") ||
        combined.includes("talk_to_team") ||
        combined.includes("الفريق") ||
        combined.includes("فريق");
    }

    if (wanted === "needs team") {
      return combined.includes("need details") ||
        combined.includes("booking request") ||
        combined.includes("consultation request") ||
        combined.includes("price question") ||
        combined.includes("call requested") ||
        combined.includes("human support") ||
        combined.includes("talk to team") ||
        combined.includes("team handoff") ||
        combined.includes("استشارة") ||
        combined.includes("موعد") ||
        combined.includes("فريق");
    }

    // One clean filter for all follow-up activity; test/status noise stays hidden from the dropdown.
    if (wanted === "follow-up") {
      return combined.includes("follow-up") ||
        combined.includes("follow up") ||
        combined.includes("followup") ||
        combined.includes("service follow-up") ||
        combined.includes("service_review_follow_up") ||
        combined.includes("review_follow_up") ||
        combined.includes("reminder") ||
        combined.includes("تذكير") ||
        combined.includes("متابعة");
    }

    return false;
  });
}

function filteredConversations() {
  const q = (searchBox.value || "").toLowerCase().trim();
  const branch = branchFilter.value;
  const status = statusFilter.value;
  const assigned = assigneeFilter ? assigneeFilter.value : "";
  const tag = tagFilter ? tagFilter.value : "";
  const activeCommandFilter = commandCenterFilter || "";
  const senderFilter = statusToSenderFilter(status);

  return sortConversationsForCurrentView(buildConversations().filter(function(c) {
    const hay = [
      c.phone,
      c.branch,
      c.status,
      c.replyFilterStatus,
      c.assignee,
      (c.tags || []).join(" "),
      c.phoneNumberId
    ].concat((c.messages || []).map(function(m) {
      return [
        m.body,
        m.status,
        m.messageType,
        m.sender,
        m.phone,
        m.customerName,
        m.branch,
        m.phoneNumberId,
        m.buttonText,
        m.buttonTitle,
        m.buttonPayload,
        m.buttonId,
        m.payload,
        m.interactiveTitle,
        m.interactiveId,
        m.interactivePayload
      ].join(String.fromCharCode(10));
    })).join(" ").toLowerCase();

    if (!showArchivedConversations && isArchivedConversation(c)) return false;
    if (q && !hay.includes(q)) return false;
    if (branch && c.branch !== branch) return false;

    if (activeCommandFilter === "needs-action" && !isNeedsActionConversation(c)) return false;
    if (activeCommandFilter && activeCommandFilter !== "needs-action") {
      if (!conversationMatchesActiveOperationalStatus(c, activeCommandFilter)) return false;
    }

    if (assigned && c.assignee !== assigned) return false;

    const conversationTags = normalizeTags(c.tags || []);
    if (tag === "__NO_TAGS__" && conversationTags.length > 0) return false;
    if (tag && tag !== "__NO_TAGS__" && !conversationTags.includes(tag)) return false;

    // Reply filters are message-type filters.
    // Customer Reply / Human Reply / Bot Reply search the full conversation.
    if (senderFilter) {
      return (c.messages || []).some(function(m) { return m.sender === senderFilter; });
    }

    if (status) {
      if (isCleanOperationalStatus(status)) {
        if (!conversationMatchesActiveOperationalStatus(c, status)) return false;
      } else if (c.status !== status && !conversationHasStatus(c, status)) {
        return false;
      }
    }

    return true;
  }));
}
function formatConversationDisplayName(c) {
  const messages = c.messages || [];
  const withName = messages.find(function(m) {
    return (m.customerName || "").toString().trim();
  });

  const name = withName ? (withName.customerName || "").toString().trim() : "";
  if (name) return name;
  return c.phone || "Unknown customer";
}

function formatConversationPreview(message) {
  if (!message) return "";
  const senderLabel = message.sender === "customer" ? "Customer" : message.sender === "staff" ? "Team" : message.sender === "bot" ? "Bot" : "Message";
  const image = parseInlineImageMessage(message.body || "");

  if (image) {
    return senderLabel + ": 📷 Image" + (image.caption ? " — " + image.caption : "");
  }

  const body = (message.body || "").toString().replace(/\s+/g, " ").trim();
  return senderLabel + ": " + body;
}

function renderConversationList() {
  const conversations = filteredConversations();

  if (!conversations.length) {
    var emptyTitle = showArchivedConversations ? 'No archived conversations' : 'No conversations found';
    var emptyHint = showArchivedConversations ? 'Archived chats will appear here after you archive them.' : 'Try another name, phone number, or keyword.';
    conversationList.innerHTML = '<div class="empty inbox-empty-state actual-empty-state">'
      + '<div class="empty-state-icon empty-state-icon-search" aria-hidden="true"></div>'
      + '<h3>' + emptyTitle + '</h3>'
      + '<p>' + emptyHint + '</p>'
      + '</div>';
    selectedPhone = "";
    selectedConversationKey = "";
    renderChat();
    updateReferenceFilterUi(0);
    return;
  }

  if (!selectedConversationKey || !conversations.some(function(c) { return c.key === selectedConversationKey; })) {
    selectedConversationKey = conversations[0].key;
    selectedPhone = conversations[0].phone;
    selectedPhoneNumberId = conversations[0].phoneNumberId || "";
  }

  conversationList.innerHTML = conversations.map(function(c) {
    const active = c.key === selectedConversationKey ? " active" : "";
    const unreadCustomerCount = getUnreadCustomerMessageCount(c);
    const unread = unreadCustomerCount > 0 ? " unread card-live-alert" : "";
    const listSenderFilter = statusToSenderFilter(statusFilter.value);
    const filteredLatest = listSenderFilter ? (c.messages || []).find(function(m) { return m.sender === listSenderFilter; }) : null;
    const latest = filteredLatest || c.latest || {};
    const displayStatus = listSenderFilter ? senderToReplyStatus(latest.sender) : (c.status || "");
    const preview = formatConversationPreview(latest);
    const displayName = formatConversationDisplayName(c);
    const messageCount = (c.messages || []).length;
    const liveBadge = unreadCustomerCount > 0
      ? '<span class="live-card-badge"><span class="live-card-dot"></span>New ' + escapeHtml(String(unreadCustomerCount > 99 ? "99+" : unreadCustomerCount)) + '</span>'
      : '';
    const tagRow = (c.tags || []).length ? '<div class="conversation-tags-row">' + tagBadges(c.tags, "conversation-tag-chip", 3) + '</div>' : '';

    return '<button type="button" class="conversation-card reference-conversation-card' + active + unread + '" data-key="' + escapeHtml(c.key) + '" data-status="' + escapeHtml(displayStatus || '') + '">' +
      '<div class="avatar reference-avatar">' + escapeHtml(avatarText(displayName || c.phone)) + '</div>' +
      '<div class="conversation-main reference-conversation-main">' +
        '<div class="conv-top reference-card-top">' +
          '<div class="conv-identity reference-card-identity">' +
            '<div class="conv-name reference-card-name">' + escapeHtml(displayName) + '</div>' +
            '<div class="conv-preview reference-card-preview">' + escapeHtml(shortText(preview, 76)) + '</div>' +
          '</div>' +
          '<div class="reference-card-side">' +
            '<div class="conv-time reference-card-time">' + escapeHtml(latest.time || "") + '</div>' +
            liveBadge +
          '</div>' +
        '</div>' +
        '<div class="conv-footer reference-card-footer">' +
          '<div class="badges reference-card-badges">' + branchBadge(c.branch) + '<span class="status ' + statusClass(displayStatus) + '">' + escapeHtml(displayStatus || "") + '</span>' + tagBadges(c.tags || [], "conversation-tag-chip", 1) + '</div>' +
          '<span class="message-count-badge">' + escapeHtml(String(messageCount)) + '</span>' +
        '</div>' +
      '</div>' +
    '</button>';
  }).join("");

  Array.from(document.querySelectorAll(".conversation-card")).forEach(function(btn) {
    btn.addEventListener("click", function() {
      selectConversation(btn.dataset.key || "");
    });
  });

  updateReferenceFilterUi(conversations.length);
  syncArchivedToggleButton();
}

function selectConversation(key) {
  const c = buildConversations().find(function(item) { return item.key === key; });
  if (!c) return;

  selectedConversationKey = c.key;
  selectedPhone = c.phone;
  selectedPhoneNumberId = c.phoneNumberId || "";
  inputTo.value = c.phone;
  inputLine.value = c.phoneNumberId || "";
  markConversationRead(c.key);
  renderAll();
  inputBody.focus();
}

function getNextWorkflowConversation(excludeKey) {
  const currentView = sortConversationsForWorkflow(filteredConversations()).filter(function(c) {
    return c.key !== excludeKey && shouldIncludeInNextWorkflow(c);
  });

  if (currentView.length) return currentView[0];

  return sortConversationsForWorkflow(buildConversations()).filter(function(c) {
    return c.key !== excludeKey && shouldIncludeInNextWorkflow(c);
  })[0] || null;
}

function openNextWorkflowConversation(options) {
  const opts = options || {};
  const nextConversation = getNextWorkflowConversation(opts.excludeKey || selectedConversationKey || "");

  if (!nextConversation) {
    resultBox.textContent = "No active customer waiting right now.";
    renderAll();
    return false;
  }

  selectedConversationKey = nextConversation.key;
  selectedPhone = nextConversation.phone;
  selectedPhoneNumberId = nextConversation.phoneNumberId || "";
  inputTo.value = nextConversation.phone;
  inputLine.value = nextConversation.phoneNumberId || "";
  markConversationRead(nextConversation.key);
  resultBox.textContent = "Opened next customer: " + formatConversationDisplayName(nextConversation);
  renderAll();
  inputBody.focus();
  return true;
}

async function closeCurrentAndOpenNext() {
  if (!selectedConversationKey) {
    resultBox.textContent = "Select a customer first.";
    return false;
  }

  await updateStatus("Closed", { selectNextAfterUpdate: true });
}

async function archiveOrRestoreCurrentConversation() {
  if (!selectedConversationKey) {
    resultBox.textContent = "Select a customer first.";
    return false;
  }

  const currentConversation = getCurrentConversationForState();
  const shouldRestore = isArchivedConversation(currentConversation);

  if (shouldRestore) {
    await updateStatus("Open", { forceReloadAfterUpdate: true });
    resultBox.textContent = "Conversation restored to Open.";
    return true;
  }

  const ok = window.confirm("Archive this conversation from the active inbox? You can show archived conversations again from the Archive button.");
  if (!ok) return false;

  markConversationRead(selectedConversationKey);
  resetVisibleLiveNotifications();
  await updateStatus("Archived", { selectNextAfterUpdate: true });
  return true;
}

function renderChat() {
  const c = buildConversations().find(function(item) { return item.key === selectedConversationKey; });

  if (!c) {
    chatTitle.textContent = "Select a conversation";
    chatMeta.innerHTML = "";
    chatAvatar.textContent = "IC";
    if (conversationStatusSelect) {
      conversationStatusSelect.value = "Open";
      conversationStatusSelect.disabled = true;
    }
    if (archiveConversationBtn) {
      archiveConversationBtn.disabled = true;
      archiveConversationBtn.textContent = "Archive";
    }
    if (chatTagsMenuBtn) chatTagsMenuBtn.disabled = true;
    closeChatTagsPopover();
    if (assigneeSelect) {
      assigneeSelect.value = "Dubai Team";
      assigneeSelect.disabled = true;
    }
    if (assigneeDisplay) {
      assigneeDisplay.className = "assignee-chip assignee-dubai";
      assigneeDisplay.textContent = "Assigned: —";
    }
    syncTagPicker([]);
    document.body.classList.add("no-conversation-selected-mode");
    updateCustomerProfile(null);
    lastRenderedConversationKeyForScroll = null;
    chatBody.innerHTML = '<div class="chat-watermark"><img src="/assets/iconic-chat-background-logo.png" alt="Iconic Hair Care watermark" /></div>'
      + '<div class="empty chat-empty-state actual-empty-state actual-chat-empty">'
      + '<div class="empty-state-icon empty-state-icon-chat" aria-hidden="true"></div>'
      + '<h3>Select a conversation</h3>'
      + '<p>Choose a customer from the left list to view the full chat history and CRM profile.</p>'
      + '</div>';
    return;
  }

  document.body.classList.remove("no-conversation-selected-mode");
  const displayName = formatConversationDisplayName(c);
  chatTitle.textContent = displayName;
  chatAvatar.textContent = avatarText(displayName || c.phone);
  const headerTags = normalizeTags(c.tags || []);
  const headerTagsHtml = headerTags.length ? tagBadges(headerTags, "tag-chip", 3) : "";
  chatMeta.innerHTML = branchBadge(c.branch) + '<span class="status ' + statusClass(c.status) + '">' + escapeHtml(c.status || "") + '</span>' + headerTagsHtml + '<div class="workflow-status-bar"><span class="workflow-status-chip ' + statusClass(c.status) + '">Workflow: ' + escapeHtml(c.status || "Open") + '</span>' + assigneeBadge(c.assignee) + '</div>';
  if (conversationStatusSelect) {
    const allowedStatuses = ["Open", "Waiting", "Need Follow-up", "Needs Team", "Booking Request", "Consultation Request", "Price Question", "Call Requested", "Location Requested", "Service Interest", "Media Requested", "Talk to Team", "Closed", "Archived"];
    conversationStatusSelect.value = allowedStatuses.includes(c.status) ? c.status : "Open";
    conversationStatusSelect.disabled = false;
  }
  if (archiveConversationBtn) {
    archiveConversationBtn.disabled = false;
    archiveConversationBtn.textContent = isArchivedConversation(c) ? "Restore" : "Archive";
    archiveConversationBtn.setAttribute("title", isArchivedConversation(c) ? "Restore this conversation to Open" : "Archive this conversation from the active inbox");
  }
  if (chatTagsMenuBtn) chatTagsMenuBtn.disabled = false;
  if (assigneeSelect) {
    assigneeSelect.value = normalizeAssigneeValue(c.assignee, c.branch);
    assigneeSelect.disabled = false;
  }
  if (assigneeDisplay) {
    assigneeDisplay.className = "assignee-chip " + assigneeClass(normalizeAssigneeValue(c.assignee, c.branch));
    assigneeDisplay.textContent = "Assigned: " + normalizeAssigneeValue(c.assignee, c.branch);
  }
  syncTagPicker(c.tags || []);
  updateCustomerProfile(c);

  const chatScrollSnapshot = getChatScrollSnapshot();
  const openedDifferentConversation = lastRenderedConversationKeyForScroll !== c.key;

  inputTo.value = c.phone;
  if (c.phoneNumberId) inputLine.value = c.phoneNumberId;

  const ordered = (c.messages || []).slice().reverse();

  // Reply-type filters affect both the conversation list and the opened chat.
  // All conversations = full history. Customer/Human/Bot Reply = only that sender.
  const chatSenderFilter = statusToSenderFilter(statusFilter.value);
  const visibleMessages = chatSenderFilter
    ? ordered.filter(function(m) { return m.sender === chatSenderFilter; })
    : ordered;

  chatBody.innerHTML = '<div class="chat-watermark"><img src="/assets/iconic-chat-background-logo.png" alt="Iconic Hair Care watermark" /></div>' + (visibleMessages.length ? visibleMessages.map(function(m) {
    const cls = m.sender === "customer" ? "customer" : (m.sender === "staff" ? "staff" : "bot");
    return '<div class="bubble-row ' + cls + '">' +
      '<div class="bubble ' + cls + '">' +
        renderMessageBody(m) +
        '<div class="bubble-info">' +
          '<span>' + senderBadge(m.sender || "") + '</span>' +
          '<span>' + escapeHtml(m.time || "") + '</span>' +
          renderMessageStatusBadge(m) +
        '</div>' +
      '</div>' +
    '</div>';
  }).join("") : '<div class="empty">No messages for this filter.</div>');

  restoreChatScrollSnapshot(chatScrollSnapshot, openedDifferentConversation);
  lastRenderedConversationKeyForScroll = c.key;
}

function renderAll() {
  buildStatusOptions();
  buildAdvancedFilterOptions();
  updateStats();
  renderConversationList();
  renderChat();
}

function buildBrowserInboxRenderSignature(messages, conversationStates, bookingRequests) {
  // V31.5.8.60.3.9.59:
  // Prevent the visible chat window from being rebuilt every auto-refresh cycle.
  // The previous 5-second full render caused a visual shake/flicker even when
  // the data did not actually change. This signature is intentionally based on
  // lightweight, user-visible fields only.
  const messagePart = (messages || []).slice(0, 800).map(function(message) {
    return [
      message.phone || "",
      message.phoneNumberId || "",
      message.time || "",
      message.sender || "",
      message.status || "",
      message.messageType || "",
      (message.body || "").toString().slice(0, 120)
    ].join("~");
  }).join("||");

  const statePart = (conversationStates || []).map(function(state) {
    return [
      state.phone || "",
      state.phoneNumberId || "",
      state.conversation_status || "",
      state.assigned_to || "",
      state.tags || "",
      state.last_updated_at || ""
    ].join("~");
  }).join("||");

  const bookingPart = (bookingRequests || []).map(function(booking) {
    return [
      booking.rowNumber || "",
      booking.phone || "",
      booking.phoneNumberId || "",
      booking.status || "",
      booking.notes || "",
      booking.lastUpdated || ""
    ].join("~");
  }).join("||");

  return [
    (messages || []).length,
    (conversationStates || []).length,
    (bookingRequests || []).length,
    messagePart,
    statePart,
    bookingPart
  ].join("::");
}

let lastBrowserInboxRenderSignature = "";
let lastBrowserRenderedAt = 0;

function browserMessageMergeKey(message) {
  return [
    message.phone || "",
    message.phoneNumberId || "",
    message.time || "",
    message.sender || "",
    (message.body || "").toString().slice(0, 300),
    message.messageType || ""
  ].join("|");
}

function mergeBrowserMessages(primaryMessages, fallbackMessages) {
  const merged = new Map();

  (primaryMessages || []).forEach(function(message) {
    const key = browserMessageMergeKey(message);
    if (key.trim() && !merged.has(key)) merged.set(key, message);
  });

  (fallbackMessages || []).forEach(function(message) {
    const key = browserMessageMergeKey(message);
    if (key.trim() && !merged.has(key)) merged.set(key, message);
  });

  return Array.from(merged.values()).sort(function(a, b) {
    return getMessageTimeValue(b) - getMessageTimeValue(a);
  });
}

let messagesLoadInFlight = false;
let messagesReloadQueued = false;
let messagesReloadQueuedOptions = null;

async function loadMessages(options) {
  const loadOptions = options || {};

  if (messagesLoadInFlight) {
    messagesReloadQueued = true;
    messagesReloadQueuedOptions = Object.assign({}, messagesReloadQueuedOptions || {}, loadOptions);
    return;
  }

  messagesLoadInFlight = true;

  try {
    const messagesUrl = "/api/messages" + (showArchivedConversations ? "?archiveOnly=1" : "");
    const res = await fetch(messagesUrl, { cache: "no-store" });
    const data = await res.json();
    const nextMessages = data.messages || [];
    const nextConversationStates = data.conversationStates || [];
    const nextBookingRequests = data.bookingRequests || allBookingRequests || [];
    const nextMessageCount = nextMessages.length;
    const currentMessageCount = (allMessages || []).length;

    // History guard: never replace a visible working inbox with an empty/partial response.
    // Archive view intentionally returns fewer rows, so it must not merge back active inbox messages.
    const shouldPreserveBrowserHistory = !showArchivedConversations && currentMessageCount > 0 && nextMessageCount < currentMessageCount;
    const safeMessages = shouldPreserveBrowserHistory
      ? mergeBrowserMessages(nextMessages, allMessages)
      : nextMessages;

    // Apply states before live notification processing so archived conversations never
    // contribute to unread/live alert counters.
    applyConversationStates(nextConversationStates);

    const nextRenderSignature = buildBrowserInboxRenderSignature(safeMessages, nextConversationStates, nextBookingRequests);
    const shouldRender = Boolean(loadOptions.forceRender) || nextRenderSignature !== lastBrowserInboxRenderSignature;

    processLiveInboxNotifications(safeMessages);
    allMessages = safeMessages;
    allBookingRequests = nextBookingRequests;

    if (shouldRender) {
      lastBrowserInboxRenderSignature = nextRenderSignature;
      lastBrowserRenderedAt = Date.now();
      renderAll();
    } else {
      // Keep live counters/title fresh without rebuilding the open chat DOM.
      updateLiveNotificationUi();
    }
  } catch (error) {
    console.log("Failed to load messages:", error);
    // Do not clear the visible conversation list on temporary network/API delay.
  } finally {
    messagesLoadInFlight = false;

    if (messagesReloadQueued) {
      const queuedOptions = messagesReloadQueuedOptions || {};
      messagesReloadQueued = false;
      messagesReloadQueuedOptions = null;
      setTimeout(function() { loadMessages(queuedOptions); }, 250);
    }
  }
}

async function sendReply() {
  const to = inputTo.value.trim();
  const body = inputBody.value.trim();
  const phoneNumberId = inputLine.value.trim();

  if (!to || !body) {
    resultBox.textContent = "Please enter customer phone and message.";
    return;
  }

  resultBox.textContent = "Sending...";

  try {
    const res = await fetch("/api/send", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ to, body, phoneNumberId })
    });

    const data = await res.json();

    if (data.ok) {
      resultBox.textContent = "Sent successfully.";
      inputBody.value = "";
      selectedPhone = to;
      selectedConversationKey = selectedConversationKey || conversationKey(to, phoneNumberId, "");
      markConversationRead(selectedConversationKey);
      loadMessages({ forceRender: true, reason: "action" });
    } else {
      resultBox.textContent = data.error || "فشل الإرسال / لم تصل للعميل.";
      loadMessages({ forceRender: true, reason: "action" });
    }
  } catch (error) {
    resultBox.textContent = "Failed: network or server error.";
  }
}


function fileToDataUrl(file) {
  return new Promise(function(resolve, reject) {
    const reader = new FileReader();
    reader.onload = function() { resolve(reader.result); };
    reader.onerror = function() { reject(new Error("Could not read image file.")); };
    reader.readAsDataURL(file);
  });
}

async function sendImage() {
  const to = inputTo.value.trim();
  const phoneNumberId = inputLine.value.trim();
  const file = imageFileInput && imageFileInput.files ? imageFileInput.files[0] : null;
  const caption = imageCaptionInput ? imageCaptionInput.value.trim() : "";

  if (!to) {
    resultBox.textContent = "Select a customer first.";
    return;
  }

  if (!file) {
    resultBox.textContent = "Please choose an image first.";
    return;
  }

  if (!["image/jpeg", "image/png", "image/webp"].includes(file.type)) {
    resultBox.textContent = "Please use JPG, PNG, or WEBP only.";
    return;
  }

  if (file.size > 5 * 1024 * 1024) {
    resultBox.textContent = "Image is too large. Please choose an image under 5MB.";
    return;
  }

  resultBox.textContent = "Uploading image...";

  try {
    const imageDataUrl = await fileToDataUrl(file);
    const res = await fetch("/api/send-image", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        to,
        phoneNumberId,
        imageDataUrl,
        filename: file.name,
        mimeType: file.type,
        caption
      })
    });

    const data = await res.json();

    if (data.ok) {
      resultBox.textContent = "Image sent successfully.";
      imageFileInput.value = "";
      const imagePicker = document.querySelector(".composer-image-picker");
      if (imagePicker) imagePicker.classList.remove("has-selected-image");
      if (imageCaptionInput) imageCaptionInput.value = "";
      selectedPhone = to;
      selectedConversationKey = selectedConversationKey || conversationKey(to, phoneNumberId, "");
      markConversationRead(selectedConversationKey);
      loadMessages({ forceRender: true, reason: "action" });
    } else {
      resultBox.textContent = "Failed: " + (data.error || "Image send failed");
    }
  } catch (error) {
    resultBox.textContent = "Failed: image upload error.";
  }
}

async function sendVoice() {
  const to = inputTo.value.trim();
  const phoneNumberId = inputLine.value.trim();
  const file = audioFileInput && audioFileInput.files ? audioFileInput.files[0] : null;
  const allowedAudioTypes = ["audio/aac", "audio/mp4", "audio/mpeg", "audio/amr", "audio/ogg", "audio/x-m4a", "audio/m4a"];

  if (!to) {
    resultBox.textContent = "Select a customer first.";
    return;
  }

  if (!file) {
    resultBox.textContent = "Please choose a voice note first.";
    return;
  }

  const fileNameForType = (file.name || "").toLowerCase();
  const looksLikeAudioFile = /\.(aac|m4a|mp4|mp3|amr|ogg|opus)$/i.test(fileNameForType);

  if (file.type && !allowedAudioTypes.includes(file.type) && !looksLikeAudioFile) {
    resultBox.textContent = "Please use AAC, M4A/MP4, MP3, AMR, or OGG audio only.";
    return;
  }

  if (file.size > 16 * 1024 * 1024) {
    resultBox.textContent = "Voice note is too large. Please choose audio under 16MB.";
    return;
  }

  resultBox.textContent = "Uploading voice note...";

  try {
    const audioDataUrl = await fileToDataUrl(file);
    const res = await fetch("/api/send-audio", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        to,
        phoneNumberId,
        audioDataUrl,
        filename: file.name || "iconic-voice-note.ogg",
        mimeType: file.type || "audio/ogg"
      })
    });

    const data = await res.json();

    if (data.ok) {
      resultBox.textContent = "Voice note sent successfully.";
      audioFileInput.value = "";
      const voicePicker = document.querySelector(".composer-voice-picker");
      if (voicePicker) voicePicker.classList.remove("has-selected-voice");
      selectedPhone = to;
      selectedConversationKey = selectedConversationKey || conversationKey(to, phoneNumberId, "");
      markConversationRead(selectedConversationKey);
      loadMessages({ forceRender: true, reason: "action" });
    } else {
      resultBox.textContent = "Failed: " + (data.error || "Voice send failed");
    }
  } catch (error) {
    resultBox.textContent = "Failed: voice upload error.";
  }
}

async function updateStatus(status, options) {
  const updateOptions = options || {};
  const phone = inputTo.value.trim() || selectedPhone;
  if (!phone) {
    resultBox.textContent = "Select a customer first.";
    return;
  }

  resultBox.textContent = "Updating status...";

  try {
    const res = await fetch("/api/status", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ phone, status })
    });

    const data = await res.json();

    if (data.ok) {
      const key = selectedConversationKey || conversationKey(phone, inputLine.value.trim(), "");
      setStatusOverride(key, status);
      const currentConversation = getCurrentConversationForState();
      if (currentConversation) {
        currentConversation.status = status;
        await saveConversationStateToGoogleSheet(currentConversation);
      }
      if (conversationStatusSelect) conversationStatusSelect.value = status;
      if (isArchivedStatusTextClient(status) || (status || "").toString().trim().toLowerCase() === "closed") {
        markConversationRead(key);
        resetVisibleLiveNotifications();
      }
      resultBox.textContent = "Status updated: " + status;
      if (updateOptions.selectNextAfterUpdate) {
        openNextWorkflowConversation({ excludeKey: key });
        loadMessages({ forceRender: true, reason: "action" });
      } else {
        loadMessages({ forceRender: true, reason: "action" });
      }
      return true;
    } else {
      resultBox.textContent = "Failed: " + (data.error || "Unknown error");
      return false;
    }
  } catch (error) {
    resultBox.textContent = "Failed: status update error.";
    return false;
  }
}

